CREATE PROCEDURE [dbo].[tai_vw_sp2_insert_autorizaciones]   @DocEntry     integer  ,@OpCom      nvarchar(16)  ,@AutorizacionCredito  integer  ,@AutorizacionDocProtestado integer  ,@AutorizacionMargen  integer  ,@AutorizacionCosto   integer  ,@ContadorCredito   integer  ,@ContadorDocProtestado  integer  ,@ContadorMargen   integer  ,@ContadorCosto    integer  ,@AutorizacionFactura  integer  ,@ContadorFactura   integer  ,@AutorizacionBM1   integer  ,@ContadorBM1    integer  ,@AutorizacionBM2   integer  ,@ContadorBM2    integer  ,@AutorizacionBM3   integer  ,@ContadorBM3    integer  ,@AutorizacionBC1   integer  ,@ContadorBC1    integer  ,@AutorizacionBC2   integer  ,@ContadorBC2    integer  ,@AutorizacionBC3   integer  ,@ContadorBC3    integer  ,@Mje_Op     nvarchar(600)  ,@Mje_Aut     nvarchar(600)  ,@Rechaza     nvarchar(20)  ,@AutorizacionTasa   integer  ,@ContadorTasa    integer  AS  BEGIN   insert into tai_tb_autorizaciones( DocEntry, OpCom, AutorizacionCredito, AutorizacionDocProtestado, AutorizacionMargen, AutorizacionCosto, ContadorCredito, ContadorDocProtestado, ContadorMargen, ContadorCosto, AutorizacionFactura, ContadorFactura, AutorizacionBM1, ContadorBM1, AutorizacionBM2, ContadorBM2, AutorizacionBM3, ContadorBM3, AutorizacionBC1, ContadorBC1, AutorizacionBC2, ContadorBC2, AutorizacionBC3, ContadorBC3, Mje_Op, Mje_Aut, Rechaza, AutorizacionTasa, ContadorTasa)                                 values(@DocEntry,@OpCom,@AutorizacionCredito,@AutorizacionDocProtestado,@AutorizacionMargen,@AutorizacionCosto,@ContadorCredito,@ContadorDocProtestado,@ContadorMargen,@ContadorCosto,@AutorizacionFactura,@ContadorFactura,@AutorizacionBM1,@ContadorBM1,@AutorizacionBM2,@ContadorBM2,@AutorizacionBM3,@ContadorBM3,@AutorizacionBC1,@ContadorBC1,@AutorizacionBC2,@ContadorBC2,@AutorizacionBC3,@ContadorBC3,@Mje_Op,@Mje_Aut,@Rechaza,@AutorizacionTasa,@ContadorTasa)  END
  CREATE PROCEDURE [dbo].[tai_vw_sp2_insert_comision_detalle_provisorio]  AS  BEGIN   declare @FecRetencion datetime   declare @añoActual    int      declare @mesActual    int         declare @diaActual    int     set @FecRetencion=getdate()      set @añoActual   =year(getdate())      set @mesActual   =month(getdate())      set @diaActual   =day(getdate())          --if @diaActual<=7    --begin    --set @mesActual=@mesActual-1     --if @mesActual=0    --begin    -- set @añoActual=@añoActual-1    -- set @mesActual=12    --end    --end          --select @añoActual año, @mesActual mes         drop table comision_detalle_provisorio   create table comision_detalle_provisorio(      CodOficina   int     ,Oficina   nvarchar(200)     ,TD     varchar(3)     ,Serie    nvarchar(16)     ,Año    int     ,Mes    int     ,Dia    int     ,Fecha    datetime     ,NDocSAP   int     ,Ind    nvarchar(4)     ,Folio    int     ,Titular   nvarchar(200)     ,CodOperador  int     ,Operador   nvarchar(310)     ,CodSN    nvarchar(30)     ,NombreSN   nvarchar(200)     ,Grupo    varchar(50)     ,CodLinea   smallint     ,Linea    nvarchar(40)     ,SubLinea   nvarchar(60)     ,Producto   nvarchar(40)     ,Descripción  nvarchar(200)     ,Cantidad   numeric(19,6)     ,Costo    numeric(19,6)     ,[Costo Total]  numeric(19,6)     ,WhsCode   nvarchar(16)     ,UnidadMedida  nvarchar(40)     ,PVUnitNeto   numeric(19,6)     ,ImpteNetoML  numeric(19,6)     ,Comision   numeric(19,6)     ,Envase    nvarchar(60)     ,KgLt    varchar(6)     ,Capacidad         numeric(19,6)     ,CodigoProv       nvarchar(30)     ,NombreProveedor nvarchar(200)     ,Creacion         datetime     ,CuartaCopia     datetime     ,[Comis%]         numeric(19,6)     ,[Comis%Est]     numeric(19,6)     ,Margen             numeric(19,6)     ,PrctMargenMin     numeric(19,6)     ,PrctComisVtas     numeric(19,6)     ,PrctComisEsp     numeric(19,6)     ,BaseComis         char(1)     ,PrctBajoMargen     numeric(19,6)     ,TopeComision     numeric(19,6)     ,PorcFlete         numeric(19,6)     ,PrctComiOpEsp     numeric(19,6)     ,PrctComision     numeric(19,6)     ,VtaMarCompartida int     ,VtaCodOperador     int     ,VtaNomOperador     nvarchar(310)     ,Descripcion        nvarchar(100)     ,ComFinal           numeric(19,6)     ,FecCarga           datetime   )         insert into comision_detalle_provisorio   select COM.*      ,(case when COM.BaseComis='V' then COM.ImpteNetoML else COM.Margen end)*(COM.[Comis%Est]/100) TotComision      ,@FecRetencion                                                                                FecCarga     from TAI_VW_comision_detalle COM     where COM.Mes=@mesActual      and COM.Año=@añoActual       update comision_detalle_provisorio      set [Comis%Est] =EXC.com_valor      ,BaseComis   =EXC.com_base      ,PrctComision=EXC.com_valor      ,ComFinal    =(case when EXC.com_base='V' then DET.ImpteNetoML else DET.Margen end)*(EXC.com_valor/100)        from comision_excluyente         EXC       inner join comision_detalle DET on DET.CodOperador=EXC.id_operador and DET.CodLinea=EXC.id_linea    where DET.Mes=@mesActual      and DET.Año=@añoActual          /*   insert into comision_detalle_provisorio   select COM.*     ,(case      when COM.TopeComision>0 then       (case when (COM.Margen/COM.ImpteNetoML)>(COM.TopeComision/100) then        (COM.ImpteNetoML*COM.[Comis%Est]*COM.TopeComision)/10000        else         (COM.Margen     *COM.[Comis%Est]                 )/100        end)      else       (case when COM.BaseComis='V' then        (COM.ImpteNetoML*COM.[Comis%Est])/100        else        (COM.Margen     *COM.[Comis%Est])/100        end)           end)          TotComision      ,@FecRetencion                      FecCarga     from TAI_VW_comision_detalle COM     where COM.Mes=@mesActual      and COM.Año=@añoActual  */        /*   update comision_detalle_provisorio      set [Comis%Est]  =14.50      ,PrctComisVtas=14.50      ,PrctComision =14.50      ,ComFinal=(Margen*14.5)/100    where VtaMarCompartida=0      and CodOperador     =236      and CodLinea        in (113,114,115,125,127,128,133)         update comision_detalle_provisorio      set [Comis%Est]  =7.25      ,PrctComisVtas=7.25      ,PrctComision =7.25      ,ComFinal=(Margen*7.25)/100    where VtaMarCompartida=2      and CodOperador     =236      and CodLinea        in (113,114,115,125,127,128,133)                         update comision_detalle_provisorio      set [Comis%Est]  =12.20      ,PrctComisVtas=12.20      ,PrctComision =12.20      ,ComFinal=(Margen*12.20)/100    where VtaMarCompartida=0      and CodOperador     =187      and CodLinea        in (113,114,115,125,127,128,133)         update comision_detalle_provisorio      set [Comis%Est]  =6.10      ,PrctComisVtas=6.10      ,PrctComision =6.10      ,ComFinal=(Margen*6.10)/100    where VtaMarCompartida=2      and CodOperador     =187      and CodLinea        in (113,114,115,125,127,128,133)                       update comision_detalle_provisorio      set [Comis%Est]  =12.20      ,PrctComisVtas=12.20      ,PrctComision =12.20      ,ComFinal=(Margen*12.20)/100    where VtaMarCompartida=0      and CodOperador     =343      and CodLinea        in (113,114,115,125,127,128,133)         update comision_detalle_provisorio      set [Comis%Est]  =6.10      ,PrctComisVtas=6.10      ,PrctComision =6.10      ,ComFinal=(Margen*6.10)/100    where VtaMarCompartida=2      and CodOperador     =343      and CodLinea        in (113,114,115,125,127,128,133)                        update comision_detalle_provisorio      set [Comis%Est]  =12.20      ,PrctComisVtas=12.20      ,PrctComision =12.20      ,ComFinal=(Margen*12.20)/100    where VtaMarCompartida=0      and CodOperador     =146      and CodLinea        in (113,114,115,125,127,128,133)         update comision_detalle_provisorio      set [Comis%Est]  =6.10      ,PrctComisVtas=6.10      ,PrctComision =6.10      ,ComFinal=(Margen*6.10)/100    where VtaMarCompartida=2      and CodOperador     =146      and CodLinea        in (113,114,115,125,127,128,133)                             update comision_detalle_provisorio      set [Comis%Est]  =12.20      ,PrctComisVtas=12.20      ,PrctComision =12.20      ,ComFinal=(Margen*12.20)/100    where VtaMarCompartida=0      and CodOperador     =330      and CodLinea        in (113,114,115,125,127,128,133)         update comision_detalle_provisorio      set [Comis%Est]  =6.10      ,PrctComisVtas=6.10      ,PrctComision =6.10      ,ComFinal=(Margen*6.10)/100    where VtaMarCompartida=2      and CodOperador     =330      and CodLinea        in (113,114,115,125,127,128,133)              update comision_detalle_provisorio      set [Comis%Est]  =12.20      ,PrctComisVtas=12.20      ,PrctComision =12.20      ,ComFinal=(Margen*12.20)/100    where VtaMarCompartida=0      and CodOperador     =188      and CodLinea        in (113,114,115,125,127,128,133)         update comision_detalle_provisorio      set [Comis%Est]  =6.10      ,PrctComisVtas=6.10      ,PrctComision =6.10      ,ComFinal=(Margen*6.10)/100    where VtaMarCompartida=2      and CodOperador     =188      and CodLinea        in (113,114,115,125,127,128,133)             update comision_detalle_provisorio      set [Comis%Est]  =12.20      ,PrctComisVtas=12.20      ,PrctComision =12.20      ,ComFinal=(Margen*12.20)/100    where VtaMarCompartida=0      and CodOperador     =223      and CodLinea        in (113,114,115,125,127,128,133)         update comision_detalle_provisorio      set [Comis%Est]  =6.10      ,PrctComisVtas=6.10      ,PrctComision =6.10      ,ComFinal=(Margen*6.10)/100    where VtaMarCompartida=2      and CodOperador     =223      and CodLinea        in (113,114,115,125,127,128,133)       */                   update comision_detalle_provisorio       set ComFinal =0        where TD      <>'NCV'      and BaseComis='M'      and abs(ImpteNetoML)<[Costo Total]      and CodLinea<>117     update comision_detalle_provisorio       set ComFinal =0     where TD       ='NCV'      and BaseComis='M'      and abs(ImpteNetoML)<[Costo Total]      and CodLinea<>117         update comision_detalle_provisorio      set ComFinal=0    where TD      <>'NCV'      and BaseComis='M'      and abs(ImpteNetoML)<[Costo Total]         and exists(select id_operador from comision_nuevo where id_operador=CodOperador)         update comision_detalle_provisorio      set ComFinal=0    where TD       ='NCV'      and BaseComis='M'      and abs(ImpteNetoML)<[Costo Total]      and exists(select id_operador from comision_nuevo where id_operador=CodOperador)       END
CREATE PROCEDURE [dbo].[tai_vw_sp2_insert_dispatcher]   @id                 nvarchar(64)   ,@codigo_borrador    integer   ,@codigo_autorizador nvarchar(16)  ,@tipo_autorizacion  nvarchar(40)  ,@aut_backup         nvarchar(30)  AS  BEGIN   declare @estado_Autorizacion as integer   declare @comentarioautoriza  as nvarchar(600)   set @estado_Autorizacion=0   set @comentarioautoriza =''   insert into tai_tb_dispatcher( Id, Codigo_Borrador, Codigo_Autorizador, Tipo_Autorizacion, Estado_Autorizacion, Fecha_Creacion, ComentarioAutoriza, Aut_Backup, Fecha_Actualizacion)                          values(@id,@codigo_borrador,@codigo_autorizador,@tipo_autorizacion,@estado_Autorizacion, getdate(),     @comentarioautoriza,@aut_backup, null)  END
  CREATE PROCEDURE [dbo].[tai_vw_sp2_select_autorizacion]   @opcion         integer  ,@operador       varchar(20)   ,@bodega         varchar(20)  ,@producto       varchar(30)  ,@fechaPedido    varchar(8)  ,@precioUnitario numeric(19,2)  ,@tipoVenta      varchar(3)    AS  BEGIN   declare @zona                nvarchar(20)   declare @sucursal            nvarchar(20)   if @opcion=10   begin    declare @codigoLinea         integer    declare @OpCom               numeric(19,6)    declare @BM1                 numeric(19,6)    declare @BM2                 numeric(19,6)    declare @BC1                 numeric(19,6)    declare @BC2                 numeric(19,6)    declare @costoComercial      numeric(19,6)    declare @precioLista         numeric(19,6)     --declare @porcentajeMargenComercial numeric(19,6)    declare @margenComercial     numeric(19,6)        --declare @puestoFundo         nvarchar(1)      set @codigoLinea=(select ItmsGrpCod       from OITM                                            where ItemCode =@producto)    set @sucursal   =(select T1.Name          from OUSR T0 inner join OUBR T1 on T0.Branch=T1.Code where USER_CODE=@operador)    set @zona       =(select top 1 U_TAI_Zona from [@TAI_AUT_BM_BC1]                               where Code     =@codigoLinea and U_TAI_Sucursal=@sucursal)     --set @puestoFundo=(select U_TAI_VtaCalzada from OWHS                                            where WhsCode  =@bodega)      set @costoComercial=(select case when T0.U_TAI_Moneda='CLP' then T0.U_TAI_CostoComercial else T0.U_TAI_CostoComercial*T1.Rate end              from OITW T0 left join ORTT T1 on T0.U_TAI_Moneda=T1.Currency and T1.RateDate=@fechaPedido           where T0.ItemCode=@producto          and T0.WhsCode =@bodega         )            set @precioLista=(select case when T0.U_TAI_Moneda='CLP' then T0.U_TAI_PrecioVenta else T0.U_TAI_PrecioVenta*T1.Rate end          from OITW T0 left join ORTT T1 on T0.U_TAI_Moneda=T1.Currency and T1.RateDate=@fechaPedido           where T0.ItemCode=@producto          and T0.WhsCode =@bodega         )          --set @porcentajeMargenComercial=(select case     --                   when @precioLista   =0 and @costoComercial=0 then 0    --                   when @costoComercial=0                       then -100    --                   else (1-(@costoComercial/@precioLista))*100    --                     end    --             )      set @margenComercial=(@precioLista-@costoComercial)      set @OpCom=(select @precioLista-(@margenComercial*U_TAI_OpCom/100) from [@TAI_AUT_BM_BC] where Code=@codigoLinea)   --Devuelve precio hasta el que llega el operador comercial      if @precioUnitario<@OpCom-1    begin     select @BM1=@precioLista-(@margenComercial*U_TAI_BM1/100)        ,@BM2=@precioLista-(@margenComercial*U_TAI_BM2/100)        ,@BC1=@precioLista-(@margenComercial*U_TAI_BC1/100)        ,@BC2=@precioLista-(@margenComercial*U_TAI_BC2/100)       from [@TAI_AUT_BM_BC]       where Code=@codigoLinea             if @precioUnitario<@OpCom and @precioUnitario>=@BM1                                  --Jefe Oficina      - D2     begin      select T0.U_TAI_User as DisOficial, T0.U_TAI_CodAut as DisTipo, T0.U_TAI_Backup as DisBackup from [@TAI_AUT_BM_BC1] T0 inner join [@TAI_AUT_BM_BC] T1 on T0.code=T1.code where U_TAI_CodAut='BM1' and U_TAI_sucursal=@sucursal and T0.Code=@codigoLinea and T1.U_TAI_BM1<>0     end     else if @precioUnitario<@BM1 and @precioUnitario>=@BM2                               --Gerente Zonal     - D3     begin      select T0.U_TAI_User as DisOficial, T0.U_TAI_CodAut as DisTipo, T0.U_TAI_Backup as DisBackup from [@TAI_AUT_BM_BC1] T0 inner join [@TAI_AUT_BM_BC] T1 on T0.code=T1.code where U_TAI_CodAut='BM2' and U_TAI_Zona=@zona and T0.Code=@codigoLinea and T1.U_TAI_BM2<>0     end     else if @precioUnitario<@BM2 and @precioUnitario>=@BC1                              --Gerente Linea     - D4     begin       --select T0.U_TAI_User as DisOficial, T0.U_TAI_CodAut as DisTipo, T0.U_TAI_Backup as DisBackup from [@TAI_AUT_BM_BC1] T0 inner join [@TAI_AUT_BM_BC] T1 on T0.code=T1.code where U_TAI_CodAut='BC1' and T0.Code=@codigoLinea and T1.U_TAI_BC1<>0      select (case when T0.Code in(101,102,103,117) and @tipoVenta not in('VCE','VLB') then 'ecanales' else T0.U_TAI_User end) as DisOficial, T0.U_TAI_CodAut as DisTipo, (case when T0.Code in(101,102,103,117) and @tipoVenta not in('VCE','VLB') then 'KScherpf' else T0.U_TAI_Backup end) as DisBackup from [@TAI_AUT_BM_BC1] T0 inner join [@TAI_AUT_BM_BC] T1 on T0.code=T1.code where T0.U_TAI_CodAut='BC1' and T0.Code=@codigoLinea and T1.U_TAI_BC1<>0     end     else if @precioUnitario<@BC1 and (@precioUnitario>=@BC2 or (@precioUnitario<@BC2))   --Gerente Comercial - D5     begin       --select T0.U_TAI_User as DisOficial, T0.U_TAI_CodAut as DisTipo, T0.U_TAI_Backup as DisBackup from [@TAI_AUT_BM_BC1] T0 inner join [@TAI_AUT_BM_BC] T1 on T0.code=T1.code where U_TAI_CodAut='BC1' and T0.Code=@codigoLinea and T1.U_TAI_BC1<>0      select (case when T0.Code in(101,102,103,117) and @tipoVenta not in('VCE','VLB') then 'ecanales' else T0.U_TAI_User end) as DisOficial, T0.U_TAI_CodAut as DisTipo, (case when T0.Code in(101,102,103,117) and @tipoVenta not in('VCE','VLB') then 'KScherpf' else T0.U_TAI_Backup end) as DisBackup from [@TAI_AUT_BM_BC1] T0 inner join [@TAI_AUT_BM_BC] T1 on T0.code=T1.code where T0.U_TAI_CodAut='BC1' and T0.Code=@codigoLinea and T1.U_TAI_BC1<>0      union all       select T0.U_TAI_User as DisOficial, T0.U_TAI_CodAut as DisTipo, T0.U_TAI_Backup as DisBackup from [@TAI_AUT_BM_BC1] T0 inner join [@TAI_AUT_BM_BC] T1 on T0.code=T1.code where U_TAI_CodAut='BC2' and T0.Code=@codigoLinea and T1.U_TAI_BC2<>0     end    end   end   if @opcion=20   begin    set @sucursal=(select T1.Name          from OUSR T0 JOIN OUBR T1 on T0.Branch = T1.Code where USER_CODE     =@operador)    set @zona    =(select top 1 U_TAI_Zona from [@TAI_AUT_BM_BC1]                           where U_TAI_Sucursal=@sucursal)    select isnull(AUT.U_TAI_User,'')          DisOficial     --,isnull(upper(AUT.U_TAI_Nombre),'') NomAutorizador       ,'TASA'                             DisTipo       ,isnull(AUT.U_TAI_Backup,'')        DisBackup      --,isnull(upper(BKP.U_NAME),'')       NomBackup       from OITM ART         inner join [@TAI_AUT_BM_BC1] AUT on AUT.Code     =ART.ItmsGrpCod        left join  OUSR              BKP on BKP.USER_CODE=AUT.U_TAI_Backup     where AUT.U_TAI_Cargo   ='JO'        and AUT.U_TAI_Sucursal=@sucursal         and ART.ItemCode      =@producto     union all  /*    select isnull(AUT.U_TAI_User,'')          DisOficial     --,isnull(upper(AUT.U_TAI_Nombre),'') NomAutorizador       ,'TASA'                             DisTipo       ,isnull(AUT.U_TAI_Backup,'')        DisBackup      --,isnull(upper(BKP.U_NAME),'')       NomBackup       from OITM ART         inner join [@TAI_AUT_BM_BC1] AUT on AUT.Code     =ART.ItmsGrpCod        left join  OUSR              BKP on BKP.USER_CODE=AUT.U_TAI_Backup     where AUT.U_TAI_Cargo='GL'        and ART.ItemCode   =@producto  */    select (case when AUT.Code in(101,102,103,117) and @tipoVenta not in('VCE','VLB') then 'ecanales' else isnull(AUT.U_TAI_User,'')   end) DisOficial     --,isnull(upper(AUT.U_TAI_Nombre),'') NomAutorizador       ,'TASA'                                                                                                              DisTipo       ,(case when AUT.Code in(101,102,103,117) and @tipoVenta not in('VCE','VLB') then 'KScherpf' else isnull(AUT.U_TAI_Backup,'') end) DisBackup      --,isnull(upper(BKP.U_NAME),'')       NomBackup       from OITM ART         inner join [@TAI_AUT_BM_BC1] AUT on AUT.Code     =ART.ItmsGrpCod        left join  OUSR              BKP on BKP.USER_CODE=AUT.U_TAI_Backup     where AUT.U_TAI_Cargo='GL'        and ART.ItemCode   =@producto    union all       select isnull(AUT.U_TAI_User,'')          DisOficial     --,isnull(upper(AUT.U_TAI_Nombre),'') NomAutorizador       ,'TASA'                             DisTipo       ,isnull(AUT.U_TAI_Backup,'')        DisBackup      --,isnull(upper(BKP.U_NAME),'')       NomBackup       from OITM ART         inner join [@TAI_AUT_BM_BC1] AUT on AUT.Code     =ART.ItmsGrpCod        left join  OUSR              BKP on BKP.USER_CODE=AUT.U_TAI_Backup     where AUT.U_TAI_Cargo='GZ'        and AUT.U_TAI_Zona =@zona       and ART.ItemCode   =@producto     end  END
  create PROCEDURE [dbo].[tai_vw_sp2_select_autorizacion_descto]   @opcion         integer  ,@operador       varchar(20)   ,@bodega         varchar(20)  ,@producto       varchar(30)  ,@fechaPedido    varchar(8)  ,@precioUnitario numeric(19,2)  ,@tipoVenta      varchar(3)    AS  BEGIN      declare @codigoLinea         integer   declare @codigosucursal      integer   declare @codigozona          varchar(1)         declare @precioLista         numeric(19,2)     declare @Dx                  numeric(19,2)     declare @D0                  numeric(19,2)   declare @D1                  numeric(19,2)   declare @D2                  numeric(19,2)   declare @D3                  numeric(19,2)   declare @D4                  numeric(19,2)       if @opcion=10   begin    --declare @precioLista         numeric(19,2)            set @precioLista=(         select case when T0.U_TAI_Moneda='CLP' then T0.U_TAI_PrecioVenta else T0.U_TAI_PrecioVenta*T1.Rate end            from OITW           T0                 left join ORTT T1 on T0.U_TAI_Moneda=T1.Currency and T1.RateDate=@fechaPedido             where T0.ItemCode=@producto            and T0.WhsCode =@bodega         )          if @precioUnitario<@precioLista    begin     --declare @Dx                  numeric(19,2)       --declare @D0                  numeric(19,2)     --declare @D1                  numeric(19,2)     --declare @D2                  numeric(19,2)     --declare @D3                  numeric(19,2)     --declare @D4                  numeric(19,2)       select @codigoLinea=ItmsGrpCod       from OITM      where ItemCode=@producto         select @codigosucursal=Branch       from OUSR      where USER_CODE=@operador       select top 1          @codigozona=det_codzona       from matriz_descto_detalle      where det_codlinea   =@codigoLinea        and det_codsucursal=@codigosucursal       set @Dx=100*(1-@precioUnitario/@precioLista)       select @D0=res_nivel0        ,@D1=res_nivel1        ,@D2=res_nivel2        ,@D3=res_nivel3        ,@D4=res_nivel4       from matriz_descto_resumen       where res_codlinea=@codigoLinea       --select @Dx as Dx, @D0 as D0, @D1 as D1, @D2 as D2, @D3 as D3, @D4 as D4, @precioLista as PrecioLista, @precioUnitario as PrecioUnitario       if @Dx>@D0 and @Dx<=@D1          --JO - D1     begin      select distinct T0.det_codusuario as DisOficial, T0.det_codautorizacion as DisTipo, T0.det_codbackup as DisBackup from matriz_descto_detalle T0 inner join matriz_descto_resumen T1 on T0.det_codlinea=T1.res_codlinea where T0.det_codautorizacion='D1' and T0.det_codsucursal=@codigosucursal and T0.det_codlinea=@codigoLinea and T1.res_nivel1<>0     end     else if @Dx>@D1 and @Dx<=@D2     --GZ - D2     begin      select distinct T0.det_codusuario as DisOficial, T0.det_codautorizacion as DisTipo, T0.det_codbackup as DisBackup from matriz_descto_detalle T0 inner join matriz_descto_resumen T1 on T0.det_codlinea=T1.res_codlinea where T0.det_codautorizacion='D2' and T0.det_codzona    =@codigozona     and T0.det_codlinea=@codigoLinea and T1.res_nivel2<>0     end     else if @Dx>@D2 and @Dx<=@D3  --GL - D3     begin      select distinct T0.det_codusuario as DisOficial, T0.det_codautorizacion as DisTipo, T0.det_codbackup as DisBackup from matriz_descto_detalle T0 inner join matriz_descto_resumen T1 on T0.det_codlinea=T1.res_codlinea where T0.det_codautorizacion='D3' and T0.det_codlinea=@codigoLinea and T1.res_nivel3<>0     end     else if @Dx>@D3                  --GC - D4     begin      select distinct T0.det_codusuario as DisOficial, T0.det_codautorizacion as DisTipo, T0.det_codbackup as DisBackup from matriz_descto_detalle T0 inner join matriz_descto_resumen T1 on T0.det_codlinea=T1.res_codlinea where T0.det_codautorizacion='D4' and T0.det_codlinea=@codigoLinea and T1.res_nivel4<>0     end    end   end   if @opcion=15   begin    --declare @precioLista         numeric(19,2)            set @precioLista=(         select case when T0.U_TAI_Moneda='CLP' then T0.U_TAI_PrecioVenta else T0.U_TAI_PrecioVenta*T1.Rate end            from OITW           T0                 left join ORTT T1 on T0.U_TAI_Moneda=T1.Currency and T1.RateDate=@fechaPedido             where T0.ItemCode=@producto            and T0.WhsCode =@bodega         )          if @precioUnitario<@precioLista    begin     --declare @Dx                  numeric(19,2)       --declare @D0                  numeric(19,2)     --declare @D1                  numeric(19,2)     --declare @D2                  numeric(19,2)     --declare @D3                  numeric(19,2)     --declare @D4                  numeric(19,2)       select @codigoLinea=ItmsGrpCod       from OITM      where ItemCode=@producto         select @codigosucursal=Branch       from OUSR      where USER_CODE=@operador       select top 1          @codigozona=det_codzona       from matriz_descto_detalle      where det_codlinea   =@codigoLinea        and det_codsucursal=@codigosucursal       set @Dx=100*(1-@precioUnitario/@precioLista)       select @D0=res_nivel0        ,@D1=res_nivel1        ,@D2=res_nivel2        ,@D3=res_nivel3        ,@D4=res_nivel4       from matriz_descto_resumen       where res_codlinea=@codigoLinea       --select @Dx as Dx, @D0 as D0, @D1 as D1, @D2 as D2, @D3 as D3, @D4 as D4, @precioLista as PrecioLista, @precioUnitario as PrecioUnitario       if @Dx>@D0     begin      select distinct T0.det_codusuario as DisOficial, T0.det_codautorizacion as DisTipo, T0.det_codbackup as DisBackup from matriz_descto_detalle T0 inner join matriz_descto_resumen T1 on T0.det_codlinea=T1.res_codlinea where T0.det_codautorizacion='D1' and T0.det_codsucursal=@codigosucursal and T0.det_codlinea=@codigoLinea and T1.res_nivel1<>0 and (@Dx>@D0)      union      select distinct T0.det_codusuario as DisOficial, T0.det_codautorizacion as DisTipo, T0.det_codbackup as DisBackup from matriz_descto_detalle T0 inner join matriz_descto_resumen T1 on T0.det_codlinea=T1.res_codlinea where T0.det_codautorizacion='D2' and T0.det_codzona    =@codigozona     and T0.det_codlinea=@codigoLinea and T1.res_nivel2<>0 and (@Dx>@D1)      union      select distinct T0.det_codusuario as DisOficial, T0.det_codautorizacion as DisTipo, T0.det_codbackup as DisBackup from matriz_descto_detalle T0 inner join matriz_descto_resumen T1 on T0.det_codlinea=T1.res_codlinea where T0.det_codautorizacion='D3' and T0.det_codlinea=@codigoLinea and T1.res_nivel3<>0                                        and (@Dx>@D2)      union         select distinct T0.det_codusuario as DisOficial, T0.det_codautorizacion as DisTipo, T0.det_codbackup as DisBackup from matriz_descto_detalle T0 inner join matriz_descto_resumen T1 on T0.det_codlinea=T1.res_codlinea where T0.det_codautorizacion='D4' and T0.det_codlinea=@codigoLinea and T1.res_nivel4<>0                                        and (@Dx>@D3)      order by T0.det_codautorizacion     end    end   end   if @opcion=20   begin    select @codigosucursal=Branch         from OUSR     where USER_CODE=@operador      select top 1            @codigozona=det_codzona      from matriz_descto_detalle     where det_codsucursal=@codigosucursal      select isnull(AUT.det_codusuario,'')      DisOficial       ,'VENTAS'                           DisTipo       ,isnull(AUT.det_codbackup,'')       DisBackup       from OITM ART         inner join matriz_descto_detalle AUT on AUT.det_codlinea =ART.ItmsGrpCod        left join  OUSR                  BKP on BKP.USER_CODE    =AUT.det_codbackup     where AUT.det_codcargo   ='JO'        and AUT.det_codsucursal=@codigosucursal         and ART.ItemCode       =@producto      union all         select isnull(AUT.det_codusuario,'')      DisOficial       ,'VENTAS'                           DisTipo       ,isnull(AUT.det_codbackup,'')       DisBackup       from OITM ART         inner join matriz_descto_detalle AUT on AUT.det_codlinea=ART.ItmsGrpCod        left join  OUSR                  BKP on BKP.USER_CODE   =AUT.det_codbackup     where AUT.det_codcargo='GZ'        and AUT.det_codzona =@codigozona       and ART.ItemCode    =@producto           union all      select (case when AUT.det_codlinea in(101,102,103,117) and @tipoVenta not in('VCE','VLB') then 'ecanales' else isnull(AUT.det_codusuario,'')   end) DisOficial       ,'VENTAS'                                                                                                                                     DisTipo       ,(case when AUT.det_codlinea in(101,102,103,117) and @tipoVenta not in('VCE','VLB') then 'KScherpf' else isnull(AUT.det_codbackup,'')    end) DisBackup       from OITM ART         inner join matriz_descto_detalle AUT on AUT.det_codlinea=ART.ItmsGrpCod        left join  OUSR                  BKP on BKP.USER_CODE   =AUT.det_codbackup     where AUT.det_codcargo='GL'        and ART.ItemCode    =@producto      union all      select isnull(AUT.det_codusuario,'')      DisOficial       ,'VENTAS'                           DisTipo       ,isnull(AUT.det_codbackup,'')       DisBackup       from OITM ART         inner join matriz_descto_detalle AUT on AUT.det_codlinea=ART.ItmsGrpCod        left join  OUSR                  BKP on BKP.USER_CODE   =AUT.det_codbackup     where AUT.det_codcargo='GG'        and ART.ItemCode    =@producto       and @tipoVenta in('VCP','VCE')   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_autorizacion_especial]   @opcion      integer  ,@autorizador varchar(20)   AS  BEGIN   if @opcion=10   begin     select OWTM.Name       as AutCodigo          ,OWTM.Remarks    as AutDescripcion          ,OWST.MaxRejReqr as EstRechazoRequerido          ,OWST.MaxReqr    as EstAutorizacionRequerido          ,OUS2.USER_CODE  as AutNombre          ,case when OWST.maxrejReqr = 1                 then 'Backup'               else 'Encadenamiento'             end             as ConRechazo            ,case when OWST.MaxReqr = 1                then 'Backup'               else 'Encadenamiento'             end             as ConAutorizacion    from WTM1        inner join OUSR      on OUSR.USERID=WTM1.UserID         inner join OWTM      on OWTM.WtmCode=WTM1.WtmCode           inner join WTM3      on WTM3.WtmCode=WTM1.WtmCode           inner join WTM2      on WTM2.WtmCode=OWTM.WtmCode           inner join OWST      on OWST.WstCode=WTM2.WstCode           inner join WST1      on WST1.WstCode=OWST.WstCode           inner join OUSR OUS2 on OUS2.USERID =WST1.UserID        where OUSR.USER_CODE=@autorizador       and OWTM.Active   ='Y'       and WTM3.TransType in (17, 13)       and OUS2.USER_CODE not in ('oramirez', 'mpalma', 'jlatorre', 'aherrera')       end    END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_autorizaciones]  @DocEntry integer  AS  BEGIN   select DocEntry      ,OpCom               ,AutorizacionCredito      ,AutorizacionDocProtestado      ,AutorizacionMargen         ,AutorizacionCosto      ,AutorizacionFactura      ,AutorizacionBM1      ,AutorizacionBM2      ,AutorizacionBM3      ,AutorizacionBC1      ,AutorizacionBC2      ,AutorizacionBC3      ,AutorizacionTasa               ,ContadorCredito      ,ContadorDocProtestado      ,ContadorMargen      ,ContadorCosto      ,ContadorFactura      ,ContadorBM1      ,ContadorBM2      ,ContadorBM3      ,ContadorBC1      ,ContadorBC2      ,ContadorBC3      ,ContadorTasa           ,isnull(Mje_Op,'')  as Mje_Op      ,isnull(Mje_Aut,'') as Mje_Aut      ,isnull(Rechaza,'') as Rechaza        from tai_tb_autorizaciones    where DocEntry=@DocEntry  END  
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_autorizador]   @opcion      integer  ,@autorizador varchar(20)   AS  BEGIN   if @opcion=10   begin    select OHEM.firstName + ' ' + OHEM.lastName AutNombre          ,OHEM.jobTitle                        AutCargo          ,OHEM.email                           AutCorreo      from OHEM              inner join OUSR on OUSR.USERID=OHEM.userId        where OUSR.USER_CODE=@autorizador     end   END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_bodega]   @opcion   integer  ,@operador varchar(20)  AS  BEGIN   if @opcion=10   begin    if (@operador not in('amozo','mundurra'))     select upper(ASIG.U_WhsCode)   as BodCodigo       ,upper(ASIG.U_WhsName)   as BodNombre       ,ASIG.U_DfltWhs          as BodDefecto       ,OWHS.U_TAI_ConsigCompra as BodConsignado       ,OWHS.U_TAI_VtaCalzada   as BodVtaCalzada      from [@VK_WHUD] ASIG       inner join OWHS on OWHS.WhsCode=ASIG.U_WhsCode      where ASIG.U_WhsCode<>'00'      and ASIG.Code=@operador      order by ASIG.U_WhsCode desc    else     select upper(ASIG.U_WhsCode)   as BodCodigo        ,upper(ASIG.U_WhsName)   as BodNombre      --,ASIG.U_DfltWhs          as BodDefecto        ,(case when ASIG.U_WhsCode in('01BUZPFT','01BUZTRT','01BUZCOT','01BUZPRT') then 'Y' else 'N' end) as BodDefecto        ,OWHS.U_TAI_ConsigCompra as BodConsignado        ,OWHS.U_TAI_VtaCalzada   as BodVtaCalzada       from [@VK_WHUD] ASIG         inner join OWHS on OWHS.WhsCode=ASIG.U_WhsCode      where ASIG.U_WhsCode<>'00'        and ASIG.Code=@operador      order by ASIG.U_WhsCode desc   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_borrador_venta]   @opcion    integer  ,@documento integer  ,@proveedor varchar(15)  ,@diacompra integer  AS  BEGIN   if @Opcion=10    select distinct            dateadd(day,odrf.extradays,odrf.docdate) as FecVencimiento        ,odrf.DocDueDate         ,odrf.DocNum         ,odrf.DocEntry        ,odrf.CardName          ,odrf.CardCode         ,odrf.DocDate         ,odrf.TaxDate         ,odrf.GroupNum       ,upper(octg.PymntGroup)                   as PymntGroup       ,odrf.ExtraDays         ,odrf.SlpCode        ,upper(oslp.SlpName)                      as SlpName        ,odrf.OwnerCode         ,odrf.PayToCode         ,isnull(odrf.ShipToCode,'')               as ShipToCode         ,isnull(odrf.NumAtCard,'')                as NumAtCard       ,isnull(odrf.Comments,'')                 as Comments       ,odrf.Series         ,nnm1.SeriesName          ,'N'                                      as Facturado       ,0                                        as FolioNum       ,odrf.U_TAI_Despacho       ,upper(ufd1.Descr)                        as TipoDespacho          ,isnull(odrf.U_TAI_CondicionPagOC,0)      as U_TAI_CondicionPagOC       ,ocrd.LicTradNum                          as LicTradNum       ,isnull(ocrd.phone1, '')                  as phone1       ,lower(isnull(ocrd.E_Mail,''))            as E_Mail       ,upper(isnull(ocrd.Notes,''))             as Notes              ,odrf.U_TAI_TipoVenta         ,isnull(odrf.U_TAI_ComentarioOC,'')       as U_TAI_ComentarioOC       ,isnull(odrf.U_TAI_MonedaProducto,'CLP')  as U_TAI_MonedaProducto              ,odrf.DocTotal              ,lower(isnull(ohem.email,''))             as email       ,upper(isnull(aut.Mje_Op,''))             as Mje_Op       ,upper(isnull(aut.Mje_Aut,''))            as Mje_Aut       ,upper(ISNULL(aut.rechaza,''))            as rechaza              ,isnull(odrf.U_TAI_NotaPedidoC, '')       as U_TAI_NotaPedidoC       ,odrf.OwnerCode       ,odrf.U_TAI_GlosaEspecial                        ,odrf.ObjType       ,0                                        as TargetType       ,0                                        as TrgetEntry                  ,isnull(cat.par_enlace,'') + ' - ' + isnull(cat.par_nombre,'') as U_TAI_Categoria       ,replace(isnull(mot.par_nombre,''),'SELECCIONE','')            as motivo       ,isnull(odrf.U_TAI_Emision,'F')                                as emision       ,isnull(odrf.U_Estado_Aut,'')                                  as U_Estado_Aut      from odrf               --inner join drf1 on drf1.Docentry  = odrf.Docentry                  left  join octg on octg.groupnum  = odrf.groupnum                 left  join oslp on oslp.slpcode   = odrf.slpcode                 left  join nnm1 on nnm1.Series    = odrf.Series                 left  join ocrd on ocrd.cardcode  = odrf.cardcode                 left  join tai_tb_autorizaciones aut on aut.DocEntry=odrf.DocEntry                 left  join ohem on ohem.salesPrson=odrf.SlpCode                 left  join ufd1 on ufd1.TableID   = 'ODRF' and ufd1.FieldID=45    and ufd1.FldValue=odrf.U_TAI_Despacho               --left  join inv1 on inv1.basetype  = ordr.ObjType  and inv1.BaseEntry = ordr.DocEntry                --left  join oinv on oinv.DocEntry  = inv1.DocEntry         left  join TAI_VW_PARAMETROS     cat on cat.par_grupo='categoria' and cat.par_enlace=ocrd.U_TAI_Categoria        left  join TAI_VW_PARAMETROS     mot on mot.par_grupo='motivo'    and mot.par_codigo=odrf.U_TAI_Motivo     where odrf.DocEntry=@documento   if @Opcion=20    select DocEntry          ,ItemCode       ,upper(Dscription) as Dscription       ,Quantity       ,Currency       ,Rate       ,Price       ,LineTotal       ,DiscPrcnt       ,U_TAI_Interes       ,U_TAI_Flete       ,U_TAI_FechaEntrega       ,U_TAI_PUFinal       ,U_TAI_CostoComercial       ,isnull(U_TAI_MonedaCosto,'')             as U_TAI_MonedaCosto       ,U_TAI_PrcDsctoMax       ,isnull(U_TAI_CostoReposicio,0)           as U_TAI_CostoReposicion                  ,isnull(U_TAI_DiasCompra,0)               as U_TAI_DiasCompra         ,U_TAI_MonedaPF               ,U_TAI_PreCompraPF       ,(isnull(U_TAI_PrecioCompraO,0)*Quantity) as U_TAI_PrecioCompraO       ,isnull(U_TAI_CardCode,'')                as U_TAI_CardCode              ,WhsCode       ,U_TAI_TasaInteres              ,isnull(U_TAI_CondicionProducto,'')       as U_TAI_CondicionProducto       ,isnull(U_TAI_MotivoProducto,0)           as CodMotivoProducto       ,(case when isnull(U_TAI_MotivoProducto,0)=0 then ''              when U_TAI_MotivoProducto=1           then 'CONDICION ESPECIAL'        when U_TAI_MotivoProducto=2           then 'FALTA DE STOCK'        when U_TAI_MotivoProducto=3           then 'COND.ESPECIAL Y FALTA DE STOCK'        else                                       ''      end)                                    as NomMotivoProducto        from drf1     where DocEntry                  =@documento             and isnull(U_TAI_CardCode,'x')=(case when @proveedor='' then isnull(U_TAI_CardCode,'x') else @proveedor end)       and isnull(U_TAI_DiasCompra,0)=(case when @diacompra=0  then isnull(U_TAI_DiasCompra,0) else @diacompra end)  END
create PROCEDURE [dbo].[tai_vw_sp2_select_borrador_venta_cancela]  AS  BEGIN   declare @DiasHabiles     int   declare @ControlaBucle   int   declare @DiasAdicionales int   declare @DiaFeriado      int   declare @FechaReal       char(8)   set @DiasHabiles    =3   set @ControlaBucle  =0   set @DiasAdicionales=@DiasHabiles   set @DiaFeriado     =0   set @FechaReal      =convert(char(8),getdate()-@DiasHabiles,112)   while @ControlaBucle<>1   begin    set @DiaFeriado=isnull((select datediff(dd,StrDate,EndDate)+1 from HLD1 where convert(char(8),EndDate,112)=@FechaReal),0)    if (@DiaFeriado=0)    begin     set @ControlaBucle=1    end    else    begin     set @DiasAdicionales=@DiasAdicionales+@DiaFeriado     set @FechaReal=convert(char(8),getdate()-@DiasAdicionales,112)    end   end   set @FechaReal=convert(char(8),getdate()-@DiasAdicionales,112)   update TAI_TB_DISPATCHER       set ComentarioAutoriza='RECHAZADO - ha excedido plazo maximo de ' + cast((@DiasHabiles*24) as varchar) + ' horas habiles para crear OV ' + ltrim(rtrim(ComentarioAutoriza))     from TAI_TB_DISPATCHER AV       inner join ODRF   BV on BV.DocEntry=AV.Codigo_Borrador    where BV.DocStatus   ='O'       and BV.ObjType     =17       and BV.U_Estado_Aut='A'       and convert(char(8),BV.DocDate,112)<@FechaReal   update ODRF       set U_Estado_Aut='R'    where DocStatus   ='O'       and ObjType     =17       and U_Estado_Aut='A'       and convert(char(8),DocDate,112)<@FechaReal  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_cancela_borrador_venta]  AS  BEGIN   declare @DiasHabiles     int   declare @ControlaBucle   int   declare @DiasAdicionales int   declare @DiaFeriado      int   declare @FechaReal       char(8)   set @DiasHabiles    =3   set @ControlaBucle  =0   set @DiasAdicionales=@DiasHabiles   set @DiaFeriado     =0   set @FechaReal      =convert(char(8),getdate()-@DiasHabiles,112)   while @ControlaBucle<>1   begin    set @DiaFeriado=isnull((select datediff(dd,StrDate,EndDate)+1 from HLD1 where convert(char(8),EndDate,112)=@FechaReal),0)    if (@DiaFeriado=0)    begin     set @ControlaBucle=1    end    else    begin     set @DiasAdicionales=@DiasAdicionales+@DiaFeriado     set @FechaReal=convert(char(8),getdate()-@DiasAdicionales,112)    end   end   set @FechaReal=convert(char(8),getdate()-@DiasAdicionales,112)   update TAI_TB_DISPATCHER       set ComentarioAutoriza='RECHAZADO - ha excedido plazo maximo de ' + cast((@DiasHabiles*24) as varchar) + ' horas habiles para crear OV ' + ltrim(rtrim(ComentarioAutoriza))     from TAI_TB_DISPATCHER AV       inner join ODRF   BV on BV.DocEntry=AV.Codigo_Borrador    where BV.DocStatus   ='O'       and BV.ObjType     =17       and BV.U_Estado_Aut='A'       and convert(char(8),BV.DocDate,112)<@FechaReal   update ODRF       set U_Estado_Aut='R'    where DocStatus   ='O'       and ObjType     =17       and U_Estado_Aut='A'       and convert(char(8),DocDate,112)<@FechaReal  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_cancela_orden_venta]  @proceso varchar(1)  AS  BEGIN   declare @DocDate datetime   if @proceso='A'    set @DocDate=getdate()-3   else if @proceso='C'       set @DocDate=getdate()-4   select OHEM.userId                                as UsuCodigo      ,ORDR.SlpCode                               as OpeCodigo      ,upper(OSLP.SlpName)                        as OpeNombre      ,isnull(lower(OHEM.email),'')               as OpeCorreo      ,ORDR.DocEntry                              as DocEntry      ,ORDR.DocNum                                as DocNumero      ,ORDR.DocDate                               as DocFecha      ,ORDR.CardCode                              as CliCodigo      ,upper(ORDR.CardName)                       as CliNombre      ,cast(ORDR.DocTotal as numeric(9,0))        as DocTotal    --,upper(ORDR.U_TAI_TipoVenta)                as VenTipo      ,case ORDR.U_TAI_TipoVenta      when 'ventaBodega'           then 'BODEGA PROPIA'      when 'ventaConsignada'       then 'CONSIGNADA'      when 'ventaPuestoFundo'      then 'PUESTO FUNDO'      when 'ventaCalzadaProveedor' then 'CALZADA PROVEEDOR'         when 'ventaCostoEspecial'    then 'COSTO ESPECIAL'      when 'ventaLiquidacion'      then 'LIQUIDACION'      else                              'SIN CLASIFICAR'       end                                        as VenTipo     from ORDR       inner join OSLP on OSLP.SlpCode   =ORDR.SlpCode        inner join OHEM on OHEM.salesPrson=OSLP.SlpCode    where DocStatus      ='O'       and U_VK_CertOrigen='WEB'       and convert(char(8),docdate,112)=convert(char(8),@DocDate,112)  END
  CREATE PROCEDURE [dbo].[tai_vw_sp2_select_cliente]   @opcion  integer  ,@cliente varchar(25)   AS  BEGIN   if @opcion=10   begin    select top 10        OCRD.CardCode                    as CliCodigo       ,upper(OCRD.CardName)             as CliNombre       ,OCRD.LicTradNum                  as CliRut       ,OCRD.frozenFor                   as CliBloqueado         ,isnull(OCRD.phone1, '')          as CliTelefono       ,lower(isnull(OCRD.E_Mail,''))    as CliCorreo       ,upper(isnull(OCRD.Notes,''))     as CliGiro       ,isnull(OCRD.Currency,'')         as CliMoneda       ,isnull(OCRD.U_TAI_Categoria, '') as CatCodigo       ,isnull(PRMT.par_nombre,'')       as CatNombre       ,isnull(OCRD.GroupNum,0)          as CliPlazoVentaCodigo       ,upper(isnull(OCTG.PymntGroup,''))as CliPlazoVentaNombre       ,isnull(OCRD.GroupCode, '')       as GruCodigo       ,upper(isnull(OCRG.GroupName, ''))as GruNombre      from OCRD           left join TAI_VW_Parametros PRMT on PRMT.par_enlace=OCRD.U_TAI_Categoria  and PRMT.par_grupo='categoria'         left join OCRG                   on OCRG.GroupCode =OCRD.GroupCode        left join OCTG     on OCTG.GroupNum  =OCRD.GroupNum     where OCRD.CardType ='C'        and OCRG.GroupType='C'        and OCRG.Locked   ='N'          and (OCRD.CardCode like '' + @cliente + '%' or OCRD.CardName like '%' + @cliente + '%' or OCRD.LicTradNum like '' + @cliente + '%')     end   if @opcion=20   begin    select OCRD.CardCode                                                           as CliCodigo          ,(case when OCRD.U_TAI_Acuerdo=1                  then 'NO - PLAZO VTA.MAX. A 30 DIAS'                  else 'SI - SE ENCUENTRA INSCRITO'            end)                                                                    as CliAcuerdo          ,isnull(OCRD.U_TAI_LinCredCom, 0)                                        as CliAutorizado       ,isnull(sum(CRED.Balance), 0)                                            as CliUtilizado               ,isnull(OCRD.U_TAI_LinCredCom - sum(CRED.Balance),OCRD.U_TAI_LinCredCom) as CliDisponible      from OCRD          left join TAI_VW_CtaCte_Cliente CRED on CRED.CardCode=OCRD.CardCode     where OCRD.CardCode=@cliente     group by OCRD.CardCode, OCRD.U_TAI_Acuerdo, OCRD.U_TAI_LinCredCom---, OCRD.U_TAI_Categoria    end   if @opcion=30   begin     select isnull(DTOP.U_SlpCode, OSLP.SlpCode)        as VenCodigo       ,upper(isnull(DTOP.U_SlpName, OSLP.SlpName)) as VenNombre        from [@TAI_OCPCC]            CBOP        right join [@TAI_OCPCD] DTOP on CBOP.Code=DTOP.Code        right join OCRD              on OCRD.CardCode=CBOP.Name        right join OSLP              on OSLP.SlpCode =OCRD.SlpCode       where OCRD.CardCode=@cliente     --union all        --select 116, 'MAQUINARIAS'       --union all       --select 180, 'MAQUINARIA CHILLAN'   end   if @opcion=40   begin      select upper(isnull(CRD1.[Address],'')) as DirTipo       ,upper(isnull(CRD1.Street,''))    as DirCalle       ,upper(isnull(CRD1.County,''))    as DirComuna       ,upper(isnull(CRD1.City,''))      as DirCiudad       ,upper(isnull(OCST.Name,''))      as DirRegion       ,upper(isnull(CRD1.Country,''))   as DirPais       ,upper(isnull(CRD1.Street,'')+' '+ isnull(CRD1.County,'')+ ' '+isnull(OCST.Name,'')) as DirCompleta      from CRD1           left join OCST on OCST.Code=CRD1.[State]     where AdresType='B'       and CardCode=@cliente   end   if @opcion=50   begin      select upper(isnull(CRD1.[Address],'')) as DirTipo       ,upper(isnull(CRD1.Street,''))    as DirCalle       ,upper(isnull(CRD1.County,''))    as DirComuna       ,upper(isnull(CRD1.City,''))      as DirCiudad       ,upper(isnull(OCST.Name,''))      as DirRegion       ,upper(isnull(CRD1.Country,''))   as DirPais       ,upper(isnull(CRD1.Street,'')+' '+ isnull(CRD1.County,'')+ ' '+isnull(OCST.Name,'')) as DirCompleta      from CRD1           left join OCST on OCST.Code=CRD1.[State]     where AdresType='S'       and CardCode=@cliente   end   if @opcion=60   begin    select top 5           VTO.FolioNum as DocNumero          ,VTO.DueDate  as DocFecha          ,VTO.Balance  as DocValor       from TAI_VW_CtaCte_Cliente VTO, OCRD CLI, OSLP OPE       where VTO.Balance <>0       and VTO.CardType ='C'          and VTO.CardCode =CLI.CardCode       and CLI.SlpCode  =OPE.SlpCode          and VTO.TransType=13           and VTO.CardCode =@cliente          and VTO.DueDate <  GETDATE()     order by VTO.DueDate   end   if @opcion=70   begin     select top 3           DET.TransId                      as DocNumero          ,DET.TaxDate                      as DocFecha          ,(DET.BalDueDeb - DET.BalDueCred) as DocValor         from JDT1 DET            inner join OJDT CAB on CAB.TransId=DET.TransId           inner join OACT CTA on DET.Account=CTA.AcctCode          where DET.ShortName         =rtrim(@cliente)          and CTA.U_TAI_DocsProtesta='Y'           and (DET.BalDueDeb - DET.BalDueCred)>0        order by DET.TaxDate   end  END
create PROCEDURE [dbo].[tai_vw_sp2_select_costo_producto]   @opcion    int  ,@grupo     int  ,@subgrupo  int  ,@linea     int  AS  BEGIN   if @opcion=10   begin    select top 1048500           G.gru_codigo                                            as GruCodigo       ,G.gru_nombre                                            as GruNombre       ,S.sub_codigo                                            as SubCodigo       ,S.sub_nombre                                            as SubNombre       ,L.lin_codigo                                            as LinCodigo       ,L.lin_nombre                                            as LinNombre       ,B.WhsCode                                               as BodCodigo       ,B.WhsName                                               as BodNombre       ,A.ItemCode                                              as ArtCodigo       ,A.ItemName                                              as ArtNombre         ,(case when isnull(W.U_TAI_Moneda,'')=''               then (select top 1 M.U_TAI_Moneda                 from OITW M          where M.ItemCode=W.ItemCode            and isnull(M.U_TAI_Moneda,'')<>''         group by M.U_TAI_Moneda          order by count(M.U_TAI_Moneda) desc)         else W.U_TAI_Moneda         end)                                                    as ArtMoneda       ,cast(isnull(W.U_TAI_CostoRep,0) as numeric(18,2))       as ArtCostoReposicion       ,cast(isnull(W.U_TAI_Flete,0) as numeric(18,0))          as ArtCargoFlete       ,cast(isnull(W.U_TAI_Seguro,0) as numeric(18,2))         as ArtCargoSeguro       ,cast(isnull(W.U_TAI_FactorLog,0) as numeric(18,2))      as ArtCargoLogistico       ,cast(isnull(W.U_TAI_Otros,0) as numeric(18,2))          as ArtCargoOtros       ,cast(isnull(W.U_TAI_PorcMargen,0) as numeric(18,2))     as ArtPorcentajeMargen       ,cast(isnull(W.U_TAI_CostoComercial,0) as numeric(18,2)) as ArtCostoComercialActual       ,cast(isnull(W.U_TAI_PorcMargen,0) as numeric(18,2))     as ArtPorcentajeMargenActual       ,cast(isnull(W.U_TAI_PrecioVenta,0) as numeric(18,2))    as ArtPrecioVentaActual      from OITW                              W           inner join OWHS      B on B.WhsCode   =W.WhsCode            inner join OITM                   A on A.ItemCode  =W.ItemCode        inner join OITB                   E on E.ItmsGrpCod=A.ItmsGrpCod        inner join matriz_descto_linea    L on L.lin_codigo=E.ItmsGrpCod        inner join matriz_descto_subgrupo S on S.sub_codigo=L.sub_codigo        inner join matriz_descto_grupo    G on G.gru_codigo=S.gru_codigo     where A.InvntItem ='Y'       and A.frozenFor ='N'       and G.gru_codigo=(case when @grupo   =0 then G.gru_codigo else @grupo    end)       and S.sub_codigo=(case when @subgrupo=0 then S.sub_codigo else @subgrupo end)       and L.lin_codigo=(case when @linea   =0 then L.lin_codigo else @linea    end)           order by A.ItemCode, B.WhsCode   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_cotizacion]   @opcion   int  ,@operador int  ,@estado   char(1)  ,@docto    int  AS  BEGIN   if @opcion=10   begin    select C.NumAtCard                                  CmrCodigo          ,C.DocEntry                                   CotCodigo       ,C.DocDate                                    CotFecha     --,replace(replace(C.U_TAI_TipoVenta,'venta',''),'Bodega','BodegaPropia') VenTipo       ,case C.U_TAI_TipoVenta             when 'ventaBodega'           then 'BODEGA PROPIA'       when 'ventaConsignada'       then 'CONSIGNADA'       when 'ventaPuestoFundo'      then 'PUESTO FUNDO'       when 'ventaCalzadaProveedor' then 'CALZADA PROVEEDOR'       when 'ventaCostoEspecial'    then 'COSTO ESPECIAL'       else ' '        end                                          VenTipo       ,C.CardCode                                   CliCodigo       ,C.CardName                                   CliNombre       ,C.DocCur                                     DocMoneda       ,cast(C.DocTotal as numeric(18,0))            DocTotal       ,C.U_TAI_Emision                              EmiCodigo       ,E.par_nombre                                 EmiNombre       ,C.U_TAI_MonedaProducto                       PagMoneda       ,C.U_TAI_Despacho                             DesCodigo       ,upper(D.Descripcion)                         DesNombre       ,C.GroupNum                                   PlaCodigo       ,upper(P.PymntGroup)                          PlaNombre      from OQUT C           inner join TAI_VW_Parametros    E on E.par_grupo='emision' and E.par_enlace=C.U_TAI_Emision           inner join TAI_VW_ValorDespacho D on D.ID=U_TAI_Despacho        inner join OCTG                 P on P.GroupNum=C.GroupNum      where C.DocDate>=getdate()-7     and C.U_U_TAI_OVTA      =4      and C.slpcode           =@Operador     and C.U_Estado_Aut      =@estado      and C.DocEntry          =(case when @docto>0 then @docto else C.DocEntry end)      order by C.DocEntry desc   end   if @opcion=20   begin    select WhsCode                      BodCodigo          ,ItemCode                     ArtCodigo       ,Dscription                   ArtNombre       ,cast(Quantity as integer)    ArtCantidad       ,cast(Price as numeric(18,2)) ArtPrecio       ,Currency                     ArtMoneda       ,cast(Rate as numeric(6,2))   ArtCambio       ,U_TAI_FechaEntrega           EntFecha      from QUT1     where DocEntry=@docto     order by LineNum   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_cuarta_copia]   @operador int  ,@año      int  ,@mes      int  AS  BEGIN      select CAB.SlpCode                               OpeCodigo        ,OPE.SlpName                               OpeNombre              ,CAB.CardCode                              CliCodigo                  ,rtrim(ltrim(left(CAB.CardName,30)))       CliNombre              ,CAB.DocDate                               DocFecha                 --,'FVR'                                     DocTipo        ,case when CAB.DocSubType='--' then 'FV'            when CAB.DocSubType='IB' then 'BV'                  when CAB.DocSubType='DN' then 'ND'             end                                       DocTipo            ,CAB.DocNum                                DocNumero              ,isnull(CAB.FolioNum,0)                    DocFolio             ,cast(sum(DET.LineTotal) as integer)       DocNeto             ,isnull(CAB.U_TAI_cuartacopia,'')          Doc4taCopia          from OINV            CAB               inner join INV1 DET on DET.DocEntry=CAB.DocEntry               inner join OSLP OPE on OPE.SlpCode =CAB.SlpCode         where CAB.SlpCode       =@operador           and year(CAB.DocDate) =@año           and month(CAB.DocDate)=@mes         and (CAB.U_TAI_cuartacopia is null or (year(CAB.U_TAI_cuartacopia)=year(getdate()) and month(CAB.U_TAI_cuartacopia)=month(getdate()) and day(CAB.U_TAI_cuartacopia)=day(getdate())))           group by CAB.SlpCode,OPE.SlpName,CAB.CardName,CAB.DocDate,CAB.U_TAI_cuartacopia,CAB.DocNum,CAB.FolioNum,CAB.CardCode,CAB.DocSubType  union      select CAB.SlpCode                               OpeCodigo        ,OPE.SlpName                               OpeNombre              ,CAB.CardCode                              CliCodigo                  ,rtrim(ltrim(left(CAB.CardName,30)))       CliNombre              ,CAB.DocDate                               DocFecha                 --,'FVR'                                     DocTipo        ,case when CAB.DocSubType='--' then 'NC'            else                          ''             end                                       DocTipo            ,CAB.DocNum                                DocNumero              ,isnull(CAB.FolioNum,0)                    DocFolio             ,cast(sum(DET.LineTotal) as integer)       DocNeto             ,isnull(CAB.U_TAI_cuartacopia,'')          Doc4taCopia          from ORIN            CAB               inner join RIN1 DET on DET.DocEntry=CAB.DocEntry               inner join OSLP OPE on OPE.SlpCode =CAB.SlpCode         where CAB.SlpCode       =@operador           and year(CAB.DocDate) =@año           and month(CAB.DocDate)=@mes         and (CAB.U_TAI_cuartacopia is null or (year(CAB.U_TAI_cuartacopia)=year(getdate()) and month(CAB.U_TAI_cuartacopia)=month(getdate()) and day(CAB.U_TAI_cuartacopia)=day(getdate())))           group by CAB.SlpCode,OPE.SlpName,CAB.CardName,CAB.DocDate,CAB.U_TAI_cuartacopia,CAB.DocNum,CAB.FolioNum,CAB.CardCode,CAB.DocSubType      END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_cuenta_contable]   @opcion integer  ,@bodega varchar(20)   AS  BEGIN   if @opcion=10   begin    declare @sucursal as varchar(20)      select @sucursal=U_TAI_Sucursal         from OWHS      where WhsCode=@bodega      select ItemCode as CtaCodigo                          from OITM        where ItemName like 'Fletes Recuperables ' + @sucursal      end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_cuenta_corriente]    @opcion  integer  ,@cliente varchar(25)   AS  BEGIN   if @opcion=10   begin    select [DocEntry]= (case          when VTO.TransType = 13 then VTO.FolioNum           when VTO.TransType = 24 then VTO.DocNum          when VTO.TransType = 14 then VTO.FolioNum           else 0         end)       ,DocNum        ,DocTipo=  (case          when VTO.TransType = 13 then 'FACTURA'          when VTO.TransType = 24 then 'PAGO RECIBIDO'          when VTO.TransType = 14 then 'NOTA CREDITO'           when VTO.TransType = 30 then 'ASIENTO'           else ''         end)       ,isnull(convert(varchar(2), VTO.TipoDoc), '') as AbrDoc       ,VTO.DocDate       ,VTO.DueDate            ,DocDebito  = (case          when VTO.Balance > 0 then convert(int,VTO.Balance)          when VTO.Balance < 0 then 0         end)       ,DocCredito = (case          when VTO.Balance < 0 then convert(int,VTO.Balance)          when VTO.Balance > 0 then 0         end)                ,DocSaldo   = (case when VTO.Balance > 0 then convert(int,VTO.Balance) when VTO.Balance < 0 then 0 end)                    -(case when VTO.Balance < 0 then convert(int,VTO.Balance) when VTO.Balance > 0 then 0 end)                     ,DocEstado = (case           when (VTO.DueDate < getdate() AND VTO.TransType='13' ) then 'VENCIDO'          when (VTO.DueDate > getdate() AND VTO.TransType='13')  then 'POR VENCER'          when (VTO.TransType <> '13')                           then ''         end)               ,'' as DocMonedaPago      ,0  as DocTipoCambio      ,0  as DocSaldoME                     from TAI_VW_CtaCte_Cliente VTO           inner join       OCRD CLI on CLI.CardCode=VTO.CardCode           inner join       OSLP OPE on OPE.SlpCode =CLI.SlpCode     where VTO.Balance <>0       and VTO.CardType='C'          and VTO.CardCode=@cliente     order by VTO.DueDate   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_descuento_maximo_producto]   @opcion          integer  ,@bodega          varchar(20)   ,@producto        varchar(30)  ,@fecha           varchar(10)   AS  BEGIN   if @opcion=10   begin    declare @costoBase numeric(19,6)      select @costoBase=case OWHS.U_TAI_VtaCalzada             when 'Y'          then 0 --@precioProveedor              else                case isnull(ITM1.Price * isnull(ORTT.Rate,1),0)              when 0            then OITW.AvgPrice              else ITM1.Price * isnull(ORTT.Rate,1)               end             end         from OITM        inner join OITW on OITW.ItemCode=OITM.ItemCode         inner join OWHS on OWHS.WhsCode =OITW.WhsCode        inner join ITM1 on ITM1.ItemCode=OITM.ItemCode and ITM1.PriceList=2         left  join ORTT on ORTT.Currency=ITM1.Currency and convert(char(8),ORTT.RateDate,112)=convert(char(8),convert(datetime,@fecha,103),112)     where OITW.ItemCode=@producto          and OITW.WhsCode =@bodega       select isnull(dbo.TAI_FN_ItemPolPre(@producto,@bodega,@costoBase,convert(datetime,@fecha,103),'DM'), 0) 'DtoMaximo'    end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_descuento_producto]   @opcion           integer  ,@producto         varchar(30)  ,@condicionPago    integer  ,@totalLinea       float  ,@fechaVencimiento varchar(10)=''  ,@fechaCompra      varchar(10)=''  AS  BEGIN   declare @diferenciaDias   integer   declare @descuento        float   declare @tasaInteres      float   set @descuento  =0   set @tasaInteres=isnull((select U_ValorNumerico from [@VK_OPAR] where code='TASAFINM'),0.3)   if @opcion=10   begin    declare @diasProducto      integer      declare @diasCondicionPago integer      set @diasCondicionPago=isnull((select isnull(ExtraDays,0)      from OCTG where GroupNum = @condicionPago),0)    set @diasProducto     =isnull((select isnull(U_TAI_DiasPago,0) from OITM where InvntItem='Y' and ItemCode=@producto),0)    set @diferenciaDias   =@diasCondicionPago - @diasProducto     if @diferenciaDias<0    begin     set @descuento=round(((abs(@diferenciaDias)/30)*@totalLinea*@tasaInteres)/100,0)    end    select @descuento as ArtDescuento     end   if @opcion=20   begin    set @diferenciaDias   =isnull((select datediff(dd,convert(datetime,@fechaCompra,103),convert(datetime,@fechaVencimiento,103))),0)    if @diferenciaDias<0    begin     set @descuento=round(((abs(@diferenciaDias)/30)*@totalLinea*@tasaInteres)/100,0)    end     select @descuento as ArtDescuento   end    END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_dispatcher]  @Codigo_Borrador integer  AS  BEGIN  /*   select Id                  as DisCodigo         ,Codigo_Autorizador  as DisOficial         ,Tipo_Autorizacion   as DisTipo          ,Aut_Backup          as DisBackup           ,Estado_Autorizacion as DisEstado         ,Fecha_Creacion      as DisFechaCreacion         ,Fecha_Actualizacion as DisFechaActualizacion         ,(case       when Estado_Autorizacion=1 then upper(isnull(ComentarioAutoriza,''))      when Estado_Autorizacion=2 then upper(isnull((select Mje_Aut from tai_tb_autorizaciones where DocEntry=@Codigo_Borrador and (Rechaza=Codigo_Autorizador or Rechaza=Aut_Backup)),''))      else  isnull(ComentarioAutoriza,'')       end)                as DisComentario      ,Estado_Autorizacion        from tai_tb_dispatcher    where Codigo_Borrador=@Codigo_Borrador      order by Fecha_Creacion, Fecha_Actualizacion  */   select Id                                   as DisCodigo         ,Codigo_Autorizador                   as DisOficial         ,Tipo_Autorizacion                    as DisTipo          ,Aut_Backup                           as DisBackup           ,Estado_Autorizacion                  as DisEstado         ,Fecha_Creacion                       as DisFechaCreacion         ,Fecha_Actualizacion                  as DisFechaActualizacion      ,upper(isnull(ComentarioAutoriza,'')) as DisComentario      ,Estado_Autorizacion        from tai_tb_dispatcher    where Codigo_Borrador=@Codigo_Borrador      order by Fecha_Creacion, Fecha_Actualizacion  END  
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_empleado]   @opcion   integer  ,@empleado integer  ,@oficina  integer  AS  BEGIN   if @opcion=10   begin    select OHEM.empID                                                                                   as EmpCodigo       ,upper(isnull(OHEM.firstName,'')+' '+isnull(OHEM.lastName,'')+' '+isnull(OHEM.middleName,'')) as EmpNombre        from OHEM     where OHEM.empID=@empleado   end   if @opcion=20   begin    select EMP.empID                                                                                    as EmpCodigo          ,upper(isnull(EMP.firstName,'')+' '+isnull(EMP.lastName,'')+' '+isnull(EMP.middleName,''))    as EmpNombre            ,isnull(EMP.salesPrson,0)                                                                     as OpeCodigo          ,isnull(OFI.Code,0)                                                                           as OfiCodigo             ,isnull(OFI.Name,'')                                                                          as OfiNombre           from OHEM            EMP             inner join HEM6 ROL on ROL.empID=EMP.empID             left join  OUBR OFI on OFI.Code =EMP.Branch           where EMP.Active='Y'          and ROL.roleID=2         and EMP.empID =@empleado         order by 3      end   END
  CREATE PROCEDURE [dbo].[tai_vw_sp2_select_factura_venta]   @opcion    integer  ,@documento integer  AS  BEGIN   if @Opcion=10    select distinct            dateadd(day,oinv.extradays,oinv.docdate) as FecVencimiento        ,oinv.DocDueDate         ,oinv.DocNum         ,oinv.DocEntry        ,oinv.CardName          ,oinv.CardCode         ,oinv.DocDate         ,oinv.TaxDate         ,oinv.GroupNum       ,upper(octg.PymntGroup)                   as PymntGroup       ,oinv.ExtraDays         ,oinv.SlpCode        ,upper(oslp.SlpName)                      as SlpName        ,oinv.OwnerCode         ,oinv.PayToCode         ,isnull(oinv.ShipToCode,'')               as ShipToCode         ,isnull(oinv.NumAtCard,'')                as NumAtCard       ,isnull(oinv.Comments,'')                 as Comments       ,oinv.Series         ,nnm1.SeriesName          ,(case when inv1.BaseEntry is null and (oinv.CANCELED='N' or oinv.DocStatus<>'C') then 'N' else 'Y' end)    as Facturado       ,isnull(oinv.FolioNum,0)                  as FolioNum       ,oinv.U_TAI_Despacho       ,upper(ufd1.Descr)                        as TipoDespacho          ,isnull(oinv.U_TAI_CondicionPagOC,0)      as U_TAI_CondicionPagOC       ,ocrd.LicTradNum                          as LicTradNum       ,isnull(ocrd.phone1, '')                  as phone1       ,lower(isnull(ocrd.E_Mail,''))            as E_Mail       ,upper(isnull(ocrd.Notes,''))             as Notes              ,oinv.U_TAI_TipoVenta         ,isnull(oinv.U_TAI_ComentarioOC,'')       as U_TAI_ComentarioOC       ,isnull(oinv.U_TAI_MonedaProducto,'CLP')  as U_TAI_MonedaProducto              ,oinv.DocTotal              ,lower(isnull(ohem.email,''))             as email       ,upper(isnull(aut.Mje_Op,''))             as Mje_Op       ,upper(isnull(aut.Mje_Aut,''))            as Mje_Aut       ,upper(ISNULL(aut.rechaza,''))            as rechaza               ,isnull(oinv.U_TAI_NotaPedidoC, '')       as U_TAI_NotaPedidoC       ,oinv.OwnerCode       ,oinv.U_TAI_GlosaEspecial                  ,oinv.ObjType       ,0                                        as TargetType       ,0                                        as TrgetEntry                 ,isnull(cat.par_enlace,'') + ' - ' + isnull(cat.par_nombre,'') as U_TAI_Categoria       ,replace(isnull(mot.par_nombre,''),'SELECCIONE','')            as motivo       ,isnull(oinv.U_TAI_Emision,'F')                                as emision        ,isnull(oinv.U_Estado_Aut,'')                                  as U_Estado_Aut           from oinv                 inner join inv1 on inv1.Docentry  = oinv.Docentry                 left  join octg on octg.groupnum  = oinv.groupnum                 left  join oslp on oslp.slpcode   = oinv.slpcode                 left  join nnm1 on nnm1.Series    = oinv.Series                 left  join ocrd on ocrd.cardcode  = oinv.cardcode                 left  join tai_tb_autorizaciones aut on aut.DocEntry=oinv.draftKey                 left  join ohem on ohem.salesPrson=oinv.SlpCode                 left  join ufd1 on ufd1.TableID   = 'OINV' and ufd1.FieldID=45 and ufd1.FldValue=oinv.U_TAI_Despacho               --left  join inv1 on inv1.basetype  = oinv.ObjType  and inv1.BaseEntry = oinv.DocEntry                --left  join oinv on oinv.DocEntry  = inv1.DocEntry           left  join TAI_VW_PARAMETROS     cat on cat.par_grupo='categoria' and cat.par_enlace=ocrd.U_TAI_Categoria        left  join TAI_VW_PARAMETROS     mot on mot.par_grupo='motivo'    and mot.par_codigo=oinv.U_TAI_Motivo     where oinv.DocNum=@documento   if @Opcion=20    select DocEntry          ,ItemCode       ,upper(Dscription) as Dscription       ,Quantity       ,Currency       ,Rate       ,Price       ,LineTotal       ,DiscPrcnt       ,U_TAI_Interes       ,U_TAI_Flete       ,U_TAI_FechaEntrega       ,U_TAI_PUFinal       ,U_TAI_CostoComercial       ,isnull(U_TAI_MonedaCosto,'')             as U_TAI_MonedaCosto       ,U_TAI_PrcDsctoMax       ,isnull(U_TAI_CostoReposicio,0)           as U_TAI_CostoReposicion              ,isnull(U_TAI_DiasCompra,0)               as U_TAI_DiasCompra         ,U_TAI_MonedaPF               ,U_TAI_PreCompraPF       ,(isnull(U_TAI_PrecioCompraO,0)*Quantity) as U_TAI_PrecioCompraO       ,isnull(U_TAI_CardCode,'')                as U_TAI_CardCode              ,WhsCode       ,U_TAI_TasaInteres      from inv1     where DocEntry=@documento  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_flete_producto]   @opcion     integer  ,@bodega     varchar(20)  ,@producto   varchar(30)  ,@cantidad   integer  ,@totalLinea float  AS  BEGIN   if @opcion=10   begin    select isnull(sum(case when OITM.QryGroup4='N'                           then isnull(round(@totalLinea*(LINE.U_TAI_PorcFlete/100),0),0)                         else isnull(FLTE.U_TAI_CostoXBodega*OITM.U_TAI_Capacidad*@cantidad,0)                       end),0) as ArtFlete      FROM OWHS         inner join OITM                       on OITM.ITEMCODE=@producto             inner join [@TAI_PPLIN]          LINE on LINE.CODE    =OITM.ItmsGrpCod              inner join OLCT                       on OLCT.Code    =OWHS.Location             left  join [@TAI_FLETE_ESPECIAL] FLTE on FLTE.Name    =OLCT.location       WHERE OITM.InvntItem='Y'         and OWHS.WhsCode  =@Bodega      end  END
create PROCEDURE [dbo].[tai_vw_sp2_select_grupo]   @opcion  int  ,@grupo   int  ,@usuario varchar(10)=''  AS  BEGIN   if @opcion=10   begin    select gru_codigo as GruCodigo       ,gru_nombre as GruNombre      from matriz_descto_grupo     order by 2    end   if @opcion=20   begin    select gru_codigo as GruCodigo       ,gru_nombre as GruNombre      from matriz_descto_grupo               g     where g.gru_codigo=(case when @grupo   =0 then g.gru_codigo else @grupo    end)     order by 2    end   if @opcion=30   begin    if not exists (select distinct d.det_codusuario from matriz_descto_detalle d where d.det_codcargo='GL' and det_codusuario=@usuario)     set @usuario=''    select distinct        g.gru_codigo as GruCodigo       ,g.gru_nombre as GruNombre      from matriz_descto_grupo               g        inner join matriz_descto_subgrupo s on s.gru_codigo  =g.gru_codigo        inner join matriz_descto_linea    l on l.sub_codigo  =s.sub_codigo         inner join matriz_descto_detalle  d on d.det_codlinea=l.lin_codigo     where d.det_codcargo  ='GL'       and d.det_codusuario=(case when @usuario ='' then d.det_codusuario else @usuario end)       and g.gru_codigo    =(case when @grupo   =0  then g.gru_codigo     else @grupo   end)     order by 2   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_hibrido_producto]   @opcion   integer  ,@producto varchar(30)  AS  BEGIN   if @opcion=10   begin    select U_TAI_DescSemillas as HibCodigo          ,U_TAI_DescSemillas as HibNombre      from [@TAI_SEMILLASD]      where U_TAI_Bloqueo='N'       and U_TAI_DescSemillas is not null       and Code         =@producto     order by U_TAI_DescSemillas   end  END
CREATE PROCEDURE tai_vw_sp2_select_impresora   @documento int  ,@folio     int  AS  BEGIN   declare @Code varchar(50)     if @documento=33    select @Code=OUSR.USER_CODE  from OINV inner join OHEM on OHEM.empID=OINV.OwnerCode inner join OUSR on OUSR.USERID=OHEM.userId where year(OINV.DocDate)>=2022 and OINV.DocSubType='--' and OINV.FolioNum=@folio     else if @documento=34    select @Code=OUSR.USER_CODE  from OINV inner join OHEM on OHEM.empID=OINV.OwnerCode inner join OUSR on OUSR.USERID=OHEM.userId where year(OINV.DocDate)>=2022 and OINV.DocSubType='IE' and OINV.FolioNum=@folio     else if @documento=39    select @Code=OUSR.USER_CODE  from OINV inner join OHEM on OHEM.empID=OINV.OwnerCode inner join OUSR on OUSR.USERID=OHEM.userId where year(OINV.DocDate)>=2022 and OINV.DocSubType='IB' and OINV.FolioNum=@folio    else if @documento=41    select @Code=OUSR.USER_CODE  from OINV inner join OHEM on OHEM.empID=OINV.OwnerCode inner join OUSR on OUSR.USERID=OHEM.userId where year(OINV.DocDate)>=2022 and OINV.DocSubType='**' and OINV.FolioNum=@folio    else if @documento=52   begin    select @Code=OUSR.USER_CODE  from ODLN inner join OHEM on OHEM.empID=ODLN.OwnerCode inner join OUSR on OUSR.USERID=OHEM.userId where year(ODLN.DocDate)>=2022 and ODLN.DocSubType='--' and ODLN.FolioNum=@folio    if @Code is null    select @Code=OUSR.USER_CODE  from OWTR inner join OHEM on OHEM.empID=OWTR.OwnerCode inner join OUSR on OUSR.USERID=OHEM.userId where year(OWTR.DocDate)>=2022 and OWTR.DocSubType='--' and OWTR.FolioNum=@folio    if @Code is null    select @Code=OUSR.USER_CODE  from ORPD inner join OHEM on OHEM.empID=ORPD.OwnerCode inner join OUSR on OUSR.USERID=OHEM.userId where year(ORPD.DocDate)>=2022 and ORPD.DocSubType='--' and ORPD.FolioNum=@folio   end   else if @documento=56    select @Code=OUSR.USER_CODE  from OINV inner join OHEM on OHEM.empID=OINV.OwnerCode inner join OUSR on OUSR.USERID=OHEM.userId where year(OINV.DocDate)>=2022 and OINV.DocSubType='DN' and OINV.FolioNum=@folio     else if @documento=61    select @Code=OUSR.USER_CODE  from ORIN inner join OHEM on OHEM.empID=ORIN.OwnerCode inner join OUSR on OUSR.USERID=OHEM.userId where year(ORIN.DocDate)>=2022 and ORIN.DocSubType='--' and ORIN.FolioNum=@folio       select Name Emisor, U_TAI_Sucursal Sucursal , U_TAI_NameImpresora Printer, U_TAI_IpImpresora IPPrinter from [@TAI_FE_IMPRESORA] where Code=@Code  END
  CREATE PROCEDURE [dbo].[tai_vw_sp2_select_informe_disponibilidad]    @Opcion int,  @Item NVARCHAR(50),  @Bodega NVARCHAR(20),  @Linea NVARCHAR(5),  @Sucursal NVARCHAR(4),  @fechaStock NVARCHAR(10),  @fechaVtaIni NVARCHAR(10),  @fechaVtaFin NVARCHAR(10),  @familia NVARCHAR(10)    AS  BEGIN   DECLARE @Fecha AS NVARCHAR(10)   DECLARE @diasTasa AS INT   SET @Fecha = convert(nvarchar(4), YEAR(DATEADD(MM,-1,CONVERT(NVARCHAR(10),@fechaStock,102)))) + '/' + CONVERT(nvarchar(2), MONTH(DATEADD(MM,-1,CONVERT(NVARCHAR(10),@fechaStock,102)))) + '/1'   SET @diasTasa = DATEDIFF(DAY, @fechaVtaIni, @fechaVtaFin )      IF @diasTasa = 0    BEGIN     SET @diasTasa = 1    END     IF @Opcion = 10    BEGIN      SELECT  distinct       T0.ItemCode      ,REPLACE(T7.ItemName,'#','') AS 'ItemName'      ,ISNULL(T9.CardName,'SP') AS CardCode      ,ISNULL(T8.ItmsGrpNam,'') AS 'LineaNegocio'      ,ISNULL(T7.U_TAI_Envase,'SE') AS 'Envase'      ,ISNULL((CASE       WHEN T7.U_TAI_UndMed = 'X' THEN 'Ninguno'       WHEN T7.U_TAI_UndMed = 'L' THEN 'LT'       WHEN T7.U_TAI_UndMed = 'K' THEN 'KG'       ELSE 'SU'      END),'') AS 'UnidadMedida'      ,ISNULL(replace(convert(nvarchar(50),convert(numeric(32,2),T7.U_TAI_Capacidad)),'.',','),0) AS 'Capacidad'      ,T0.Warehouse       ,ISNULL(T6.[Location],'') AS 'Sucursal'      ,ISNULL(CONVERT(INT,(SUM(T0.InQty) - SUM(T0.OutQty))),0) AS 'Stock'      ,CONVERT(numeric(32,0),(ISNULL(T1.U_TAI_CostoRep,0) * ISNULL(CONVERT(INT,(SUM(T0.InQty) - SUM(T0.OutQty))),0))) AS 'PxQ'      ,ISNULL(REPLACE(ISNULL(CONVERT(NUMERIC(32,2),(SELECT SUM(TT0.Quantity) FROM INV1 TT0 LEFT JOIN OINV TT1 ON TT0.DocEntry = TT1.DocEntry WHERE TT0.ItemCode = T0.ItemCode AND TT0.WhsCode = T0.Warehouse  AND TT1.CANCELED <> 'Y' AND TT0.LineStatus <> 'C' AND (TT1.DocDate >= CONVERT(NVARCHAR(10),@fechaVtaIni,102) AND TT1.DocDate <= CONVERT(NVARCHAR(10),@fechaVtaFin,102)))),0),'.',','),0) AS 'Vendido'       ,ISNULL(MONTH(@Fecha),0) AS Mes      ,CONVERT(NUMERIC(32,2),(CASE        WHEN (SUM(T0.InQty) - SUM(T0.OutQty)) > 0 AND (SELECT SUM(TT0.Quantity) FROM INV1 TT0 LEFT JOIN OINV TT1 ON TT0.DocEntry = TT1.DocEntry WHERE TT0.ItemCode = T0.ItemCode AND TT0.WhsCode = T0.Warehouse  AND TT1.CANCELED <> 'Y' AND TT0.LineStatus <> 'C' AND (TT1.DocDate >= CONVERT(NVARCHAR(10),@fechaVtaIni,102) AND TT1.DocDate <= CONVERT(NVARCHAR(10),@fechaVtaFin,102)))  > 0 THEN (SUM(T0.InQty) - SUM(T0.OutQty)) /(SELECT SUM(TT0.Quantity) FROM INV1 TT0 LEFT JOIN OINV TT1 ON TT0.DocEntry = TT1.DocEntry WHERE TT0.ItemCode = T0.ItemCode AND TT0.WhsCode = T0.Warehouse  AND TT1.CANCELED <> 'Y' AND TT0.LineStatus <> 'C' AND (TT1.DocDate >= CONVERT(NVARCHAR(10),@fechaVtaIni,102) AND TT1.DocDate <= CONVERT(NVARCHAR(10),@fechaVtaFin,102)))/@diasTasa        ELSE 0      END)) AS 'Tasa'      FROM OINM T0        LEFT JOIN OITW T1 ON T0.ItemCode = T1.ItemCode AND T0.Warehouse = T1.WhsCode       LEFT JOIN OWHS T4 ON T0.Warehouse = T4.WhsCode       LEFT JOIN OLCT T6 ON T4.[Location] = T6.Code       LEFT JOIN OITM T7 ON T0.ItemCode = T7.ItemCode        LEFT JOIN OITB T8 ON T7.ItmsGrpCod = T8.ItmsGrpCod       LEFT JOIN OCRD T9 ON T7.CardCode = T9.CardCode      WHERE T0.DocDate <= @Fecha         AND T0.ItemCode LIKE           (CASE            WHEN ISNULL(@Item,'0') = '0' THEN '%'            WHEN ISNULL(@Item,'0') <> '0' THEN @Item          END)           AND T0.Warehouse LIKE           (CASE            WHEN ISNULL(@Bodega,'0') = '0' THEN '%'            WHEN ISNULL(@Bodega,'0') <> '0' THEN @Bodega          END)           AND T8.ItmsGrpCod LIKE           (CASE            WHEN ISNULL(@Linea,'0') = '0' THEN '%'            WHEN ISNULL(@Linea,'0') <> '0' THEN @Linea          END)         AND T6.[Code] LIKE           (CASE            WHEN ISNULL(@Sucursal,'0') = '0' THEN '%'            WHEN ISNULL(@Sucursal,'0') <> '0' THEN @Sucursal          END)       AND T7.ItmsGrpCod LIKE          (CASE            WHEN ISNULL(@familia,'0') = '0' THEN '%'            WHEN ISNULL(@familia,'0') <> '0' THEN @familia          END)         GROUP BY T0.ItemCode, T7.ItemName, T9.CardName, T1.U_TAI_CostoRep,T8.ItmsGrpNam, T0.Warehouse, T6.[Location], T7.U_TAI_Envase, T7.U_TAI_UndMed, T7.U_TAI_Capacidad      END      IF @Opcion = '20'        BEGIN      SELECT COUNT(ItemCode) AS Cuenta FROM (      SELECT  distinct       T0.ItemCode      ,REPLACE(T7.ItemName,'#','') AS 'ItemName'      ,ISNULL(T9.CardName,'SP') AS CardCode      ,ISNULL(T8.ItmsGrpNam,'') AS 'LineaNegocio'      ,ISNULL(T7.U_TAI_Envase,'SE') AS 'Envase'      ,ISNULL((CASE       WHEN T7.U_TAI_UndMed = 'X' THEN 'Ninguno'       WHEN T7.U_TAI_UndMed = 'L' THEN 'LT'       WHEN T7.U_TAI_UndMed = 'K' THEN 'KG'       ELSE 'SU'      END),'') AS 'UnidadMedida'      ,ISNULL(replace(convert(nvarchar(50),convert(numeric(32,2),T7.U_TAI_Capacidad)),'.',','),0) AS 'Capacidad'      ,T0.Warehouse       ,ISNULL(T6.[Location],'') AS 'Sucursal'      ,ISNULL(CONVERT(INT,(SUM(T0.InQty) - SUM(T0.OutQty))),0) AS 'Stock'      ,CONVERT(numeric(32,0),(ISNULL(T1.U_TAI_CostoRep,0) * ISNULL(CONVERT(INT,(SUM(T0.InQty) - SUM(T0.OutQty))),0))) AS 'PxQ'      ,ISNULL(REPLACE(ISNULL(CONVERT(NUMERIC(32,2),(SELECT SUM(TT0.Quantity) FROM INV1 TT0 LEFT JOIN OINV TT1 ON TT0.DocEntry = TT1.DocEntry WHERE TT0.ItemCode = T0.ItemCode AND TT0.WhsCode = T0.Warehouse  AND TT1.CANCELED <> 'Y' AND TT0.LineStatus <> 'C' AND (TT1.DocDate >= CONVERT(NVARCHAR(10),@fechaVtaIni,102) AND TT1.DocDate <= CONVERT(NVARCHAR(10),@fechaVtaFin,102)))),0),'.',','),0) AS 'Vendido'       ,ISNULL(MONTH(@Fecha),0) AS Mes      ,CONVERT(NUMERIC(32,2),(CASE        WHEN (SUM(T0.InQty) - SUM(T0.OutQty)) > 0 AND (SELECT SUM(TT0.Quantity) FROM INV1 TT0 LEFT JOIN OINV TT1 ON TT0.DocEntry = TT1.DocEntry WHERE TT0.ItemCode = T0.ItemCode AND TT0.WhsCode = T0.Warehouse  AND TT1.CANCELED <> 'Y' AND TT0.LineStatus <> 'C' AND (TT1.DocDate >= CONVERT(NVARCHAR(10),@fechaVtaIni,102) AND TT1.DocDate <= CONVERT(NVARCHAR(10),@fechaVtaFin,102)))  > 0 THEN (SUM(T0.InQty) - SUM(T0.OutQty)) /(SELECT SUM(TT0.Quantity) FROM INV1 TT0 LEFT JOIN OINV TT1 ON TT0.DocEntry = TT1.DocEntry WHERE TT0.ItemCode = T0.ItemCode AND TT0.WhsCode = T0.Warehouse  AND TT1.CANCELED <> 'Y' AND TT0.LineStatus <> 'C' AND (TT1.DocDate >= CONVERT(NVARCHAR(10),@fechaVtaIni,102) AND TT1.DocDate <= CONVERT(NVARCHAR(10),@fechaVtaFin,102)))/@diasTasa        ELSE 0      END)) AS 'Tasa'      FROM OINM T0        LEFT JOIN OITW T1 ON T0.ItemCode = T1.ItemCode AND T0.Warehouse = T1.WhsCode       LEFT JOIN OWHS T4 ON T0.Warehouse = T4.WhsCode       LEFT JOIN OLCT T6 ON T4.[Location] = T6.Code       LEFT JOIN OITM T7 ON T0.ItemCode = T7.ItemCode        LEFT JOIN OITB T8 ON T7.ItmsGrpCod = T8.ItmsGrpCod       LEFT JOIN OCRD T9 ON T7.CardCode = T9.CardCode      WHERE T0.DocDate <= @Fecha         AND T0.ItemCode LIKE           (CASE            WHEN ISNULL(@Item,'0') = '0' THEN '%'            WHEN ISNULL(@Item,'0') <> '0' THEN @Item          END)           AND T0.Warehouse LIKE           (CASE            WHEN ISNULL(@Bodega,'0') = '0' THEN '%'            WHEN ISNULL(@Bodega,'0') <> '0' THEN @Bodega          END)           AND T8.ItmsGrpCod LIKE           (CASE            WHEN ISNULL(@Linea,'0') = '0' THEN '%'            WHEN ISNULL(@Linea,'0') <> '0' THEN @Linea          END)         AND T6.[Code] LIKE           (CASE            WHEN ISNULL(@Sucursal,'0') = '0' THEN '%'            WHEN ISNULL(@Sucursal,'0') <> '0' THEN @Sucursal          END)       AND T7.ItmsGrpCod LIKE          (CASE            WHEN ISNULL(@familia,'0') = '0' THEN '%'            WHEN ISNULL(@familia,'0') <> '0' THEN @familia          END)         GROUP BY T0.ItemCode, T7.ItemName, T9.CardName, T1.U_TAI_CostoRep,T8.ItmsGrpNam, T0.Warehouse, T6.[Location], T7.U_TAI_Envase, T7.U_TAI_UndMed, T7.U_TAI_Capacidad) AS Productos    END  END  
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_ingrediente_activo]  @opcion   integer  AS  BEGIN   if @opcion=10   begin    select Code        as IngCodigo          ,upper(Name) as IngNombre            from [@TAI_INGACTIVO]           order by Name   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_interes_producto]   @opcion           integer  ,@cliente          varchar(20)  ,@bodega           varchar(20)  ,@producto         varchar(30)  ,@condicionPago    integer  ,@totalLinea       float  ,@tipoCalculo      varchar(8)   ,@tasaInteres      float      =0  ,@fechaVencimiento varchar(10)=''  ,@fechaCompra      varchar(10)=''  AS  BEGIN   declare @diferenciaDias    integer      if @opcion=10   begin    declare @diasProducto      integer      declare @diasCondicionPago integer      set @diasCondicionPago=(select ExtraDays        from OCTG where GroupNum = @condicionPago)      set @diasProducto     =(select U_TAI_DiasPago   from OITM where ItemCode = @producto)      set @diferenciaDias   =@diasCondicionPago - @diasProducto        select top 1            case when @tipoCalculo='Final'    then (case when round(isnull(((((@totalLinea*PRMT.U_ValorNumerico)/100)/30)*@DiferenciaDias),0),0)                <0 then 0 else round(isnull(((((@totalLinea*PRMT.U_ValorNumerico)/100)/30)*@DiferenciaDias),0),0)                 end)                        when @tipoCalculo='FinalCon' then (case when @totalLinea-round(isnull((@totalLinea/(100+(PRMT.U_ValorNumerico*(@DiferenciaDias)/30)))*100,0),0)<0 then 0 else @totalLinea-round(isnull((@totalLinea/(100+(PRMT.U_ValorNumerico*(@DiferenciaDias)/30)))*100,0),0) end)                 end  as ArtInteres              from [@VK_OPAR] PRMT            ,OITM                   where OITM.InvntItem    ='Y'         and PRMT.Code         ='TASAINTM'         and OITM.ItemCode     =@producto         and @diasCondicionPago>@diasProducto       end   if @opcion=20   begin    set @diferenciaDias   =isnull((select datediff(dd,convert(datetime,@fechaCompra,103),convert(datetime,@fechaVencimiento,103))),0)    select top 1            case when @tipoCalculo='Final'    then (case when round(isnull(((((@totalLinea*@tasaInteres)/100)/30)*@DiferenciaDias),0),0)                <0 then 0 else round(isnull(((((@totalLinea*@tasaInteres)/100)/30)*@DiferenciaDias),0),0)                 end)                        when @tipoCalculo='FinalCon' then (case when @totalLinea-round(isnull((@totalLinea/(100+(@tasaInteres*(@DiferenciaDias)/30)))*100,0),0)<0 then 0 else @totalLinea-round(isnull((@totalLinea/(100+(@tasaInteres*(@DiferenciaDias)/30)))*100,0),0) end)                 end  as ArtInteres                    from OITM             where OITM.InvntItem='Y'         and OITM.ItemCode =@producto      end    END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_inventario]   @opcion   integer  ,@producto varchar(30)   ,@operador nvarchar(50)=''  AS  BEGIN      if @opcion=10      begin    select OITW.WhsCode                                   as BodCodigo       ,left(OWHS.WhsName,18)                          as BodNombre       ,isnull(OITW.U_TAI_StockReal, 0)                as ArtStockFisico       ,OITW.IsCommited                                as ArtStockPedido       ,OITW.OnOrder                                   as ArtStockOrdenado       ,(OITW.OnHand + OITW.OnOrder - OITW.IsCommited) as ArtStockDisponible      from OITW          inner join OWHS on OWHS.WhsCode =OITW.WhsCode         inner join OITM on OITM.ItemCode=OITW.ItemCode       where OITW.ItemCode = @producto          and (OITW.OnHand>0 or OITW.IsCommited>0 or OITW.OnOrder>0)         and OITM.InvntItem = 'Y'   end   IF @opcion=20   begin    select 1                                        as BodAutoriza       ,T0.WhsCode                               as BodCodigo        ,T1.WhsName                               as BodNombre        ,isnull(T0.U_TAI_StockReal, 0)            as ArtStockFisico        ,T0.IsCommited                            as ArtStockPedido       ,T0.OnOrder                               as ArtStockOrdenado        ,(T0.OnHand + T0.OnOrder - T0.IsCommited) as ArtStockDisponible       ,isnull(U_TAI_Moneda,'')                  as ArtMoneda           ,isnull(U_TAI_CostoComercial,0)           as ArtCosto            from OITW T0         join OWHS T1 on T0.WhsCode =T1.WhsCode         join OITM T2 on T2.ItemCode=T0.ItemCode      where T0.ItemCode = @producto     and  (T0.OnHand > 0 OR T0.IsCommited > 0 OR  T0.OnOrder>0)     and not exists(select * from [@VK_WHUD] where U_WhsCode=T0.WhsCode and Code=@operador)      and T2.InvntItem = 'Y'    union       select 0                                        as BodAutoriza       ,T0.WhsCode                               as BodCodigo        ,T1.WhsName                               as BodNombre        ,isnull(T0.U_TAI_StockReal, 0)            as ArtStockFisico        ,T0.IsCommited                            as ArtStockPedido       ,T0.OnOrder                               as ArtStockOrdenado        ,(T0.OnHand + T0.OnOrder - T0.IsCommited) as ArtStockDisponible       ,isnull(U_TAI_Moneda,'')                  as ArtMoneda           ,isnull(U_TAI_CostoComercial,0)           as ArtCosto         from OITW T0         join OWHS T1 on T0.WhsCode =T1.WhsCode         join OITM T2 on T2.ItemCode=T0.ItemCode     where T0.ItemCode = @producto              and T0.WhsCode<>'00'       and exists(select * from [@VK_WHUD] where U_WhsCode=T0.WhsCode and Code=@operador)        and T2.InvntItem = 'Y'     order by 1      end   END
create PROCEDURE [dbo].[tai_vw_sp2_select_linea]   @opcion   int  ,@grupo    int  ,@subgrupo int  ,@linea    int  ,@usuario  varchar(10)=''  AS  BEGIN   if @opcion=10   begin    select lin_codigo as LinCodigo       ,lin_nombre as LinNombre      from matriz_descto_linea     order by 2    end   if @opcion=20   begin    select l.lin_codigo as LinCodigo       ,l.lin_nombre as LinNombre      from matriz_descto_grupo               g           inner join matriz_descto_subgrupo s on s.gru_codigo=g.gru_codigo        inner join matriz_descto_linea    l on l.sub_codigo=s.sub_codigo     where g.gru_codigo=(case when @grupo   =0 then g.gru_codigo else @grupo    end)       and s.sub_codigo=(case when @subgrupo=0 then s.sub_codigo else @subgrupo end)       and l.lin_codigo=(case when @linea   =0 then l.lin_codigo else @linea    end)     order by 2    end   if @opcion=30   begin    if not exists (select distinct d.det_codusuario from matriz_descto_detalle d where d.det_codcargo='GL' and det_codusuario=@usuario)     set @usuario=''    select distinct        l.lin_codigo as LinCodigo       ,l.lin_nombre as LinNombre      from matriz_descto_grupo               g        inner join matriz_descto_subgrupo s on s.gru_codigo  =g.gru_codigo        inner join matriz_descto_linea    l on l.sub_codigo  =s.sub_codigo         inner join matriz_descto_detalle  d on d.det_codlinea=l.lin_codigo     where d.det_codcargo  ='GL'       and d.det_codusuario=(case when @usuario ='' then d.det_codusuario else @usuario  end)       and g.gru_codigo    =(case when @grupo   =0  then g.gru_codigo     else @grupo    end)       and s.sub_codigo    =(case when @subgrupo=0  then s.sub_codigo     else @subgrupo end)       and l.lin_codigo    =(case when @linea   =0  then l.lin_codigo     else @linea    end)     order by 2   end  END
  CREATE PROCEDURE [dbo].[tai_vw_sp2_select_liquidacion_comision]   @opcion        integer  ,@empleado      integer   ,@operador      integer  ,@año           integer  ,@mes           integer   ,@identificador integer  ,@oficina       varchar(25)  ,@linea         integer  ,@sublinea      varchar(25)  ,@docto         varchar(3)  AS  BEGIN   if @opcion=10   begin    select RES.LiqIdentificador       ,RES.CodOperador       ,RES.NomOperador       ,RES.LiqAño       ,RES.LiqMes               ,RES.TotNeto/10    as TotNeto       ,RES.TotCosto/10   as TotCosto       ,RES.TotMargen/10  as TotMargen       ,RES.PorMargen       ,RES.IndComision       ,RES.GruComision       ,RES.FinComision       ,RES.ProVacaciones       ,RES.SemCorrida       ,RES.TotComision       ,RES.FecLiquidacion       ,RES.LiqOrigen        ,case when RES.LiqTipo='L' then 'LIQUIDACION'             when RES.LiqTipo='R' then 'RELIQUIDACION'             when RES.LiqTipo='C' then 'CUARTAS COPIAS'             else 'SIN CLASIFICAR'        end LiqTipo      from comision_liquidacion_resumen RES     where ((RES.CodOperador=@empleado and RES.LiqOrigen in('A','I'))          or (RES.CodOperador=@operador and RES.LiqOrigen in('E','O')))       and year(RES.FecLiquidacion) =@año       and month(RES.FecLiquidacion)=@mes       and RES.EmiteRecursos        =2           order by RES.FecLiquidacion   end    if @opcion=11   begin    select distinct         esp_empleado       ,esp_vendedor      from comision_especial     where esp_empleado=@empleado       and esp_vendedor=@operador       and @empleado<>325        and @empleado<>480      end    if @opcion=20   begin    select RES.LiqIdentificador          ,DET.CodLinea             LinCodigo         ,upper(DET.Linea)         LinNombre         ,upper(DET.SubLinea)      SubNombre              ,DET.TD                   DocTipo       ,sum(DET.ImpteNetoML)     TotNeto            ,sum(DET.ComFinal)        FinComision             from comision_liquidacion_resumen            RES              inner join comision_liquidacion_detalle DET on DET.FecLiquidacion=RES.FecLiquidacion              where RES.LiqIdentificador=@identificador        group by RES.LiqIdentificador, DET.CodLinea, DET.SubLinea, DET.Linea, DET.TD          order by 3,4,5    end   if @opcion=21   begin    select RES.LiqIdentificador          ,left(upper(DET.Oficina),10)           OfiNombre            ,DET.Fecha                             DocFecha         ,ltrim(rtrim(DET.TD))                  DocTipo            ,DET.Folio                             FolNumero         ,DET.CuartaCopia                       Doc4taCopia            ,left(upper(DET.NombreSN),25)          CliNombre          ,DET.CodLinea                          LinCodigo                ,upper(DET.Linea)                      LinNombre            ,upper(DET.SubLinea)                   SubNombre            ,DET.WhsCode                           BodNombre            ,left(upper(DET.Descripción),25)       ArtNombre            ,left(upper(DET.UnidadMedida),15)      ArtMedida            ,DET.Cantidad                          ArtCantidad            ,DET.PVUnitNeto                        VenNeto            ,DET.ImpteNetoML                       TotNeto            ,DET.Margen                            VenMargen            ,cast(DET.[Comis%Est] as numeric(9,3)) PorComision          ,case when DET.BaseComis='V' then 'VENTA'                when DET.BaseComis='M' then 'MARGEN'                else 'SIN CLASIFICAR'           end                                   BasComision             ,DET.ComFinal                          FinComision            from comision_liquidacion_resumen            RES           inner join comision_liquidacion_detalle DET on DET.FecLiquidacion=RES.FecLiquidacion              where RES.LiqIdentificador=@identificador               and DET.CodLinea        =@linea             and DET.SubLinea        =@sublinea             and DET.TD              =@docto     order by 2,3,4      end    if @opcion=30   begin     select RES.LiqIdentificador          ,CAB.EmpCodigo            ,CAB.OpeCodigo            ,CAB.OfiCodigo            ,CAB.LinCodigo            ,CAB.OpeNombre            ,CAB.OfiNombre            ,CAB.LinNombre            ,CAB.TotNeto            ,CAB.TotMargen            ,cast(CAB.PorComision as numeric(9,3)) PorComision          ,case when CAB.BasComision='V' then 'VENTA'                when CAB.BasComision='M' then 'MARGEN'                else 'SIN CLASIFICAR'           end BasComision             ,case when CAB.NivComision='P' then 'PROPIA'                when CAB.NivComision='O' then 'OFICINA'                when CAB.NivComision='N' then 'NACIONAL'                else 'SIN CLASIFICAR'           end NivComision                       ,CAB.FinComision           from comision_liquidacion_resumen             RES           inner join comision_liquidacion_especial CAB on CAB.FecLiquidacion=RES.FecLiquidacion           where RES.LiqIdentificador=@identificador     order by CAB.LinNombre           end   if @opcion=31   begin    select RES.LiqIdentificador          ,left(upper(DET.Oficina),10)           OfiNombre            ,DET.Fecha                             DocFecha         ,ltrim(rtrim(DET.TD))                  DocTipo            ,DET.Folio                             FolNumero         ,DET.CuartaCopia                       Doc4taCopia            ,left(upper(DET.NombreSN),25)          CliNombre          ,DET.CodLinea                          LinCodigo                ,upper(DET.Linea)                      LinNombre            ,upper(DET.SubLinea)                   SubNombre            ,DET.WhsCode                           BodNombre            ,left(upper(DET.Descripción),25)       ArtNombre            ,left(upper(DET.UnidadMedida),15)      ArtMedida            ,DET.Cantidad                          ArtCantidad            ,DET.PVUnitNeto                        VenNeto          ,DET.ImpteNetoML                       TotNeto          ,DET.Margen                            VenMargen          ,cast(DET.PorComision as numeric(9,3)) PorComision          ,case when DET.BasComision='V' then 'VENTA'                when DET.BasComision='M' then 'MARGEN'                else 'SIN CLASIFICAR'           end                                   BasComision                    ,DET.EspComision                       FinComision            from comision_liquidacion_resumen                     RES           inner join comision_liquidacion_especial         CAB on CAB.FecLiquidacion=RES.FecLiquidacion        inner join comision_liquidacion_detalle_especial DET on DET.FecLiquidacion=CAB.FecLiquidacion and DET.Oficina=CAB.OfiNombre and DET.CodEmpleado=CAB.EmpCodigo and DET.CodLinea=CAB.LinCodigo              where RES.LiqIdentificador=@identificador           and CAB.OfiNombre       =@oficina          and CAB.EmpCodigo       =@empleado              and CAB.LinCodigo       =@linea        order by 2,3,4    end    if @opcion=40   begin    select 0                    LiqIdentificador          ,CodLinea             LinCodigo         ,upper(Linea)         LinNombre         ,upper(SubLinea)      SubNombre              ,TD                   DocTipo       ,sum(ImpteNetoML)     TotNeto            ,sum(ComFinal)        FinComision             from comision_detalle_provisorio     where CodOperador=@operador       and CodLinea in(101,102,103,104,105,106,107,108,109,110,111,112,113,114,115,116,117,125,126,127,128,130,131,133)     group by CodLinea, SubLinea, Linea, TD       order by 2,3,4     end    if @opcion=41   begin    select 0                                  as LiqIdentificador          ,left(upper(Oficina),10)            as OfiNombre       ,Fecha                              as DocFecha        ,TD                                 as DocTipo       ,isnull(Folio,0)                    as FolNumero       ,CuartaCopia                        as Doc4taCopia       ,left(upper(NombreSN),25)           as CliNombre                  ,CodLinea                           as LinCodigo       ,upper(Linea)                       as LinNombre       ,SubLinea                           as SubNombre        ,WhsCode                            as BodNombre          ,left(upper(Descripción),25)        as ArtNombre         ,left(upper(UnidadMedida),15)       as ArtMedida         ,Cantidad                           as ArtCantidad          ,PVUnitNeto                         as VenNeto         ,ImpteNetoML                        as TotNeto         ,Margen                             as VenMargen         ,cast([Comis%Est] as numeric(9,3))  as PorComision       ,case when BaseComis='V' then 'VENTA'       when BaseComis='M' then 'MARGEN'       else 'SIN CLASIFICAR'        end                                as BasComision          ,ComFinal                           as FinComision                  from comision_detalle_provisorio         where CodOperador=@operador             and CodLinea   =@linea             and SubLinea   =@sublinea             and TD         =@docto         end    if @opcion=50   begin    select 0                                           as LiqIdentificador          ,ESP.esp_empleado                            as EmpCodigo  ---       ,ESP.esp_vendedor                            as OpeCodigo  ---       ,ESP.esp_oficina                             as OfiCodigo         ,DET.CodLinea                                as LinCodigo         ,upper(isnull(VEN.SlpName,isnull(EMP.lastName,'')+' ' +isnull(EMP.middleName,'')+ ', ' +isnull(EMP.firstName,''))) as OpeNombre  ---         ,upper(DET.Oficina)                          as OfiNombre         ,upper(DET.Linea)                            as LinNombre         ,cast(sum(DET.ImpteNetoML) as numeric(19,0)) as TotNeto         ,cast(sum(DET.Margen) as numeric(19,0))      as TotMargen         ,cast(ESP.esp_comision as numeric(9,3))      as PorComision               ,case when ESP.esp_base='V' then 'VENTA'       when ESP.esp_base='M' then 'MARGEN'       else 'SIN CLASIFICAR'        end                                         as BasComision          ,case when ESP.esp_nivel='P' then 'PROPIA'       when ESP.esp_nivel='O' then 'OFICINA'       when ESP.esp_nivel='N' then 'NACIONAL'       else 'SIN CLASIFICAR'        end                                         as NivComision          ,cast((((case when ESP.esp_base='V' then cast(sum(DET.ImpteNetoML) as numeric(19,0)) else cast(sum(DET.Margen) as numeric(19,0)) end)*ESP.esp_comision)/100) as numeric(19,0)) as FinComision        from comision_especial                      ESP          left  join comision_detalle_provisorio DET on DET.CodLinea=ESP.esp_linea          left  join OHEM                        EMP on EMP.empID   =ESP.esp_empleado          left  join OSLP                        VEN on VEN.SlpCode =ESP.esp_vendedor           where ESP.esp_empleado=@empleado       and ESP.esp_vendedor=@operador        and DET.VtaMarCompartida in(0,1)         and (        (ESP.esp_nivel='P' and DET.CodOperador=ESP.esp_vendedor)       or (ESP.esp_nivel='O' and DET.CodOficina =ESP.esp_oficina)       or (ESP.esp_nivel='N')          )     group by EMP.lastName,EMP.middleName,EMP.firstName,VEN.SlpName,ESP.esp_empleado,ESP.esp_vendedor,ESP.esp_oficina,DET.CodLinea,DET.Oficina,DET.Linea,ESP.esp_comision,ESP.esp_base,ESP.esp_nivel       order by DET.Linea    end   if @opcion=51   begin    select 0                                       as LiqIdentificador          ,left(upper(DET.Oficina),10)             as OfiNombre       ,DET.Fecha                               as DocFecha        ,DET.TD                                  as DocTipo       ,isnull(DET.Folio,0)                     as FolNumero       ,DET.CuartaCopia                         as Doc4taCopia       ,left(upper(DET.NombreSN),25)            as CliNombre                  ,DET.CodLinea                            as LinCodigo       ,upper(DET.Linea)                        as LinNombre       ,DET.SubLinea                            as SubNombre        ,DET.WhsCode                             as BodNombre          ,left(upper(DET.Descripción),25)         as ArtNombre         ,left(upper(DET.UnidadMedida),15)        as ArtMedida         ,DET.Cantidad                            as ArtCantidad            ,DET.PVUnitNeto                          as VenNeto         ,DET.ImpteNetoML                         as TotNeto         ,DET.Margen                              as VenMargen       ,cast(ESP.esp_comision as numeric(9,3))  as PorComision               ,case when ESP.esp_base='V' then 'VENTA'       when ESP.esp_base='M' then 'MARGEN'       else 'SIN CLASIFICAR'        end                                     as BasComision          ,cast((((case when ESP.esp_base='V' then cast((DET.ImpteNetoML) as numeric(19,0)) else cast((DET.Margen) as numeric(19,0)) end)*ESP.esp_comision)/100) as numeric(19,0)) as FinComision        from comision_especial                      ESP          left  join comision_detalle_provisorio DET on DET.CodLinea=ESP.esp_linea          left  join OHEM                        EMP on EMP.empID   =ESP.esp_empleado          left  join OSLP                        VEN on VEN.SlpCode =ESP.esp_vendedor           where ESP.esp_empleado=@empleado       and ESP.esp_vendedor=@operador        and DET.VtaMarCompartida in(0,1)         and (        (ESP.esp_nivel='P' and DET.CodOperador=ESP.esp_vendedor)       or (ESP.esp_nivel='O' and DET.CodOficina =ESP.esp_oficina)       or (ESP.esp_nivel='N')          )       and DET.CodLinea    =@linea             and DET.Oficina     =@oficina     order by DET.Linea    end    END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_matriz_descto_detalle]   @opcion   int    ,@linea    int  ,@sucursal int  ,@usuario  varchar(10)  ,@backup   varchar(10)  AS  BEGIN   if @opcion=10   begin    select D.det_codlinea               as LinCodigo          ,upper(L.lin_nombre)          as LinNombre                ,upper(D.det_codusuario)      as UsuCodigo                ,upper(U.U_NAME)              as UsuNombre       ,D.det_codsucursal            as SucCodigo                ,upper(S.[Name])              as SucNombre                ,D.det_codcargo               as CarCodigo          ,upper(C.par_nombre)          as CarNombre                ,upper(D.det_codautorizacion) as AutCodigo                ,D.det_codzona                as ZonCodigo          ,upper(Z.par_nombre)          as ZonNombre                ,upper(D.det_codbackup)       as BkpCodigo       ,upper(B.U_NAME)              as BkpNombre      from matriz_descto_linea              L           inner join matriz_descto_detalle D on D.det_codlinea=L.lin_codigo        inner join OUBR                  S on S.Code        =D.det_codsucursal        inner join OUSR                  U on U.USER_CODE   =D.det_codusuario              inner join OUSR                  B on B.USER_CODE   =D.det_codbackup           inner join TAI_VW_Parametros     Z on Z.par_enlace  =D.det_codzona  and Z.par_grupo='zona'           inner join TAI_VW_Parametros     C on C.par_enlace  =D.det_codcargo and C.par_grupo='cargo'     where L.lin_codigo     =(case when @linea   <>0   then @linea    else L.lin_codigo      end)       and D.det_codsucursal=(case when @sucursal<>0   then @sucursal else D.det_codsucursal end)        and D.det_codusuario =(case when @usuario <>'x' then @usuario  else D.det_codusuario  end)        and D.det_codbackup  =(case when @backup  <>'x' then @backup   else D.det_codbackup   end)            order by 9, 7, 4, 6, 13, 1   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_matriz_descto_resumen]   @opcion    int  ,@grupo     int  ,@subgrupo  int  ,@linea     int  ,@proveedor varchar(25)  ,@producto  nvarchar(50)  ,@usuario   varchar(10) ='x'  AS  BEGIN   if not exists (select distinct d.det_codusuario from matriz_descto_detalle d where d.det_codcargo='GL' and det_codusuario=@usuario)   begin    set @usuario='x'   end   if @opcion=10   begin    select G.gru_codigo                          as GruCodigo       ,G.gru_nombre                          as GruNombre       ,S.sub_codigo                          as SubCodigo       ,S.sub_nombre                          as SubNombre       ,L.lin_codigo                          as LinCodigo       ,upper(L.lin_nombre)                   as LinNombre       ,isnull(P.CardCode,'')                 as ProCodigo       ,left(isnull(P.CardName,''),20)        as ProNombre       ,A.ItemCode collate database_default   as ArtCodigo       ,left(upper(A.ItemName),40)            as ArtNombre       ,isnull(R.res_nivel0,0)                as AutNivel0       ,isnull(R.res_nivel1,0)                as AutNivel1       ,isnull(R.res_nivel2,0)                as AutNivel2       ,isnull(R.res_nivel3,0)                as AutNivel3       ,isnull(R.res_nivel4,0)                as AutNivel4       ,0                                     as ArtCapacidad       ,''                                    as ArtMedida       ,''                                    as ArtMoneda       ,0                                     as ArtCosto       ,0                                     as ArtMargen       ,0                                     as ArtPrecioVta       ,0                                     as ArtCostoPP      from OITM                              A        inner join OITB                   E on E.ItmsGrpCod  =A.ItmsGrpCod        left  join OCRD                   P on P.CardCode    =A.CardCode        inner join matriz_descto_linea    L on L.lin_codigo  =E.ItmsGrpCod        inner join matriz_descto_subgrupo S on S.sub_codigo  =L.sub_codigo        inner join matriz_descto_grupo    G on G.gru_codigo  =S.gru_codigo        left  join matriz_descto_resumen  R on R.res_codlinea=L.lin_codigo   and R.res_codproducto=A.ItemCode        inner join matriz_descto_detalle  D on D.det_codlinea=R.res_codlinea     where A.frozenFor       ='N'       and A.InvntItem       ='Y'       and D.det_codcargo    ='GL'       and G.gru_codigo      =(case when @grupo    =0   then G.gru_codigo       else @grupo     end)       and S.sub_codigo      =(case when @subgrupo =0   then S.sub_codigo       else @subgrupo  end)       and L.lin_codigo      =(case when @linea    =0   then L.lin_codigo       else @linea     end)       and R.res_codproveedor=(case when @proveedor='x' then R.res_codproveedor else @proveedor end)        and R.res_codproducto =(case when @producto ='x' then R.res_codproducto  else @producto  end)       and D.det_codusuario  =(case when @usuario  ='x' then D.det_codusuario   else @usuario   end)     order by 2,4,6,8   end   if @opcion=15   begin    select count(*) CanRegistros      from OITM                              A        left  join (          select ItemCode          ,U_TAI_Moneda                                     as Moneda          ,cast(avg(U_TAI_CostoComercial) as numeric(18,2)) as Costo          ,(case when cast(avg(U_TAI_PrecioVenta) as numeric(18,2))<>0               then cast(((cast(avg(U_TAI_PrecioVenta) as numeric(18,2))-cast(avg(U_TAI_CostoComercial) as numeric(18,2)))/cast(avg(U_TAI_PrecioVenta) as numeric(18,2)))*1 as numeric(18,4))               else 0            end)                                            as Margen          ,cast(avg(U_TAI_PrecioVenta) as numeric(18,2))    as Venta         from OITW            where right(WhsCode,3)='PRT'          and U_TAI_CostoComercial is not null          and U_TAI_CostoComercial>0           --and U_TAI_Moneda is not null           --and U_TAI_Moneda<>''           group by ItemCode, U_TAI_Moneda          )                      V on V.ItemCode    =A.ItemCode        inner join OITB                   E on E.ItmsGrpCod  =A.ItmsGrpCod        left  join OCRD                   P on P.CardCode    =A.CardCode        inner join matriz_descto_linea    L on L.lin_codigo  =E.ItmsGrpCod        inner join matriz_descto_subgrupo S on S.sub_codigo  =L.sub_codigo        inner join matriz_descto_grupo    G on G.gru_codigo  =S.gru_codigo        left  join matriz_descto_resumen  R on R.res_codlinea=L.lin_codigo   and R.res_codproducto=A.ItemCode                 inner join matriz_descto_detalle  D on D.det_codlinea=R.res_codlinea        where A.frozenFor       ='N'       and A.InvntItem       ='Y'          and D.det_codcargo    ='GL'       and G.gru_codigo      =(case when @grupo    =0   then G.gru_codigo       else @grupo     end)       and S.sub_codigo      =(case when @subgrupo =0   then S.sub_codigo       else @subgrupo  end)       and L.lin_codigo      =(case when @linea    =0   then L.lin_codigo       else @linea     end)       and R.res_codproveedor=(case when @proveedor='x' then R.res_codproveedor else @proveedor end)        and R.res_codproducto =(case when @producto ='x' then R.res_codproducto  else @producto  end)       and D.det_codusuario  =(case when @usuario  ='x' then D.det_codusuario   else @usuario   end)        end   if @opcion=20   begin    select G.gru_codigo                                      as GruCodigo       ,G.gru_nombre                                      as GruNombre       ,S.sub_codigo                                      as SubCodigo       ,S.sub_nombre                                      as SubNombre       ,L.lin_codigo                                      as LinCodigo       ,L.lin_nombre                                      as LinNombre       ,isnull(P.CardCode,'...')                          as ProCodigo       ,isnull(P.CardName,'...')                          as ProNombre       ,A.ItemCode collate database_default               as ArtCodigo       ,upper(replace(replace(replace(ItemName,char(34), 'in'),char(39), 'in'),char(35), 'no')) as ArtNombre       ,isnull(R.res_nivel0,0)                            as AutNivel0       ,isnull(R.res_nivel1,0)                            as AutNivel1       ,isnull(R.res_nivel2,0)                            as AutNivel2        ,isnull(R.res_nivel3,0)                            as AutNivel3       ,isnull(R.res_nivel4,0)                            as AutNivel4       ,cast(isnull(A.U_TAI_Capacidad,0) as numeric(9,2)) as ArtCapacidad       ,isnull(A.U_TAI_UndMed,'...')                      as ArtMedida       ,isnull(V.Moneda,'...')                            as ArtMoneda       ,isnull(V.Costo,0)                                 as ArtCosto       ,isnull(V.Margen,0)                                as ArtMargen       ,isnull(V.Venta,0)                                 as ArtPrecioVta       ,cast(isnull(A.U_ValAcum,0) as numeric(12,2))      as ArtCostoPP      from OITM                              A        left  join (          select ItemCode          ,U_TAI_Moneda                                     as Moneda          ,cast(avg(U_TAI_CostoComercial) as numeric(18,2)) as Costo          ,(case when cast(avg(U_TAI_PrecioVenta) as numeric(18,2))<>0               then cast(((cast(avg(U_TAI_PrecioVenta) as numeric(18,2))-cast(avg(U_TAI_CostoComercial) as numeric(18,2)))/cast(avg(U_TAI_PrecioVenta) as numeric(18,2)))*1 as numeric(18,4))               else 0            end)                                            as Margen          ,cast(avg(U_TAI_PrecioVenta) as numeric(18,2))    as Venta         from OITW            where right(WhsCode,3)='PRT'          and U_TAI_CostoComercial is not null          and U_TAI_CostoComercial>0           --and U_TAI_Moneda is not null           --and U_TAI_Moneda<>''           group by ItemCode, U_TAI_Moneda          )                      V on V.ItemCode    =A.ItemCode        inner join OITB                   E on E.ItmsGrpCod  =A.ItmsGrpCod        left  join OCRD                   P on P.CardCode    =A.CardCode        inner join matriz_descto_linea    L on L.lin_codigo  =E.ItmsGrpCod        inner join matriz_descto_subgrupo S on S.sub_codigo  =L.sub_codigo        inner join matriz_descto_grupo    G on G.gru_codigo  =S.gru_codigo        left  join matriz_descto_resumen  R on R.res_codlinea=L.lin_codigo   and R.res_codproducto=A.ItemCode                 inner join matriz_descto_detalle  D on D.det_codlinea=R.res_codlinea        where A.frozenFor       ='N'       and A.InvntItem       ='Y'          and D.det_codcargo    ='GL'       and G.gru_codigo      =(case when @grupo    =0   then G.gru_codigo       else @grupo     end)       and S.sub_codigo      =(case when @subgrupo =0   then S.sub_codigo       else @subgrupo  end)       and L.lin_codigo      =(case when @linea    =0   then L.lin_codigo       else @linea     end)       and R.res_codproveedor=(case when @proveedor='x' then R.res_codproveedor else @proveedor end)        and R.res_codproducto =(case when @producto ='x' then R.res_codproducto  else @producto  end)       and D.det_codusuario  =(case when @usuario  ='x' then D.det_codusuario   else @usuario   end)          order by 2,4,6,8   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_menu_sistema]   @opcion  integer  ,@perfil  integer   --,@usuario varchar(50)  AS  BEGIN   if @opcion=10   begin    select MED.mod_nombre ModNombre       ,OPC.opc_nombre OpcNombre       ,OPC.opc_pagina OpcPagina      from menu_sistema_modulo MED        inner join menu_sistema_opcion OPC on OPC.id_modulo=MED.id_modulo        where opc_vigente='S'          and (            (@perfil=1 and opc_perfil1=1)           or  (@perfil=2 and opc_perfil2=1)           or  (@perfil=3 and opc_perfil3=1)        )           --and not (MED.mod_nombre='VENTAS' and @usuario in ('jbarros','aperez','avera','lvasquez','delgart','bfernandez','creyes'))     order by MED.mod_orden, OPC.opc_orden      end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_mes]  AS  BEGIN   select cast(Code as int) as MesCodigo         ,upper(Name)       as MesNombre     from [@TAI_P_MES]    order by cast(Code as int)  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_monitor_autorizacion_resumen]   @opcion integer   ,@cliente nvarchar(15)  ,@estado nvarchar(1)  ,@desde  nvarchar(8)  ,@hasta  nvarchar(8)  ,@operador nvarchar(20)  ,@pagina numeric(5,1)  AS  BEGIN   if @desde=''     set @desde=convert(nvarchar(8),getdate()-7,112)   if @hasta=''     set @hasta=convert(nvarchar(8),getdate(),112)   if @opcion=10   begin    select (count(DocEntry/10))   as DocPagina      from ODRF as OD           join TAI_TB_DISPATCHER as DI on OD.DocEntry=DI.Codigo_Borrador     where (OD.U_Estado_Aut='P')       and (OD.CardCode           =(case when @cliente='' then OD.CardCode else @cliente end))        and (convert(nvarchar(8),OD.DocDate,112) between @desde and @hasta)     --and (OD.U_Estado_Aut       =@estado)       and (DI.Estado_Autorizacion=@estado)       and (DI.Codigo_Autorizador = @operador or DI.Aut_Backup = @operador)   end   if @opcion=20    begin          select *       from (select row_number() over (order by DocFecha desc) as RowNum        ,T0.*      from (select distinct          OD.DocEntry                  as DocEntry         ,OD.DocNum                    as DocCodigo           ,OD.TaxDate                   as EntFecha           ,OD.DocDate                   as DocFecha           ,OD.DocDueDate                as VenFecha           ,left(OD.CardName,35)         as CliNombre           ,OD.DocTotal                  as DocTotal         ,(case when DI.Codigo_Autorizador=@operador then 'DIRECTO'               when DI.Aut_Backup        =@operador then 'BACKUP'             else  'DIRECTO'           end)                         as AutTipo         ,DI.Id                        as DisCodigo         ,DI.Tipo_Autorizacion         as DisConcepto         ,(case when DI.Codigo_Autorizador=@operador then 0               when DI.Aut_Backup        =@operador then 1             else 0           end)                         as DisTipo         ,(case when OD.U_TAI_TipoVenta='ventaBodega'           then 'BODEGA PROPIA'             when OD.U_TAI_TipoVenta='ventaConsignada'       then 'CONSIGNADA'             when OD.U_TAI_TipoVenta='ventaPuestoFundo'      then 'PUESTO FUNDO'             when OD.U_TAI_TipoVenta='ventaCalzadaProveedor' then 'CALZADA PROVEEDOR'             when OD.U_TAI_TipoVenta='ventaCostoEspecial'    then 'COSTO ESPECIAL'             when OD.U_TAI_TipoVenta='ventaLiquidacion'      then 'LIQUIDACION'             else 'SIN CLASIFICAR'          end)                         as VenTipo                              ,upper(SC.Remark)             as OfiNombre         from ODRF as OD          inner join TAI_TB_DISPATCHER as DI on OD.DocEntry=DI.Codigo_Borrador          inner join NNM1              as SC on SC.Series  =OD.Series          where (OD.U_Estado_Aut='P')         and (OD.CardCode           =(case when @cliente='' then OD.CardCode else @cliente end))          and (convert(nvarchar(8),OD.DocDate,112) between @desde and @hasta)          --and (OD.U_Estado_Aut       =@estado)         and (DI.Estado_Autorizacion=@estado)         and (DI.Codigo_Autorizador =@operador or DI.Aut_Backup=@operador)           ) as T0      )      as RowConstrainedResult where RowNum>=((@pagina*10)-9) and RowNum <= (@pagina*10)      order by RowNum       end  END
  CREATE PROCEDURE [dbo].[tai_vw_sp2_select_monitor_documento_detalle]   @tipo      varchar(2)  ,@documento integer  AS  BEGIN   if @tipo='OV'     begin      set @tipo=17     end     else if @tipo='FV'   begin      set @tipo='--'     end       else if @tipo='BV'   begin      set @tipo='IB'     end            else if @tipo='NC'     begin      set @tipo=14     end      if @documento>0   begin     select distinct          RDR1.ItemCode                      as ArtCodigo       ,left(upper(RDR1.Dscription),30)    as ArtNombre       ,RDR1.Quantity                      as ArtCantidad       ,RDR1.Currency                      as ArtMoneda       ,RDR1.Price                         as ArtPrecioUnitario       ,RDR1.LineTotal                     as ArtPrecioTotal       ,RDR1.DiscPrcnt                     as PorDescuento       ,isnull(RDR1.U_TAI_Interes,0)       as ArtInteres       ,isnull(RDR1.U_TAI_ImpteComis,0)    as ArtComision       ,isnull(RDR1.U_TAI_FechaEntrega,'') as FecEntrega         ,''                                 as EntFactura        ,''                                 as EntDespacho        ,''                                 as DocNC       ,'rdr1'                             as DocTipo        from ORDR        left join RDR1 on RDR1.DocEntry=ORDR.DocEntry       where 1=1       and ORDR.ObjType=@tipo          and ORDR.DocNum =@documento    union all      select distinct          INV1.ItemCode                      as ArtCodigo       ,left(upper(INV1.Dscription),30)    as ArtNombre       ,INV1.Quantity                      as ArtCantidad       ,INV1.Currency                      as ArtMoneda       ,INV1.Price                         as ArtPrecioUnitario       ,INV1.LineTotal                     as ArtPrecioTotal       ,INV1.DiscPrcnt                     as PorDescuento       ,isnull(INV1.U_TAI_Interes, 0)      as ArtInteres       ,isnull(INV1.U_TAI_ImpteComis, 0)   as ArtComision       ,isnull(INV1.U_TAI_FechaEntrega,'') as FecEntrega       --,OINV.FolioNum                      as EntFactura      --,isnull(ODLN.FolioNum, ODLN.Docnum) as EntDespacho      --,''                                 as DocNC        ,''                                 as EntFactura        ,''                                 as EntDespacho        ,''                                 as DocNC       ,'inv1'                             as DocTipo       from OINV           left join INV1 on INV1.DocEntry =OINV.DocEntry         --left join DLN1 on DLN1.BaseEntry=INV1.DocEntry and DLN1.BaseType = INV1.ObjType and DLN1.ItemCode = INV1.ItemCode         --left join ODLN on ODLN.DocEntry =DLN1.DocEntry       where 1 = 1     --and OINV.ObjType   =@tipo            and OINV.FolioPref in ('33','39')               and OINV.DocSubType=@tipo       and OINV.FolioNum  =@documento    union all      select distinct          DRF1.ItemCode                      as ArtCodigo       ,left(upper(DRF1.Dscription),30)    as ArtNombre       ,DRF1.Quantity                      as ArtCantidad       ,DRF1.Currency                      as ArtMoneda       ,DRF1.Price                         as ArtPrecioUnitario       ,DRF1.LineTotal                     as ArtPrecioTotal       ,DRF1.DiscPrcnt                     as PorDescuento       ,DRF1.U_TAI_Interes                 as ArtInteres        ,DRF1.U_TAI_ImpteComis              as ArtComision       ,isnull(DRF1.U_TAI_FechaEntrega,'') as FecEntrega           ,''                                 as EntFactura        ,''                                 as EntDespacho        ,''                                 as DocNC         ,'drf1'                             as DocTipo      from ODRF          inner join DRF1 on DRF1.docentry = ODRF.docentry       where ODRF.ObjType      =@tipo       and ODRF.DocEntry     =@documento       and ODRF.U_Estado_Aut<>'A'     union all     select distinct          RIN1.ItemCode                      as ArtCodigo       ,left(upper(RIN1.Dscription),30)    as ArtNombre       ,RIN1.Quantity                      as ArtCantidad       ,RIN1.Currency                      as ArtMoneda       ,RIN1.Price                         as ArtPrecioUnitario       ,RIN1.LineTotal                     as ArtPrecioTotal       ,RIN1.DiscPrcnt                     as PorDescuento       ,isnull(RIN1.U_TAI_Interes,0)       as ArtInteres       ,isnull(RIN1.U_TAI_ImpteComis,0)    as ArtComision        ,isnull(RIN1.U_TAI_FechaEntrega,'') as FecEntrega           ,''                                 as EntFactura        ,''                                 as EntDespacho        ,''                                 as DocNC       ,'rin1'                             as DocTipo     from ORIN        left join RIN1 on RIN1.DocEntry=ORIN.DocEntry       where 1=1       and ORIN.ObjType =@tipo          and ORIN.FolioNum=@documento    union all    select distinct          DRF1.ItemCode                      as ArtCodigo       ,left(upper(DRF1.Dscription),30)    as ArtNombre       ,DRF1.Quantity                      as ArtCantidad       ,DRF1.Currency                      as ArtMoneda       ,DRF1.Price                         as ArtPrecioUnitario       ,DRF1.LineTotal                     as ArtPrecioTotal       ,DRF1.DiscPrcnt                     as PorDescuento       ,DRF1.U_TAI_Interes                 as ArtInteres        ,DRF1.U_TAI_ImpteComis              as ArtComision       ,isnull(DRF1.U_TAI_FechaEntrega,'') as FecEntrega           ,''                                 as EntFactura        ,''                                 as EntDespacho        ,''                                 as DocNC         ,'drf2'                             as DocTipo      from ODRF          inner join DRF1 on DRF1.docentry = ODRF.docentry       where ODRF.ObjType     =17--@tipo       and ODRF.DocEntry    =@documento       and ODRF.U_Estado_Aut='A'       and not exists(select * from ORDR where ORDR.DocNum  =ODRF.DocNum and ORDR.ObjType=ODRF.ObjType and ORDR.draftKey=ODRF.DocEntry)        and not exists(select * from OINV where OINV.FolioNum=ODRF.DocEntry)       and not exists(select * from ORIN where ORIN.FolioNum=ODRF.DocEntry)   end             END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_monitor_documento_resumen]   @opcion integer  ,@cliente nvarchar(15)  ,@producto nvarchar(30)  ,@estado nvarchar(30)  ,@desde  nvarchar(8)  ,@hasta  nvarchar(8)  ,@operador integer  ,@pagina numeric(5,1)  AS  BEGIN   if @desde=''     set @desde=convert(nvarchar(8),getdate()-7,112)   if @hasta=''     set @hasta=convert(nvarchar(8),getdate(),112)   if @opcion = 10   begin    select (count(docnum/10)) as DocPagina from TAI_FN_MONITOR_OV(@cliente,@producto,@estado,@desde,@hasta,@operador)     end   if @opcion = 20      begin    select *       from (select row_number() over (order by DocFecha desc) as RowNum         ,T0.*        from (select distinct            DocNum            as DocCodigo           ,left(CardName,40) as CliNombre           ,TaxDate           as EntFecha           ,DocDate           as DocFecha           ,DocDueDate        as VenFecha           ,Estado            as DocEstado           ,TipoDoc           as DocTipo           ,Tipo              as DocGrupo            --,OwnerCode         as VenCodigo          from TAI_FN_MONITOR_OV(@cliente,@producto,@estado,@desde,@hasta,@operador)) as T0)        as RowConstrainedResult where RowNum>=((@pagina*10)-9) and RowNum <= (@pagina*10)     order by RowNum   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_operador]   @opcion   integer  ,@operador integer  ,@oficina  integer  AS  BEGIN   if @opcion=10   begin    select OSLP.SlpCode           as OpeCodigo       ,upper(OSLP.SlpName)    as OpeNombre      from OSLP     where OSLP.SlpCode=@operador   end   if @opcion=20   begin     select isnull(OPE.SlpCode,0) as OpeCodigo          ,upper(OPE.SlpName)    as OpeNombre         from OHEM ADM         left join OUSR EMP on ADM.userId  = EMP.USERID         left join OUBR OFI on EMP.Branch  = OFI.Code         left join OSLP OPE on OPE.SlpCode = ADM.salesPrson          where ADM.Active='Y'       and ADM.branch=@oficina       and isnull(OPE.SlpCode,0)>0        order by 2     end   END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_orden_compra]   @opcion    integer  ,@documento integer  ,@proveedor varchar(15)  ,@diacompra integer  AS  BEGIN   if @Opcion=10    select distinct            dateadd(day,opor.extradays,opor.docdate) as FecVencimiento        ,opor.DocDueDate         ,opor.DocNum         ,opor.DocEntry        ,opor.CardName          ,opor.CardCode         ,opor.DocDate         ,opor.TaxDate         ,opor.GroupNum       ,upper(octg.PymntGroup)                   as PymntGroup       ,opor.ExtraDays         ,opor.SlpCode        ,upper(oslp.SlpName)                      as SlpName        ,opor.OwnerCode         ,opor.PayToCode         ,isnull(opor.ShipToCode,'')               as ShipToCode         ,isnull(opor.NumAtCard,'')                as NumAtCard       ,isnull(opor.Comments,'')                 as Comments       ,opor.Series         ,nnm1.SeriesName          ,(case when inv1.BaseEntry is null and (opor.CANCELED='N' or opor.DocStatus<>'C') then 'N' else 'Y' end)    as Facturado       ,isnull(oinv.FolioNum,0)                  as FolioNum       ,opor.U_TAI_Despacho       ,upper(ufd1.Descr)                        as TipoDespacho          ,isnull(opor.U_TAI_CondicionPagOC,0)      as U_TAI_CondicionPagOC       ,ocrd.LicTradNum                          as LicTradNum       ,isnull(ocrd.phone1, '')                  as phone1       ,lower(isnull(ocrd.E_Mail,''))            as E_Mail       ,upper(isnull(ocrd.Notes,''))             as Notes              ,opor.U_TAI_TipoVenta         ,isnull(opor.U_TAI_ComentarioOC,'')       as U_TAI_ComentarioOC       ,isnull(opor.U_TAI_MonedaProducto,'CLP')  as U_TAI_MonedaProducto              ,opor.DocTotal              ,lower(isnull(ohem.email,''))             as email       ,upper(isnull(aut.Mje_Op,''))             as Mje_Op       ,upper(isnull(aut.Mje_Aut,''))            as Mje_Aut       ,upper(ISNULL(aut.rechaza,''))            as rechaza               ,isnull(opor.U_TAI_NotaPedidoC, '')       as U_TAI_NotaPedidoC       ,opor.OwnerCode       ,opor.U_TAI_GlosaEspecial                  ,opor.ObjType       ,por1.TargetType       ,isnull(por1.TrgetEntry,0)                as TrgetEntry               ,isnull(cat.par_enlace,'') + ' - ' + isnull(cat.par_nombre,'') as U_TAI_Categoria       ,replace(isnull(mot.par_nombre,''),'SELECCIONE','')            as motivo       ,isnull(opor.U_TAI_Emision,'F')                                as emision        ,isnull(opor.U_Estado_Aut,'')                                  as U_Estado_Aut           from opor                  inner join por1 on por1.Docentry  = opor.Docentry                 left  join octg on octg.groupnum  = opor.groupnum                 left  join oslp on oslp.slpcode   = opor.slpcode                 left  join nnm1 on nnm1.Series    = opor.Series                 left  join ocrd on ocrd.cardcode  = opor.cardcode                 left  join tai_tb_autorizaciones aut on aut.DocEntry =opor.draftKey                 left  join ohem on ohem.salesPrson=opor.SlpCode                 left  join ufd1 on ufd1.TableID   = 'OPOR' and ufd1.FieldID=45 and ufd1.FldValue=opor.U_TAI_Despacho                 left  join inv1 on inv1.basetype  = opor.ObjType  and inv1.BaseEntry = opor.DocEntry                  left  join oinv on oinv.DocEntry  = inv1.DocEntry           left  join TAI_VW_PARAMETROS     cat on cat.par_grupo='categoria' and cat.par_enlace=ocrd.U_TAI_Categoria        left  join TAI_VW_PARAMETROS     mot on mot.par_grupo='motivo'    and mot.par_codigo=opor.U_TAI_Motivo     where opor.DocNum=@documento   if @Opcion=20    select DocEntry          ,ItemCode       ,upper(Dscription) as Dscription       ,Quantity       ,Currency       ,Rate       ,Price       ,LineTotal       ,DiscPrcnt       ,U_TAI_Interes       ,U_TAI_Flete       ,U_TAI_FechaEntrega       ,U_TAI_PUFinal       ,U_TAI_CostoComercial       ,isnull(U_TAI_MonedaCosto,'')             as U_TAI_MonedaCosto       ,U_TAI_PrcDsctoMax                ,isnull(U_TAI_CostoReposicio,0)           as U_TAI_CostoReposicion                  ,isnull(U_TAI_DiasCompra,0)               as U_TAI_DiasCompra         ,U_TAI_MonedaPF               ,U_TAI_PreCompraPF       ,(isnull(U_TAI_PrecioCompraO,0)*Quantity) as U_TAI_PrecioCompraO       ,isnull(U_TAI_CardCode,'')                as U_TAI_CardCode              ,WhsCode       ,U_TAI_TasaInteres         ,isnull(U_TAI_CondicionProducto,'')       as U_TAI_CondicionProducto       ,isnull(U_TAI_MotivoProducto,0)           as CodMotivoProducto       ,(case when isnull(U_TAI_MotivoProducto,0)=0 then ''              when U_TAI_MotivoProducto=1           then 'CONDICION ESPECIAL'        when U_TAI_MotivoProducto=2           then 'FALTA DE STOCK'        when U_TAI_MotivoProducto=3           then 'COND.ESPECIAL Y FALTA DE STOCK'        else                                       ''      end)                                    as NomMotivoProducto        from por1     where DocEntry                  =@documento       and isnull(U_TAI_CardCode,'x')=(case when @proveedor='' then isnull(U_TAI_CardCode,'x') else @proveedor end)       and isnull(U_TAI_DiasCompra,0)=(case when @diacompra=0  then isnull(U_TAI_DiasCompra,0) else @diacompra end)  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_orden_compra_genera]  @opcion integer  AS  BEGIN      declare @fecha char(8)   --select cast(replace(left(convert(time,getdate()),2),':','') as integer)   --if (cast(replace(left(convert(time,getdate()),2),':','') as integer)>6)   -- set @fecha=convert(char(8),getdate()-0,112)      --else    set @fecha=convert(char(8),getdate()-1,112)  ---   -1 original   --select @fecha   if @Opcion=10   begin    select distinct --top 10           ordr.U_TAI_TipoVenta  as TipoVenta       ,ordr.DocEntry         as DocEntryOV       ,ordr.DocDate          as FechaOV       ,ordr.DocNum           as DocNumOV       ,oinv.DocEntry         as DocEntryFV       ,oinv.DocDate          as FechaFV       ,oinv.DocNum           as DocNumFV       ,oinv.FolioNum         as FolioFV       ,inv1.BaseType         as BaseTypeFV       ,inv1.BaseEntry        as BaseEntryFV       ,OC.BaseType           as BaseTypeOC       ,OC.BaseEntry          as BaseEntryOC       ,ohem.userId           as Usuario       ,ordr.DocEntry         as DocEntry       ,ordr.DocNum           as DocNum       ,rdr1.U_TAI_CardCode   as Proveedor       ,rdr1.U_TAI_DiasCompra as DiaCompra      from ordr         inner join rdr1 on rdr1.DocEntry  =ordr.Docentry        inner join oinv on oinv.DocEntry  =rdr1.TrgetEntry        inner join inv1 on inv1.DocEntry  =oinv.DocEntry        inner join ohem on ohem.salesPrson=ordr.SlpCode        left join (select por1.BaseType, por1.BaseEntry from opor inner join por1 on por1.DocEntry=opor.DocEntry where opor.U_TAI_TipoVenta='ventaPuestoFundo' and convert(char(8),opor.DocDate,112)=@fecha) OC on OC.BaseType=inv1.BaseType and OC.BaseEntry=inv1.BaseEntry     where ordr.U_TAI_TipoVenta='ventaPuestoFundo'        and rdr1.U_TAI_CardCode   is not null       and rdr1.U_TAI_DiasCompra is not null       and (rdr1.itemcode not in('INTERESES','DESCUENTO') and left(rdr1.ItemCode,1)<>'Z')       and convert(char(8),oinv.DocDate,112)=@fecha       and OC.BaseType is null       and ordr.Canceled='N'       and oinv.Canceled='N'       and oinv.FolioNum is not null    union    select  distinct --top 20           ordr.U_TAI_TipoVenta  as TipoVenta       ,ordr.DocEntry         as DocEntryOV       ,ordr.DocDate          as FechaOV       ,ordr.DocNum           as DocNumOV       ,oinv.DocEntry         as DocEntryFV       ,oinv.DocDate          as FechaFV       ,oinv.DocNum           as DocNumFV       ,oinv.FolioNum         as FolioFV       ,inv1.BaseType         as BaseTypeFV       ,inv1.BaseEntry        as BaseEntryFV       ,OC.BaseType           as BaseTypeOC       ,OC.BaseEntry          as BaseEntryOC       ,ohem.userId           as Usuario       ,ordr.DocEntry         as DocEntry       ,ordr.DocNum           as DocNum       ,rdr1.U_TAI_CardCode   as Proveedor       ,rdr1.U_TAI_DiasCompra as DiaCompra      from ordr         inner join rdr1 on rdr1.DocEntry  =ordr.Docentry        inner join oinv on oinv.DocEntry  =rdr1.TrgetEntry        inner join inv1 on inv1.DocEntry  =oinv.DocEntry        inner join ohem on ohem.salesPrson=ordr.SlpCode        left join (select por1.BaseType, por1.BaseEntry from opor inner join por1 on por1.DocEntry=opor.DocEntry where opor.U_TAI_TipoVenta='ventaCalzadaProveedor' and convert(char(8),opor.DocDate,112)=@fecha) OC on OC.BaseType=inv1.BaseType and OC.BaseEntry=inv1.BaseEntry     where ordr.U_TAI_TipoVenta='ventaCalzadaProveedor'       and rdr1.U_TAI_CardCode   is not null       and rdr1.U_TAI_DiasCompra is not null       and (rdr1.itemcode not in('INTERESES','DESCUENTO') and left(rdr1.ItemCode,1)<>'Z')       and convert(char(8),oinv.DocDate,112)=@fecha       and OC.BaseType is null       and ordr.Canceled='N'       and oinv.Canceled='N'       and oinv.FolioNum is not null       order by 1, 2 desc   end   else if @Opcion=20   begin    select distinct           'PUESTO FUNDO'       as TipoVenta       ,ordr.DocEntry        as DocEntryOV       ,ordr.DocDate         as FechaOV       ,ordr.DocNum          as DocNumOV       ,oinv.DocEntry        as DocEntryFV       ,oinv.DocDate         as FechaFV       ,oinv.DocNum          as DocNumFV       ,oinv.FolioNum        as FolioFV       ,oinv.CardCode        as CardCodeFV       ,oinv.CardName        as CardNameFV       ,OC.CreateDate        as CreateDateOC       ,OC.CreateTS          as CreateTsOC       ,OC.DocEntry          as DocEntryOC       ,OC.DocNum            as DocNumOC       ,OC.CardCode          as CardCodeOC       ,OC.CardName          as CardNameOC      from ordr         inner join rdr1 on rdr1.DocEntry  =ordr.Docentry        inner join oinv on oinv.DocEntry  =rdr1.TrgetEntry        inner join inv1 on inv1.DocEntry  =oinv.DocEntry        inner join ohem on ohem.salesPrson=ordr.SlpCode        left join (select opor.CreateDate, opor.CreateTS, opor.DocEntry, opor.DocNum, opor.CardCode, opor.CardName, por1.BaseType, por1.BaseEntry from opor inner join por1 on por1.DocEntry=opor.DocEntry where opor.U_TAI_TipoVenta='ventaPuestoFundo' and convert(char(8),opor.DocDate,112)=@fecha) OC on OC.BaseType=inv1.BaseType and OC.BaseEntry=inv1.BaseEntry     where ordr.U_TAI_TipoVenta='ventaPuestoFundo'        and rdr1.U_TAI_CardCode   is not null       and rdr1.U_TAI_DiasCompra is not null       and (rdr1.itemcode not in('INTERESES','DESCUENTO') and left(rdr1.ItemCode,1)<>'Z')       and convert(char(8),oinv.DocDate,112)=@fecha       and OC.BaseType is not null       and ordr.Canceled='N'       and oinv.Canceled='N'       and oinv.FolioNum is not null    union    select distinct           'CALZADA PROVEEDOR'  as TipoVenta       ,ordr.DocEntry        as DocEntryOV       ,ordr.DocDate         as FechaOV       ,ordr.DocNum          as DocNumOV       ,oinv.DocEntry        as DocEntryFV       ,oinv.DocDate         as FechaFV       ,oinv.DocNum          as DocNumFV       ,oinv.FolioNum        as FolioFV       ,oinv.CardCode        as CardCodeFV       ,oinv.CardName        as CardNameFV       ,OC.CreateDate        as CreateDateOC       ,OC.CreateTS          as CreateTsOC       ,OC.DocEntry          as DocEntryOC       ,OC.DocNum            as DocNumOC       ,OC.CardCode          as CardCodeOC       ,OC.CardName          as CardNameOC      from ordr         inner join rdr1 on rdr1.DocEntry  =ordr.Docentry        inner join oinv on oinv.DocEntry  =rdr1.TrgetEntry        inner join inv1 on inv1.DocEntry  =oinv.DocEntry        inner join ohem on ohem.salesPrson=ordr.SlpCode        left join (select opor.CreateDate, opor.CreateTS, opor.DocEntry, opor.DocNum, opor.CardCode, opor.CardName, por1.BaseType, por1.BaseEntry from opor inner join por1 on por1.DocEntry=opor.DocEntry where opor.U_TAI_TipoVenta='ventaCalzadaProveedor' and convert(char(8),opor.DocDate,112)=@fecha) OC on OC.BaseType=inv1.BaseType and OC.BaseEntry=inv1.BaseEntry     where ordr.U_TAI_TipoVenta='ventaCalzadaProveedor'       and rdr1.U_TAI_CardCode   is not null       and rdr1.U_TAI_DiasCompra is not null       and (rdr1.itemcode not in('INTERESES','DESCUENTO') and left(rdr1.ItemCode,1)<>'Z')       and convert(char(8),oinv.DocDate,112)=@fecha       and OC.BaseType is not null       and ordr.Canceled='N'       and oinv.Canceled='N'       and oinv.FolioNum is not null       order by 1, 4 desc   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_orden_venta]   @opcion    integer  ,@documento integer  ,@proveedor varchar(15)  ,@diacompra integer  AS  BEGIN   if @Opcion=10    select distinct            dateadd(day,ordr.extradays,ordr.docdate) as FecVencimiento        ,ordr.DocDueDate         ,ordr.DocNum         ,ordr.DocEntry        ,ordr.CardName          ,ordr.CardCode         ,ordr.DocDate         ,ordr.TaxDate         ,ordr.GroupNum       ,upper(octg.PymntGroup)                   as PymntGroup       ,ordr.ExtraDays         ,ordr.SlpCode        ,upper(oslp.SlpName)                      as SlpName        ,ordr.OwnerCode         ,ordr.PayToCode         ,isnull(ordr.ShipToCode,'')               as ShipToCode         ,isnull(ordr.NumAtCard,'')                as NumAtCard       ,isnull(ordr.Comments,'')                 as Comments       ,ordr.Series         ,nnm1.SeriesName          ,(case when inv1.BaseEntry is null and (ordr.CANCELED='N' or ordr.DocStatus<>'C') then 'N' else 'Y' end)    as Facturado       ,isnull(oinv.FolioNum,0)                  as FolioNum       ,ordr.U_TAI_Despacho       ,upper(ufd1.Descr)                        as TipoDespacho          ,isnull(ordr.U_TAI_CondicionPagOC,0)      as U_TAI_CondicionPagOC       ,ocrd.LicTradNum                          as LicTradNum       ,isnull(ocrd.phone1, '')                  as phone1       ,lower(isnull(ocrd.E_Mail,''))            as E_Mail       ,upper(isnull(ocrd.Notes,''))             as Notes              ,ordr.U_TAI_TipoVenta         ,isnull(ordr.U_TAI_ComentarioOC,'')       as U_TAI_ComentarioOC       ,isnull(ordr.U_TAI_MonedaProducto,'CLP')  as U_TAI_MonedaProducto              ,ordr.DocTotal              ,lower(isnull(ohem.email,''))             as email       ,upper(isnull(aut.Mje_Op,''))             as Mje_Op       ,upper(isnull(aut.Mje_Aut,''))            as Mje_Aut       ,upper(ISNULL(aut.rechaza,''))            as rechaza               ,isnull(ordr.U_TAI_NotaPedidoC, '')       as U_TAI_NotaPedidoC       ,ordr.OwnerCode       ,ordr.U_TAI_GlosaEspecial                  ,ordr.ObjType       ,rdr1.TargetType       ,isnull(rdr1.TrgetEntry,0)                as TrgetEntry                  ,isnull(cat.par_enlace,'') + ' - ' + isnull(cat.par_nombre,'') as U_TAI_Categoria       ,replace(isnull(mot.par_nombre,''),'SELECCIONE','')            as motivo       ,isnull(ordr.U_TAI_Emision,'F')                                as emision        ,isnull(ordr.U_Estado_Aut,'')                                  as U_Estado_Aut      from ordr                 inner join rdr1 on rdr1.Docentry  = ordr.Docentry                 left  join octg on octg.groupnum  = ordr.groupnum                 left  join oslp on oslp.slpcode   = ordr.slpcode                 left  join nnm1 on nnm1.Series    = ordr.Series                 left  join ocrd on ocrd.cardcode  = ordr.cardcode                 left  join tai_tb_autorizaciones aut on aut.DocEntry=ordr.draftKey                 left  join ohem on ohem.salesPrson=ordr.SlpCode                 left  join ufd1 on ufd1.TableID   = 'ORDR' and ufd1.FieldID=45    and ufd1.FldValue=ordr.U_TAI_Despacho                 left  join inv1 on inv1.basetype  = ordr.ObjType  and inv1.BaseEntry = ordr.DocEntry                  left  join oinv on oinv.DocEntry  = inv1.DocEntry           left  join TAI_VW_PARAMETROS     cat on cat.par_grupo='categoria' and cat.par_enlace=ocrd.U_TAI_Categoria        left  join TAI_VW_PARAMETROS     mot on mot.par_grupo='motivo'    and mot.par_codigo=ordr.U_TAI_Motivo     where ordr.DocNum=@documento   if @Opcion=20    select DocEntry          ,ItemCode       ,upper(Dscription) as Dscription       ,Quantity       ,Currency       ,Rate       ,Price       ,LineTotal       ,DiscPrcnt       ,U_TAI_Interes       ,U_TAI_Flete       ,U_TAI_FechaEntrega       ,U_TAI_PUFinal       ,U_TAI_CostoComercial       ,isnull(U_TAI_MonedaCosto,'')             as U_TAI_MonedaCosto       ,U_TAI_PrcDsctoMax         ,isnull(U_TAI_CostoReposicio,0)           as U_TAI_CostoReposicion                  ,isnull(U_TAI_DiasCompra,0)               as U_TAI_DiasCompra         ,U_TAI_MonedaPF               ,U_TAI_PreCompraPF       ,(isnull(U_TAI_PrecioCompraO,0)*Quantity) as U_TAI_PrecioCompraO       ,isnull(U_TAI_CardCode,'')                as U_TAI_CardCode              ,WhsCode       ,U_TAI_TasaInteres         ,isnull(U_TAI_CondicionProducto,'')       as U_TAI_CondicionProducto       ,isnull(U_TAI_MotivoProducto,0)           as CodMotivoProducto       ,(case when isnull(U_TAI_MotivoProducto,0)=0 then ''              when U_TAI_MotivoProducto=1           then 'CONDICION ESPECIAL'        when U_TAI_MotivoProducto=2           then 'FALTA DE STOCK'        when U_TAI_MotivoProducto=3           then 'COND.ESPECIAL Y FALTA DE STOCK'        else                                       ''      end)                                    as NomMotivoProducto        from rdr1     where DocEntry                  =@documento             and isnull(U_TAI_CardCode,'x')=(case when @proveedor='' then isnull(U_TAI_CardCode,'x') else @proveedor end)       and isnull(U_TAI_DiasCompra,0)=(case when @diacompra=0  then isnull(U_TAI_DiasCompra,0) else @diacompra end)  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_orden_venta_cancela]  @proceso varchar(1)  AS  BEGIN   declare @DocDate datetime   if @proceso='A'    set @DocDate=getdate()-3   else if @proceso='C'       set @DocDate=getdate()-4   select OHEM.userId                                as UsuCodigo      ,ORDR.SlpCode                               as OpeCodigo      ,upper(OSLP.SlpName)                        as OpeNombre      ,isnull(lower(OHEM.email),'')               as OpeCorreo      ,ORDR.DocEntry                              as DocEntry      ,ORDR.DocNum                                as DocNumero      ,ORDR.DocDate                               as DocFecha      ,ORDR.CardCode                              as CliCodigo      ,upper(ORDR.CardName)                       as CliNombre      ,cast(ORDR.DocTotal as numeric(9,0))        as DocTotal    --,upper(ORDR.U_TAI_TipoVenta)                as VenTipo      ,case ORDR.U_TAI_TipoVenta      when 'ventaBodega'           then 'BODEGA PROPIA'      when 'ventaConsignada'       then 'CONSIGNADA'      when 'ventaPuestoFundo'      then 'PUESTO FUNDO'      when 'ventaCalzadaProveedor' then 'CALZADA PROVEEDOR'         when 'ventaCostoEspecial'    then 'COSTO ESPECIAL'      when 'ventaLiquidacion'      then 'LIQUIDACION'      else                              'SIN CLASIFICAR'       end                                        as VenTipo     from ORDR       inner join OSLP on OSLP.SlpCode   =ORDR.SlpCode        inner join OHEM on OHEM.salesPrson=OSLP.SlpCode    where DocStatus      ='O'       and U_VK_CertOrigen='WEB'       and convert(char(8),docdate,112)=convert(char(8),@DocDate,112)  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_parametro]   @opcion    integer  ,@parametro varchar(25)       AS  BEGIN   if @opcion=10   begin      select PRMT.par_codigo        as ParCodigo          ,PRMT.par_enlace        as ParEnlace          ,upper(PRMT.par_nombre) as ParNombre      from TAI_VW_Parametros PRMT     where PRMT.par_estado=1       and PRMT.par_grupo=@parametro     order by PRMT.par_orden   end  END 
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_periodo_contable]  @opcion integer      AS  BEGIN   if @opcion=10   begin      select PERI.Code as PerNombre      from [@TAI_CIERRE_MESD] PERI     where PERI.U_TAI_Activo='N'       and PERI.U_TAI_Objeto=17   end  END 
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_plazo_compra]  @opcion integer  AS  BEGIN   if @opcion=10   begin    select upper(UFD1.FldValue)      as PlaCodigo          ,upper(UFD1.Descr)         as PlaNombre       ,substring(UFD1.Descr,1,3) as PlaDias      from UFD1      where UFD1.TableID='OPOR'       and UFD1.FieldID=59      end   if @opcion=20   begin    select UFD1.FldValue             as PlaCodigo          ,upper(UFD1.Descr)         as PlaNombre       ,substring(UFD1.Descr,1,3) as PlaDias      from UFD1      where UFD1.TableID='OPOR'       and UFD1.FieldID=59       and UFD1.FldValue in(4,5,6,17,29)        order by cast(substring(UFD1.Descr,1,3) as integer)    end   END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_plazo_venta]  @opcion integer  AS  BEGIN   if @opcion=10   begin    select OCTG.GroupNum          as PlaCodigo          ,upper(OCTG.PymntGroup) as PlaNombre          ,OCTG.ExtraDays         as PlaDias      from OCTG   end   if @opcion=20   begin    select OCTG.GroupNum          as PlaCodigo          ,upper(OCTG.PymntGroup) as PlaNombre          ,OCTG.ExtraDays         as PlaDias      from OCTG     where GroupNum in(-1,1,16,30)   end   END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_producto]   @opcion      integer  ,@producto    varchar(30)   ,@bodega      varchar(20)=''  ,@ingrediente varchar(5) ='0'  AS  BEGIN   if @opcion=10   begin    select top 10           OITM.ItemCode                                     as ArtCodigo                                      ,isnull(upper(OITM.ItemName),'')                   as ArtNombre          ,isnull(OITM.U_TAI_Envase + ' ' + cast(cast(OITM.U_TAI_Capacidad as float) as nvarchar(10)) + ' ' +            case OITM.U_TAI_UndMed                 when 'X' then '---'              when 'L' then 'LTS'                      when 'K' then 'KGS'           end, '')                                     as ArtEnvase          ,OITB.ItmsGrpCod                                   as GruCodigo                  ,upper(OITB.ItmsGrpNam)                            as GruNombre          ,isnull(OCRD.CardCode, '')                         as ProCodigo          ,upper(isnull(OCRD.CardName , ''))                 as ProNombre          ,isnull(OITW.U_TAI_PrecioVenta, 0)                 as ArtPrecioUnitario          ,isnull(OITW.U_TAI_CostoComercial,0)               as ArtCostoComercial          ,isnull(OITW.U_TAI_Moneda, 'CLP')                  as ArtMoneda                                         ,sum(isnull(OITW.U_TAI_StockReal, 0))              as ArtStockFisico           ,sum(OITW.OnHand + OITW.OnOrder - OITW.IsCommited) as ArtStockDisponible          ,OITM.InvntItem                                    as ArtInventariable          ,cast(isnull([@TAI_PPLIN].U_TAI_PorcFlete,0) as numeric(9,2))as PorFlete          ,isnull(OITW.U_TAI_CostoRep,0)                     as ArtCostoReposicion       ,isnull(OITM.U_TAI_DiasPago,0)                     as ArtDiasPago       ,cast(isnull(ITM1.Price,0) as numeric(18,2))       as ArtPrecioCompra       ,isnull(ITM1.Currency,'')                          as ArtMonedaCompra      from OITM            left  join ITM1             on ITM1.ItemCode        =oitm.ItemCode and ITM1.PriceList=2           inner join OITB             on OITM.ItmsGrpCod      =OITB.ItmsGrpCod           inner join OITW             on OITW.ItemCode        =OITM.ItemCode and OITW.WhsCode = @bodega                    left  join OCRD             on OCRD.CardCode        =OITM.CardCode           inner join [@TAI_PPLIN]     on [@TAI_PPLIN].Code    =OITB.ItmsGrpCod    where OITM.frozenFor       ='N'       and (OITM.ItemCode like '%' + @producto + '%' or OITM.SWW like '%' + @producto + '%' or OITM.ItemName like '%' + @producto + '%')    group By OITM.ItemCode, OITM.SWW, OITM.ItemName, OITB.ItmsGrpNam, OITB.ItmsGrpCod, OCRD.CardCode, OCRD.CardName, OITW.U_TAI_Moneda, OITW.U_TAI_PrecioVenta, OITW.U_TAI_CostoComercial, OITM.U_TAI_Envase, OITM.U_TAI_Capacidad, OITM.U_TAI_UndMed, OITM.InvntItem, [@TAI_PPLIN].U_TAI_PorcFlete,OITW.U_TAI_CostoRep, OITM.U_TAI_DiasPago, ITM1.Price, ITM1.Currency   end   if @opcion=20   begin    select distinct top 10            OITM.ItemCode                                     as ArtCodigo                                      ,isnull(upper(OITM.ItemName),'')                   as ArtNombre          ,isnull(OITM.U_TAI_Envase + ' ' + cast(cast(OITM.U_TAI_Capacidad as float) as nvarchar(10)) + ' ' +            case OITM.U_TAI_UndMed                 when 'X' then '---'              when 'L' then 'LTS'                      when 'K' then 'KGS'           end, '')                                     as ArtEnvase          ,OITB.ItmsGrpCod                                   as GruCodigo                  ,upper(OITB.ItmsGrpNam)                            as GruNombre          ,isnull(OCRD.CardCode, '')                         as ProCodigo          ,upper(isnull(OCRD.CardName , ''))                 as ProNombre                 ,0                                                 as ArtPrecioUnitario          ,0                                                 as ArtCostoComercial          ,''                                                as ArtMoneda                                         ,0                                                 as ArtStockFisico           ,0                                                 as ArtStockDisponible                                ,OITM.InvntItem                                    as ArtInventariable          ,0                                                 as PorFlete          ,0                                                 as ArtCostoReposicion       ,isnull(OITM.U_TAI_DiasPago,0)                     as ArtDiasPago       ,cast(isnull(ITM1.Price,0) as numeric(18,2))       as ArtPrecioCompra       ,isnull(ITM1.Currency,'')                          as ArtMonedaCompra      from OITM              left  join ITM1             on ITM1.ItemCode        =oitm.ItemCode and ITM1.PriceList=2           inner join OITB on OITM.ItmsGrpCod=OITB.ItmsGrpCod           left  join OCRD on OCRD.CardCode  =OITM.CardCode    where OITM.frozenFor = 'N'       and (OITM.ItemCode like '%' + @producto + '%' or OITM.SWW like '%' + @producto + '%' or OITM.ItemName like '%' + @producto + '%')    group By OITM.ItemCode, OITM.SWW, OITM.ItemName, OITB.ItmsGrpNam, OITB.ItmsGrpCod, OCRD.CardCode, OCRD.CardName, OITM.U_TAI_Envase, OITM.U_TAI_Capacidad, OITM.U_TAI_UndMed, OITM.InvntItem, OITM.U_TAI_DiasPago, ITM1.Price, ITM1.Currency   end    --if @opcion=30   --begin   -- select top 10   --        OITM.ItemCode                                     as ArtCodigo                               --       ,upper(OITM.ItemName)                              as ArtNombre   --       ,isnull(OITM.U_TAI_Envase + ' ' + cast(cast(OITM.U_TAI_Capacidad as float) as nvarchar(10)) + ' ' +    --        case OITM.U_TAI_UndMed    --             when 'X' then '---'    --          when 'L' then 'LTS'   --                   when 'K' then 'KGS'   --        end, '')            as ArtEnvase   --       ,upper(OITB.ItmsGrpNam)                            as GruNombre     --       ,upper(isnull(OCRD.CardName, ''))                  as ProNombre                                          --   from OITM    --        inner join OITB on OITM.ItmsGrpCod=OITB.ItmsGrpCod    --        left  join OCRD on OITM.CardCode  =OCRD.CardCode            -- where OITM.frozenFor = 'N'    --   and (OITM.ItemCode like '%' + @producto + '%' or OITM.SWW like '%' + @producto + '%' or OITM.ItemName like '%' + @producto + '%')   -- group By OITM.ItemCode, OITM.SWW, OITM.ItemName, OITM.U_TAI_Envase, OITM.U_TAI_Capacidad, OITM.U_TAI_UndMed, OITB.ItmsGrpNam, OCRD.CardName      --end    if @opcion=30   begin    select ItemCode                   as ArtCodigo          ,(ItemCode+' | ' +ItemName) as ArtNombre      from OITM           where frozenFor='N'       and U_TAI_IngrActivo=@ingrediente--(case when @ingrediente='0' then U_TAI_IngrActivo else @ingrediente end)          order by ItemName   end  END
  CREATE PROCEDURE [dbo].[tai_vw_sp2_select_proveedor]   @opcion  integer  ,@proveedor varchar(25)  AS  BEGIN   if @opcion=10   begin    select top 10           CardCode        as ProCodigo          ,upper(CardName) as ProNombre      from OCRD      where substring(CardCode,1,1)='P'       and CardType='S'        and (CardCode like '' + @proveedor + '%'  or CardName like '' + @proveedor + '%')       and frozenFor='N'   end   if @opcion=20   begin    select CardCode        as ProCodigo          ,upper(CardName) as ProNombre      from OCRD      where substring(CardCode,1,1)='P'       and CardType               ='S'        and CardCode               =@proveedor       and frozenFor              ='N'        end  END
create PROCEDURE [dbo].[tai_vw_sp2_select_proveedor_orden_compra]   @DocEntry integer  ,@Docnum   integer  AS  BEGIN   select ocrd.CardCode         as ProCodigo         ,ocrd.CardName         as ProNombre      ,rdr1.U_TAI_DiasCompra as DiaCompra     from ordr          inner join rdr1 on rdr1.DocEntry=ordr.DocEntry       inner join ocrd on ocrd.CardCode=rdr1.U_TAI_CardCode    where ordr.DocEntry=@DocEntry      and ordr.DocNum  =@Docnum     group by ocrd.CardCode, ocrd.CardName, rdr1.U_TAI_DiasCompra   END
CREATE PROCEDURE tai_vw_sp2_select_region  @opcion   integer  AS  BEGIN   if @opcion=10   begin    select distinct        U_VK_RegionNum     RegCodigo       ,upper(U_VK_Region) RegNombre      from [@VK_OCCL]     order by 2   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_serie]   @opcion    integer  ,@objeto    nvarchar(10)  ,@subobjeto nvarchar(10)  ,@usuario   integer  AS  BEGIN   if @opcion=10   begin    declare @serie as integer      select @serie = count(*) from NNM2 where ObjectCode=@objeto and NNM2.DocSubType=@subobjeto and NNM2.UserSign=@usuario      if @serie = 0 and @objeto = 17 and @subobjeto = '--'    begin       select 644              as SerCodigo        ,'OV-OFC'         as SerNombre    end      else if @serie = 0 and @objeto = 13 and @subobjeto = '--'    begin       select 564              as SerCodigo           ,'FVN-OFC'        as SerNombre    end    else if @serie = 0 and @objeto = 13 and @subobjeto = 'IB'    begin       select 4                as SerCodigo           ,'BVN_OFC'        as SerNombre    end       else      begin        select NNM1.series     as SerCodigo         ,NNM1.SeriesName as SerNombre        from NNM1         inner join NNM2 on NNM2.ObjectCode = NNM1.ObjectCode and NNM2.Series = NNM1.Series         inner join OUSR on OUSR.USERID = NNM2.UserSign         where NNM1.ObjectCode=@objeto       and NNM2.DocSubType=@subobjeto      and NNM2.UserSign  =@usuario      end   end  END
create PROCEDURE [dbo].[tai_vw_sp2_select_subgrupo]   @opcion   int  ,@grupo    int  ,@subgrupo int  ,@usuario  varchar(10)=''  AS  BEGIN   if @opcion=10   begin    select sub_codigo as SubCodigo       ,sub_nombre as SubNombre      from matriz_descto_subgrupo     order by 2    end   if @opcion=20   begin    select s.sub_codigo as SubCodigo       ,s.sub_nombre as SubNombre      from matriz_descto_grupo               g           inner join matriz_descto_subgrupo s on s.gru_codigo=g.gru_codigo     where g.gru_codigo=(case when @grupo   =0 then g.gru_codigo else @grupo    end)       and s.sub_codigo=(case when @subgrupo=0 then s.sub_codigo else @subgrupo end)     order by 2    end   if @opcion=30   begin    if not exists (select distinct d.det_codusuario from matriz_descto_detalle d where d.det_codcargo='GL' and det_codusuario=@usuario)     set @usuario=''    select distinct        s.sub_codigo as SubCodigo       ,s.sub_nombre as SubNombre      from matriz_descto_grupo               g        inner join matriz_descto_subgrupo s on s.gru_codigo  =g.gru_codigo        inner join matriz_descto_linea    l on l.sub_codigo  =s.sub_codigo         inner join matriz_descto_detalle  d on d.det_codlinea=l.lin_codigo     where d.det_codcargo  ='GL'       and d.det_codusuario=(case when @usuario ='' then d.det_codusuario else @usuario  end)             and g.gru_codigo    =(case when @grupo   =0  then g.gru_codigo     else @grupo    end)       and s.sub_codigo    =(case when @subgrupo=0  then s.sub_codigo     else @subgrupo end)     order by 2   end  END
create PROCEDURE [dbo].[tai_vw_sp2_select_sucursal]  @opcion int  AS  BEGIN   if @opcion=10   begin    select distinct            det_codsucursal as SucCodigo          ,upper(S.[Name]) as SucNombre      from matriz_descto_detalle D           inner join OUBR       S on S.Code=D.det_codsucursal           order by 2   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_tasa_interes_producto]   @opcion   integer  ,@tipoTasa varchar(20)  AS  BEGIN   if @opcion=10   begin       select U_ValorNumerico as TasInteres          from [@VK_OPAR]        where Code=@tipoTasa   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_tipo_cambio]   @opcion integer  ,@moneda varchar(3)   ,@fecha  varchar(10)        AS  BEGIN   if @opcion=10   begin    select ORTT.RateDate                   as CamFecha          ,ORTT.Currency                   as CamMoneda       ,cast(ORTT.Rate as numeric(9,2)) as CamValor      from ORTT     where ORTT.Currency=(case when @moneda='' then ORTT.Currency else @moneda end)       and convert(char(8),ORTT.RateDate,112)=convert(char(8),convert(datetime,@fecha,103),112)    end  END 
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_tipo_despacho]  @opcion int      AS  BEGIN   if @opcion=10   begin      select DESP.Id                 as DesCodigo          ,upper(DESP.Descripcion) as DesNombre      from TAI_VW_ValorDespacho DESP   end  END 
create PROCEDURE [dbo].[tai_vw_sp2_select_usuario]  @opcion int  AS  BEGIN   if @opcion=10   begin    select distinct            D.det_codusuario as UsuCodigo          ,upper(U.U_NAME)  as UsuNombre      from matriz_descto_detalle D           inner join OUSR       U on U.USER_CODE=D.det_codusuario           order by 2   end   else if @opcion=20   begin    select distinct            D.det_codbackup as UsuCodigo       ,upper(B.U_NAME) as UsuNombre      from matriz_descto_detalle D                 inner join OUSR       B on B.USER_CODE=D.det_codbackup           order by 2   end   else if @opcion=30   begin    select distinct            U.USER_CODE      as UsuCodigo          ,upper(U.U_NAME)  as UsuNombre      from OHEM            E           inner join OUSR U on U.USERID=E.userId        inner join HEM6 C on C.empID =E.empID        inner join OHTY F on F.typeID=C.roleID           where E.Active='Y'       and U.Locked='N'       and (E.position in(2,11,13,23,24,27,28,29)        or F.typeID in (5,7,8,9,10,11,12,15,16,20,22,24))           order by 2   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_usuario_sap]   @opcion  integer  ,@usuario integer  AS  BEGIN   if @opcion=10   begin    select CSAP.U_TAI_User as SapUser          ,CSAP.U_TAI_Pass as SapPassword      from OUSR           left join OUBR                      on OUSR.Branch        = OUBR.Code           left join [@TAI_CUENTASAPXSUC] CSAP on CSAP.U_TAI_Sucursal=OUBR.Name     where OUSR.Locked='N'       and OUSR.GROUPS<>99       and OUSR.USERID=@usuario   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_usuario_sistema]   @opcion   integer  ,@usuario  varchar(50)  ,@password varchar(32)  AS  BEGIN   if @opcion=10   begin    select T0.Active EmpActivo      from OHEM T0        left join OUSR T1 on T1.USERID=T0.userId     where T1.USER_CODE     =@usuario       and T1.U_TAI_Password=substring(sys.fn_sqlvarbasetostr(hashbytes('MD5',@password)),3,32)   end    if @opcion=20   begin  /*        select T0.empID                 'EmpCodigo'       ,T1.USERID                'UsuCodigo'       ,isnull(T0.salesPrson,0)  'OpeCodigo'        ,isnull(T0.branch,0)      'OfiCodigo'         ,upper(T1.USER_CODE)      'UsuAlias'       ,upper(T1.U_NAME)         'UsuNombre'       ,upper(T3.Name)           'OfiNombre'       from OHEM T0         left join OUSR T1 on T1.USERID =T0.userId        left join OSLP T2 on T2.SlpCode=T0.salesPrson        left join OUBR T3 on T3.Code   =T1.Branch      where T0.Active        ='Y'        and T1.USER_CODE     =@usuario       and T1.U_TAI_Password=substring(sys.fn_sqlvarbasetostr(hashbytes('MD5',@password)),3,32)    */    select EMP.empID                  EmpCodigo         ,USU.userId                 UsuCodigo         ,isnull(EMP.salesPrson,0)   OpeCodigo       ,isnull(SUC.Code,0)         OfiCodigo         ,upper(USU.USER_CODE)       UsuAlias       ,upper(USU.U_NAME)          UsuNombre            ,isnull(upper(SUC.Name),'') OfiNombre       --,USU.Locked                 UsuBloqueado     --,USU.U_TAI_Password         UsuPassword       ,ROL.roleID                 RolCodigo       ,upper(CAR.name)            RolNombre       ,case           when ROL.roleID in(5,6,15,16,19) then 1           when ROL.roleID in(7,8,22)       then 2           when ROL.roleID in(9,10,11)      then 3           when ROL.roleID in(12,26)        then 4           when ROL.roleID in(2,4,17)       then 5           when ROL.roleID in(18)           then 6        end                        NivCodigo       ,1                          UsuActivo      from ousr            USU        inner join ohem EMP on EMP.userId=USU.USERID        inner join hem6 ROL on ROL.empID =EMP.empID        inner join ohty CAR on CAR.typeID=ROL.roleID        left join  oubr SUC on SUC.code  =EMP.branch        where ROL.roleID in(2,4,5,6,7,8,9,10,11,12,15,16,17,18,19,22,26)       and USU.Locked                   ='N'        and lower(USU.USER_CODE)         =@usuario       and isnull(USU.U_TAI_Password,'')=substring(sys.fn_sqlvarbasetostr(hashbytes('MD5',@password)),3,32)     end   if @opcion=30   begin           --Listado de operadores comerciales---------      select 1                                                                       as PerCodigo          ,'OpCom'                                                                 as PerNombre        ,'N'                                                                     as PerCotizador        --,(case when T0.empid in(1,10,112,506,624,649,650) then 'S' else 'N' end) as PerCotizador      from OHEM T0           left join OUSR T1 on T1.USERID=T0.userId     where T0.dept in (3, 5)          and T0.jobTitle not in ('Grandes Cuentas','Jefe Oficina', 'Jefe Vtas.Especiali.', 'Jefe Linea AgroMaqu.', 'Jefe Depto.Plasticos', 'Gerente Zona Norte', 'Gerente Zona Sur', 'Gerente Distribución', 'Gerente Maquinaria', 'Gerente Adm. y Finan', 'Gerente General', 'Gerente Comercial', 'Gerente Especialidad','Jefa Abastecimiento')         and T0.Active        ='Y'         and T1.USER_CODE     =@usuario        and T1.U_TAI_Password=substring(sys.fn_sqlvarbasetostr(hashbytes('MD5',@password)),3,32)     union all    ---Listado de Mixto(operadores comerciales y autorizadores)-------      select 2                                                                       as PerCodigo          ,'Mixto'                                                                 as PerNombre       ,'N'                                                                     as PerCotizador        --,(case when T0.empid in(1,10,112,506,624,649,650) then 'S' else 'N' end) as PerCotizador      from OHEM T0           left join OUSR T1 on T1.USERID=T0.userId     where T0.dept in (3, 5)          and T0.jobTitle in ('Jefe Oficina', 'Gerente Zona Norte', 'Gerente Zona Centro', 'Gerente Zona Sur', 'Jefe Vtas.Especiali.', 'Grandes Cuentas', 'Gerente Distribución', 'Gerente Maquinaria','Gerente Especialidad','Jefa Abastecimiento','Gerente Ventas')         and T0.empID not in (380, 425, 444, 447, 452)       and T0.Active        ='Y'         and T1.USER_CODE     =@usuario        and T1.U_TAI_Password=substring(sys.fn_sqlvarbasetostr(hashbytes('MD5',@password)),3,32)     union all      ---Listado de Autorizador Creditos----------      select 3                                                                       as PerCodigo          ,'Autorizador'                                                           as PerNombre       ,'N'                                                                     as PerCotizador        --,(case when T0.empid in(1,10,112,506,624,649,650) then 'S' else 'N' end) as PerCotizador      from OHEM T0           left join OUSR T1 on T1.USERID=T0.userId     where T0.empID in (172, 189, 136, 109, 101, 278, 192, 376, 380, 401, 161, 465, 425, 444, 447, 452, 492, 538, 281)        and T0.Active        ='Y'         and T1.USER_CODE     =@usuario         and T1.U_TAI_Password=substring(sys.fn_sqlvarbasetostr(hashbytes('MD5',@password)),3,32)    end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_venta_mensual]    @opcion  integer  ,@usuario integer  ,@cliente varchar(25)   ,@año   integer  ,@mes   integer  AS  BEGIN   if @opcion=10   begin     select OINV.DocEntry       ,OINV.DocNum       ,OINV.FolioPref       ,OINV.FolioNum        ,OINV.DocDate        ,OINV.DocDueDate        ,OINV.U_TAI_cuartacopia                   as Doc4taCopia       ,OINV.CardCode       ,OINV.CardName        ,convert(int,(OINV.DocTotal-OINV.VatSum)) as DocNeto        from OINV         left join OHEM on OINV.SlpCode=OHEM.salesPrson     where OINV.ObjType       ='13'        and OINV.FolioPref     in('33','39')       and OHEM.userId        =@usuario        and OINV.CardCode      =(case when @cliente='' then OINV.CardCode else @cliente end)       and year(OINV.DocDate) =@año                 and month(OINV.DocDate)=@mes     union    select ORIN.DocEntry       ,ORIN.DocNum        ,ORIN.FolioPref       ,ORIN.FolioNum        ,ORIN.DocDate        ,ORIN.DocDueDate       ,ORIN.U_TAI_cuartacopia                   as Doc4taCopia       ,ORIN.CardCode       ,ORIN.CardName       ,convert(int,(ORIN.DocTotal-ORIN.VatSum)) as DocNeto       from ORIN         left join OHEM on ORIN.SlpCode=OHEM.salesPrson     where ORIN.ObjType       ='14'        and ORIN.FolioPref     ='61'        and OHEM.userId        =@usuario        and ORIN.CardCode      =(case when @cliente='' then ORIN.CardCode else @cliente end)       and year(ORIN.DocDate) =@año                and month(ORIN.DocDate)=@mes    end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_select_venta_vendedor]    @opcion  integer  ,@usuario integer  ,@cliente varchar(25)   ,@año   integer  ,@mes   integer  AS  BEGIN   SET NOCOUNT ON;   if @opcion=10    begin        if @cliente=''      begin        SELECT OINV.DocEntry,          OINV.DocNum,         OINV.FolioPref,         OINV.FolioNum,          OINV.DocDate,          OINV.DocDueDate,          OINV.U_TAI_CUARTACOPIA  as Doc4taCopia,         OINV.CardCode,          OINV.CardName,          CONVERT(INT, (OINV.DocTotal - OINV.VatSum)) AS 'DocNeto'         FROM  OINV LEFT JOIN OHEM ON OINV.SlpCode = OHEM.salesPrson       WHERE OINV.ObjType='13' AND OINV.FolioPref='33' AND OHEM.userId=@usuario AND MONTH(OINV.DocDate)=@mes AND   YEAR(OINV.DocDate)=@año          UNION          SELECT ORIN.DocEntry,          ORIN.DocNum,          ORIN.FolioPref,         ORIN.FolioNum,          ORIN.DocDate,          ORIN.DocDueDate,         ORIN.U_TAI_CUARTACOPIA  as Doc4taCopia,         ORIN.CardCode,          ORIN.CardName,          CONVERT(INT, (ORIN.DocTotal - ORIN.VatSum)) AS 'Neto'        FROM  ORIN LEFT JOIN OHEM ON ORIN.SlpCode = OHEM.salesPrson       WHERE ORIN.ObjType='14' AND ORIN.FolioPref='61' AND OHEM.userId=@usuario AND MONTH(ORIN.DocDate)=@mes AND   YEAR(ORIN.DocDate)=@año        end      if @cliente<>''      begin       SELECT OINV.DocEntry,          OINV.DocNum,         OINV.FolioPref,         OINV.FolioNum,          OINV.DocDate,          OINV.DocDueDate,         OINV.U_TAI_CUARTACOPIA  as Doc4taCopia,         OINV.CardCode,          OINV.CardName,          CONVERT(INT, (OINV.DocTotal - OINV.VatSum)) AS 'DocNeto'        FROM  OINV LEFT JOIN OHEM ON OINV.SlpCode = OHEM.salesPrson        WHERE OINV.ObjType='13' AND OINV.FolioPref='33' AND OHEM.userId=@usuario           AND (OINV.CardCode like '' + @cliente + '%' or OINV.CardName like '%' + @cliente + '%' or OINV.LicTradNum like '' + @cliente + '%')            AND MONTH(OINV.DocDate)=@mes AND   YEAR(OINV.DocDate)=@año           UNION         SELECT ORIN.DocEntry,           ORIN.DocNum,           ORIN.FolioPref,          ORIN.FolioNum,           ORIN.DocDate,           ORIN.DocDueDate,           ORIN.U_TAI_CUARTACOPIA        as Doc4taCopia,          ORIN.CardCode,           ORIN.CardName,           CONVERT(INT, (ORIN.DocTotal - ORIN.VatSum)) AS 'Neto'        FROM  ORIN LEFT JOIN OHEM ON ORIN.SlpCode = OHEM.salesPrson        WHERE ORIN.ObjType='14' AND ORIN.FolioPref='61' AND OHEM.userId=@usuario         AND (ORIN.CardCode like '' + @cliente + '%' or ORIN.CardName like '%' + @cliente + '%' or ORIN.LicTradNum like '' + @cliente + '%')          AND MONTH(ORIN.DocDate)=@mes AND   YEAR(ORIN.DocDate)=@año        end    end  END        
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_autorizaciones]   @DocEntry            integer  ,@Concepto            varchar(25)   ,@Estado_Autorizacion integer  ,@Mje_Aut             nvarchar(600)   ,@Rechaza             nvarchar(20)  AS  BEGIN   if @Estado_Autorizacion=1   begin    update tai_tb_autorizaciones       set ContadorCredito  =(case when @Concepto='Creditos'      and ContadorCredito      <>-1 then (case when ContadorCredito      <AutorizacionCredito       then ContadorCredito+1       else ContadorCredito       end) else ContadorCredito       end)       ,ContadorDocProtestado=(case when @Concepto='Protestos'     and ContadorDocProtestado<>-1 then (case when ContadorDocProtestado<AutorizacionDocProtestado then ContadorDocProtestado+1 else ContadorDocProtestado end) else ContadorDocProtestado end)       ,ContadorMargen  =(case when @Concepto='Dscto. Mayor'  and ContadorMargen       <>-1 then (case when ContadorMargen       <AutorizacionMargen        then ContadorMargen+1        else ContadorMargen        end) else ContadorMargen        end)       ,ContadorCosto  =(case when @Concepto='Bajo Costo'    and ContadorCosto        <>-1 then (case when ContadorCosto        <AutorizacionCosto         then ContadorCosto+1         else ContadorCosto         end) else ContadorCosto         end)       ,ContadorFactura  =(case when @Concepto='Deuda Vencida' and ContadorFactura      <>-1 then (case when ContadorFactura      <AutorizacionFactura       then ContadorFactura+1       else ContadorFactura       end) else ContadorFactura       end)       ,ContadorBM1   =(case when @Concepto='BM1'           and ContadorBM1          <>-1 then (case when ContadorBM1          <AutorizacionBM1           then ContadorBM1+1           else ContadorBM1           end) else ContadorBM1           end)       ,ContadorBM2   =(case when @Concepto='BM2'           and ContadorBM2          <>-1 then (case when ContadorBM2          <AutorizacionBM2           then ContadorBM2+1           else ContadorBM2           end) else ContadorBM2           end)       ,ContadorBM3   =(case when @Concepto='BM3'           and ContadorBM3          <>-1 then (case when ContadorBM3          <AutorizacionBM3           then ContadorBM3+1           else ContadorBM3           end) else ContadorBM3           end)       ,ContadorBC1   =(case when @Concepto='BC1'           and ContadorBC1          <>-1 then (case when ContadorBC1          <AutorizacionBC1           then ContadorBC1+1           else ContadorBC1           end) else ContadorBC1           end)       ,ContadorBC2   =(case when @Concepto='BC2'           and ContadorBC2          <>-1 then (case when ContadorBC2          <AutorizacionBC2           then ContadorBC2+1           else ContadorBC2           end) else ContadorBC2           end)       ,ContadorBC3   =(case when @Concepto='BC3'           and ContadorBC3          <>-1 then (case when ContadorBC3          <AutorizacionBC3           then ContadorBC3+1           else ContadorBC3           end) else ContadorBC3           end)     --,Mje_Aut    =''     --,Rechaza    =''       ,ContadorTasa   =(case when @Concepto='Tasa'          and ContadorTasa         <>-1 then (case when ContadorTasa         <AutorizacionTasa          then ContadorTasa+1          else ContadorTasa          end) else ContadorTasa          end)        where DocEntry=@DocEntry   end   else   begin    update tai_tb_autorizaciones       set ContadorCredito  =(case when @Concepto='Creditos'      and ContadorCredito      =0 then -1 else ContadorCredito       end)       ,ContadorDocProtestado=(case when @Concepto='Protestos'     and ContadorDocProtestado=0 then -1 else ContadorDocProtestado end)       ,ContadorMargen  =(case when @Concepto='Dscto. Mayor'  and ContadorMargen       =0 then -1 else ContadorMargen        end)       ,ContadorCosto  =(case when @Concepto='Bajo Costo'    and ContadorCosto        =0 then -1 else ContadorCosto         end)       ,ContadorFactura  =(case when @Concepto='Deuda Vencida' and ContadorFactura      =0 then -1 else ContadorFactura       end)       ,ContadorBM1   =(case when @Concepto='BM1'           and ContadorBM1          =0 then -1 else ContadorBM1           end)       ,ContadorBM2   =(case when @Concepto='BM2'           and ContadorBM2          =0 then -1 else ContadorBM2           end)       ,ContadorBM3   =(case when @Concepto='BM3'           and ContadorBM3          =0 then -1 else ContadorBM3           end)       ,ContadorBC1   =(case when @Concepto='BC1'           and ContadorBC1          =0 then -1 else ContadorBC1           end)       ,ContadorBC2   =(case when @Concepto='BC2'           and ContadorBC2          =0 then -1 else ContadorBC2           end)       ,ContadorBC3   =(case when @Concepto='BC3'           and ContadorBC3          =0 then -1 else ContadorBC3           end)        --,Mje_Aut    =(case when (@Concepto='Creditos'     and ContadorCredito=0) or (@Concepto='Protestos' and ContadorDocProtestado=0) or (@Concepto='Dscto. Mayor' and ContadorMargen=0) or (@Concepto='Bajo Costo' and ContadorCosto=0) or (@Concepto='Deuda Vencida' and ContadorFactura =0) or (@Concepto='BM1' and ContadorBM1=0) or (@Concepto='BM2' and ContadorBM2=0) or (@Concepto='BM3' and ContadorBM3=0) or (@Concepto='BC1' and ContadorBC1=0) or (@Concepto='BC2' and ContadorBC2=0) or (@Concepto='BC3' and ContadorBC3=0) or (@Concepto='Tasa' and ContadorTasa=0) then @Mje_Aut else Mje_Aut end)     --,Rechaza    =(case when (@Concepto='Creditos'     and ContadorCredito=0) or (@Concepto='Protestos' and ContadorDocProtestado=0) or (@Concepto='Dscto. Mayor' and ContadorMargen=0) or (@Concepto='Bajo Costo' and ContadorCosto=0) or (@Concepto='Deuda Vencida' and ContadorFactura =0) or (@Concepto='BM1' and ContadorBM1=0) or (@Concepto='BM2' and ContadorBM2=0) or (@Concepto='BM3' and ContadorBM3=0) or (@Concepto='BC1' and ContadorBC1=0) or (@Concepto='BC2' and ContadorBC2=0) or (@Concepto='BC3' and ContadorBC3=0) or (@Concepto='Tasa' and ContadorTasa=0) then @Rechaza else Rechaza end)       ,ContadorTasa   =(case when @Concepto='Tasa'          and ContadorTasa         =0 then -1 else ContadorTasa          end)        where DocEntry=@DocEntry       update tai_tb_autorizaciones       set ContadorCredito  =(case when AutorizacionCredito      <>ContadorCredito       then -1 else ContadorCredito       end)       ,ContadorDocProtestado=(case when AutorizacionDocProtestado<>ContadorDocProtestado then -1 else ContadorDocProtestado end)       ,ContadorMargen  =(case when AutorizacionMargen       <>ContadorMargen        then -1 else ContadorMargen        end)       ,ContadorCosto  =(case when AutorizacionCosto        <>ContadorCosto         then -1 else ContadorCosto         end)       ,ContadorFactura  =(case when AutorizacionFactura      <>ContadorFactura       then -1 else ContadorFactura       end)       ,ContadorBM1   =(case when AutorizacionBM1          <>ContadorBM1           then -1 else ContadorBM1           end)       ,ContadorBM2   =(case when AutorizacionBM2          <>ContadorBM2           then -1 else ContadorBM2           end)       ,ContadorBM3   =(case when AutorizacionBM3          <>ContadorBM3           then -1 else ContadorBM3           end)       ,ContadorBC1   =(case when AutorizacionBC1          <>ContadorBC1           then -1 else ContadorBC1           end)       ,ContadorBC2   =(case when AutorizacionBC2          <>ContadorBC2           then -1 else ContadorBC2           end)       ,ContadorBC3   =(case when AutorizacionBC3          <>ContadorBC3           then -1 else ContadorBC3           end)       ,Mje_Aut    =@Mje_Aut       ,Rechaza    =@Rechaza       ,ContadorTasa   =(case when AutorizacionTasa         <>ContadorTasa          then -1 else ContadorTasa          end)     where DocEntry=@DocEntry   end   END
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_boleta_venta]   @DocEntry integer  ,@DocNum   integer  AS  BEGIN   update oinv      set UpdInvnt='I'    where DocEntry=@DocEntry       and Docnum  =@DocNum  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_costo_producto_carga]  @opcion int  AS  BEGIN   if @opcion=10    delete from costo_producto_carga   else if @opcion=20   begin    update OITW       set U_TAI_Moneda        =C.ArtMoneda       ,U_TAI_CostoRep      =C.ArtCostoReposicion       ,U_TAI_Flete         =C.ArtCargoFlete       ,U_TAI_Seguro        =C.ArtCargoSeguro       ,U_TAI_FactorLog     =C.ArtCargoLogistico       ,U_TAI_Otros         =C.ArtCargoOtros       ,U_TAI_PorcMargen    =C.ArtPorcentajeMargen       ,U_TAI_CostoComercial=(C.ArtCostoReposicion + C.ArtCargoFlete + (C.ArtCostoReposicion*C.ArtCargoSeguro/100) + (C.ArtCostoReposicion*C.ArtCargoLogistico /100) + (C.ArtCostoReposicion*C.ArtCargoOtros/100))       ,U_TAI_PrecioVenta   =(C.ArtCostoReposicion + C.ArtCargoFlete + (C.ArtCostoReposicion*C.ArtCargoSeguro/100) + (C.ArtCostoReposicion*C.ArtCargoLogistico /100) + (C.ArtCostoReposicion*C.ArtCargoOtros/100))/(1-(C.ArtPorcentajeMargen/100))      from costo_producto_carga C        inner join OITW      W on W.WhsCode=C.BodCodigo and replace(replace(W.ItemCode,char(13),''),char(10),'')=replace(replace(C.ArtCodigo,char(13),''),char(10),'')   end  END
create PROCEDURE [dbo].[tai_vw_sp2_update_costos_productos_carga]  @opcion int  AS  BEGIN   if @opcion=10    delete from TEST   else if @opcion=20   begin    --update OITW     --  set U_TAI_Moneda    =C.U_TAI_Moneda     --  ,U_TAI_CostoRep  =C.U_TAI_CostoRep     --  ,U_TAI_Flete     =C.U_TAI_Flete     --  ,U_TAI_Seguro    =C.U_TAI_Seguro     --  ,U_TAI_FactorLog =C.U_TAI_FactorLog     --  ,U_TAI_Otros     =C.U_TAI_Otros     --  ,U_TAI_PorcMargen=C.U_TAI_PorcMargen     -- from costos_productos_carga  C     --   inner join OITW         W on W.WhsCode=C.WhsCode and W.ItemCode=C.ItemCode     --where W.WhsCode='1' and W.ItemCode='1'       update TEST set ID=999   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_cuarta_copia]   @operador   int  ,@cliente    varchar(15)  ,@tipo       varchar(3)  ,@documento  int  ,@folio      int  ,@ingreso    int  AS  BEGIN   if @tipo='NC'    update ORIN        set U_TAI_cuartacopia=(case when @ingreso=0 then null else getdate() end)     where SlpCode =@operador       and CardCode=@cliente       and DocNum  =@documento       and FolioNum=@folio   else    update OINV       set U_TAI_cuartacopia=(case when @ingreso=0 then null else getdate() end)     where SlpCode =@operador       and CardCode=@cliente       and DocNum  =@documento       and FolioNum=@folio   END
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_dispatcher]   @Id                  nvarchar(64)   ,@Codigo_Autorizador  nvarchar(16)  ,@Tipo_Autorizador    integer  ,@Tipo_Autorizacion   nvarchar(40)  ,@Estado_Autorizacion integer  ,@ComentarioAutoriza  nvarchar(600)  AS  BEGIN  /*   if @Tipo_Autorizador=0   begin    update tai_tb_dispatcher       set Estado_Autorizacion=(case when Estado_Autorizacion<>0 then Estado_Autorizacion else @Estado_Autorizacion end)       ,ComentarioAutoriza =(case when Estado_Autorizacion<>0 then ComentarioAutoriza  else (case when @Estado_Autorizacion=1 then @ComentarioAutoriza else '' end) end)       ,Fecha_Actualizacion=(case when Estado_Autorizacion<>0 then Fecha_Actualizacion else getdate()            end)     where Id                =@Id       and Codigo_Autorizador=@Codigo_Autorizador       and Tipo_Autorizacion =@Tipo_Autorizacion   end   else       begin    update tai_tb_dispatcher       set Estado_Autorizacion=(case when Estado_Autorizacion<>0 then Estado_Autorizacion else @Estado_Autorizacion end)       ,ComentarioAutoriza =(case when Estado_Autorizacion<>0 then ComentarioAutoriza  else (case when @Estado_Autorizacion=1 then @ComentarioAutoriza else '' end) end)       ,Fecha_Actualizacion=(case when Estado_Autorizacion<>0 then Fecha_Actualizacion else getdate()            end)     where Id               =@Id       and Aut_Backup       =@Codigo_Autorizador       and Tipo_Autorizacion=@Tipo_Autorizacion   end  */   update tai_tb_dispatcher      set Estado_Autorizacion=@Estado_Autorizacion      ,ComentarioAutoriza =@ComentarioAutoriza      ,Fecha_Actualizacion=getdate()       where Id                 =@Id      and Estado_Autorizacion=0      and (Codigo_Autorizador=@Codigo_Autorizador or Aut_Backup=@Codigo_Autorizador)      and Tipo_Autorizacion  =@Tipo_Autorizacion     if @Estado_Autorizacion=2   begin    declare @Codigo_Borrador as integer    set @Codigo_Borrador=right(@id,6)  --isnull((select Codigo_Borrador from tai_tb_dispatcher where id=@Id),0)    update tai_tb_dispatcher       set Estado_Autorizacion=@Estado_Autorizacion       ,ComentarioAutoriza ='rechazado automaticamente por '+lower(@Codigo_Autorizador)+'.'       ,Fecha_Actualizacion=getdate()     where Id                <>@Id       and Estado_Autorizacion=0       and Codigo_Borrador    =@Codigo_Borrador   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_estado_borrador]   @DocEntry        integer  ,@U_Estado_Aut    varchar(1)  ,@U_TAI_BloqueaGD integer  AS  BEGIN   update odrf      set U_Estado_Aut   =@U_Estado_Aut         ,U_TAI_BloqueaGD=(case when @U_TAI_BloqueaGD=2 then U_TAI_BloqueaGD else (case when U_TAI_BloqueaGD=1 then U_TAI_BloqueaGD else @U_TAI_BloqueaGD end) end)    where DocEntry=@DocEntry  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_estado_orden]   @DraftKey int  ,@DocNum   int  AS  BEGIN   declare @Estado_Autorizacion int   set @Estado_Autorizacion=isnull((select Estado_Autorizacion from TAI_TB_DISPATCHER where Tipo_Autorizacion='CREDITOS' and codigo_borrador=@DraftKey),0)   if (@Estado_Autorizacion=1)    update ordr       set U_Estado_Aut='A'      where DraftKey=@DraftKey       and DocNum  =@DocNum   else      update ordr       set U_Estado_Aut='P'     where DocNum=@DocNum  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_matriz_descto_detalle]   @opcion    int  ,@sucursal  int  ,@usuario   varchar(10)  ,@reemplazo varchar(10)  AS  BEGIN   if @opcion=10   begin    update matriz_descto_detalle       set det_codusuario =@reemplazo      where det_codusuario =@usuario       and det_codsucursal=@sucursal   end   else if @opcion=20   begin    update matriz_descto_detalle       set det_codbackup  =@reemplazo      where det_codbackup  =@usuario       and det_codsucursal=@sucursal   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_matriz_descto_resumen]   @linea    int  ,@producto nvarchar(50)  ,@nivel0   numeric(6,2)  ,@nivel1   numeric(6,2)  ,@nivel2   numeric(6,2)  ,@nivel3   numeric(6,2)  ,@nivel4   numeric(6,2)  AS  BEGIN   update matriz_descto_resumen      set res_nivel0       =@nivel0         ,res_nivel1       =@nivel1      ,res_nivel2       =@nivel2            ,res_nivel3       =@nivel3            ,res_nivel4       =@nivel4      ,res_actualizacion=getdate()    where res_codlinea   =@linea      and res_codproducto=@producto  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_matriz_descto_resumen_carga]  @opcion int  AS  BEGIN   if @opcion=10    delete from matriz_descto_resumen_carga   else if @opcion=20   begin    insert into matriz_descto_resumen (res_codlinea,res_codproveedor,res_codproducto,res_nivel0,res_nivel1,res_nivel2,res_nivel3,res_nivel4,res_creacion)    select C.LinCodigo       ,C.ProCodigo       ,C.ArtCodigo       ,C.AutNivel0       ,C.AutNivel1       ,C.AutNivel2       ,C.AutNivel3       ,C.AutNivel4       ,getdate()      from matriz_descto_resumen_carga C     where not exists(select R.* from matriz_descto_resumen R where replace(replace(R.res_codproducto,char(13),''),char(10),'')=replace(replace(C.ArtCodigo,char(13),''),char(10),''))      update matriz_descto_resumen       set res_codlinea     =C.LinCodigo       ,res_codproveedor =C.ProCodigo       ,res_nivel0       =C.AutNivel0       ,res_nivel1       =C.AutNivel1       ,res_nivel2       =C.AutNivel2       ,res_nivel3       =C.AutNivel3       ,res_nivel4       =C.AutNivel4       ,res_actualizacion=getdate()      from matriz_descto_resumen_carga      C        inner join matriz_descto_resumen R on replace(replace(R.res_codproducto,char(13),''),char(10),'')=replace(replace(C.ArtCodigo,char(13),''),char(10),'')   end  END
CREATE PROCEDURE [dbo].[tai_vw_sp2_update_orden_compra]   @DocEntry   integer  ,@ItemCode   varchar(50)  ,@DocEntryOV integer  ,@BaseLine   integer  AS  BEGIN   update por1      set BaseEntry=@DocEntryOV         ,BaseLine =@BaseLine         ,BaseType =17     where DocEntry =@DocEntry       and ItemCode =@ItemCode  END